import { test, expect } from '@playwright/test';
import { LoginPage } from '../pages/LoginPage';
import { DashboardPage } from '../pages/DashboardPage';
import { InvestmentPage } from '../pages/InvestmentPage';
import { ConfirmationPage } from '../pages/ConfirmationPage';

test.describe('Complete Investment Purchase Flow', () => {
  test('should complete investment purchase with balance validation', async ({ page }) => {
    // Initialize page objects
    const loginPage = new LoginPage(page);
    const dashboardPage = new DashboardPage(page);
    const investmentPage = new InvestmentPage(page);
    const confirmationPage = new ConfirmationPage(page);

    // Test data
    const user = { email: 'investor@test.com', password: 'SecurePass123' };
    const investment = { symbol: 'AAPL', amount: 5000, type: 'market' };

    // Execute complete investment journey
    await test.step('User authentication', async () => {
      await loginPage.navigate();
      await loginPage.login(user);
      await expect(dashboardPage.welcomeMessage).toBeVisible();

      // Verify session persistence
      await page.reload();
      await expect(dashboardPage.welcomeMessage).toBeVisible();
    });

    await test.step('Account balance verification', async () => {
      const initialBalance = await dashboardPage.getAccountBalance();
      expect(initialBalance).toBeGreaterThan(investment.amount);

      // Verify balance matches backend
      const apiBalance = await dashboardPage.getBalanceFromAPI();
      expect(initialBalance).toBe(apiBalance);
    });

    await test.step('Investment selection and configuration', async () => {
      await dashboardPage.navigateToInvestments();
      await investmentPage.searchInvestment(investment.symbol);
      await investmentPage.selectInvestment(investment.symbol);

      // Validate real-time data
      const currentPrice = await investmentPage.getCurrentPrice();
      expect(currentPrice).toBeGreaterThan(0);

      // Configure purchase
      await investmentPage.enterInvestmentAmount(investment.amount);
      await investmentPage.selectOrderType(investment.type);

      // Preview and validate calculations
      const preview = await investmentPage.getOrderPreview();
      expect(preview.totalAmount).toBe(investment.amount);
      expect(preview.estimatedShares).toBe(investment.amount / currentPrice);
    });

    await test.step('Purchase execution and confirmation', async () => {
      await investmentPage.submitOrder();

      // Validate order processing feedback
      await expect(investmentPage.processingIndicator).toBeVisible();
      await expect(investmentPage.processingIndicator).toBeHidden({ timeout: 30000 });

      // Verify confirmation
      const confirmation = await confirmationPage.getConfirmationDetails();
      expect(confirmation.orderId).toMatch(/ORD\d{8}/);
      expect(confirmation.status).toBe('executed');

      // Validate updated balance
      const updatedBalance = await dashboardPage.getAccountBalance();
      const initialBalance = await dashboardPage.getInitialBalance();
      expect(updatedBalance).toBe(initialBalance - investment.amount);
    });

    await test.step('System-wide validation', async () => {
      // Verify trade recorded in database
      const tradeRecord = await confirmationPage.getTradeFromDB();
      expect(tradeRecord.symbol).toBe(investment.symbol);
      expect(tradeRecord.amount).toBe(investment.amount);

      // Verify confirmation email
      const email = await confirmationPage.getConfirmationEmail();
      expect(email.subject).toContain('Trade Confirmation');

      // Verify analytics tracking
      const analytics = await confirmationPage.getAnalyticsEvent('trade_completed');
      expect(analytics.userId).toBe(user.email);
      expect(analytics.properties.amount).toBe(investment.amount);

      // Verify audit trail
      const auditLog = await confirmationPage.getAuditLog();
      expect(auditLog.action).toBe('trade_execution');
      expect(auditLog.status).toBe('success');
    });
  });
});

