import factory
import factory.fuzzy
from datetime import datetime, timedelta
from random import randint
from models import User, Order, Product, Payment

class UserFactory(factory.Factory):
    class Meta:
        model = User

    id = factory.Sequence(lambda n: n)
    username = factory.Sequence(lambda n: f"user{n}")
    email = factory.LazyAttribute(lambda o: f"{o.username}@example.com")
    first_name = factory.fuzzy.FuzzyText(length=8)
    last_name = factory.fuzzy.FuzzyText(length=10)
    created_at = factory.fuzzy.FuzzyDateTime(
        datetime(2020, 1, 1),
        datetime(2024, 1, 1)
    )
    is_active = factory.fuzzy.FuzzyChoice([True, False])

    @factory.post_generation
    def orders(obj, create, extracted, **kwargs):
        if not create:
            return
        if extracted:
            for order in extracted:
                obj.orders.append(order)
        else:
            # Create some random orders
            for _ in range(randint(0, 5)):
                obj.orders.append(OrderFactory(user=obj))


class ProductFactory(factory.Factory):
    class Meta:
        model = Product

    id = factory.Sequence(lambda n: n)
    name = factory.fuzzy.FuzzyText(length=15)
    description = factory.fuzzy.FuzzyText(length=50)
    price = factory.fuzzy.FuzzyFloat(5.99, 999.99)
    sku = factory.Sequence(lambda n: f"SKU-{n:05d}")
    in_stock = factory.fuzzy.FuzzyChoice([True, False])
    category = factory.fuzzy.FuzzyChoice(['electronics', 'clothing', 'books', 'home'])


class OrderFactory(factory.Factory):
    class Meta:
        model = Order

    id = factory.Sequence(lambda n: n)
    user = factory.SubFactory(UserFactory)
    created_at = factory.fuzzy.FuzzyDateTime(
        datetime(2023, 1, 1),
        datetime(2024, 1, 1)
    )
    status = factory.fuzzy.FuzzyChoice(['pending', 'paid', 'shipped', 'delivered'])

    @factory.post_generation
    def items(obj, create, extracted, **kwargs):
        if not create:
            return
        if extracted:
            for item in extracted:
                obj.items.append(item)
        else:
            # Add 1-5 random items
            for _ in range(randint(1, 5)):
                product = ProductFactory()
                obj.items.append(OrderItemFactory(
                    order=obj,
                    product=product,
                    price=product.price
                ))


class OrderItemFactory(factory.Factory):
    class Meta:
        model = OrderItem

    id = factory.Sequence(lambda n: n)
    order = factory.SubFactory(OrderFactory)
