// Jenkinsfile - Complete CD Pipeline
pipeline {
    agent any

    tools {
        nodejs 'NodeJS-18'
        docker 'latest'
    }

    environment {
        DOCKER_REGISTRY = 'docker.io/myorg'
        DOCKER_IMAGE = "${DOCKER_REGISTRY}/myapp:${BUILD_NUMBER}"
        STAGING_URL = 'https://staging.example.com'
        PRODUCTION_URL = 'https://example.com'
    }

    stages {
        stage('Commit Stage') {
            parallel {
                stage('Lint') {
                    steps {
                        sh 'npm run lint'
                    }
                }
                stage('Type Check') {
                    steps {
                        sh 'npm run type-check'
                    }
                }
                stage('Unit Tests') {
                    steps {
                        sh 'npm run test:unit -- --coverage'
                    }
                    post {
                        always {
                            junit 'junit.xml'
                            publishHTML([
                                reportDir: 'coverage',
                                reportFiles: 'index.html',
                                reportName: 'Coverage Report'
                            ])
                        }
                    }
                }
                stage('Security Scan') {
                    steps {
                        sh 'npm audit'
                    }
                }
            }
        }

        stage('Build and Package') {
            steps {
                sh 'npm run build'
                sh "docker build -t ${DOCKER_IMAGE} ."
                sh "docker push ${DOCKER_IMAGE}"
            }
        }

        stage('Acceptance Tests') {
            parallel {
                stage('Integration Tests') {
                    steps {
                        sh 'docker-compose -f docker-compose.test.yml up -d'
                        sh 'npm run test:integration'
                        sh 'docker-compose -f docker-compose.test.yml down'
                    }
                }
                stage('API Tests') {
                    steps {
                        sh 'npm run test:api'
                    }
                }
                stage('Performance Tests') {
                    steps {
                        sh 'npm run test:performance'
                    }
                }
            }
        }

        stage('Deploy to Staging') {
            steps {
                sh "./deploy.sh staging ${DOCKER_IMAGE}"
            }
            post {
                success {
                    echo "Deployed to staging: ${STAGING_URL}"
                }
            }
        }

        stage('Smoke Tests on Staging') {
            steps {
                sh "npm run test:smoke -- --url=${STAGING_URL}"
            }
        }

        stage('Manual Approval') {
            when {
                branch 'main'
            }
            steps {
                input(
                    message: 'Deploy to production?',
                    ok: 'Deploy',
                    submitter: 'release-managers',
                    parameters: [
                        string(name: 'VERSION', defaultValue: BUILD_NUMBER, description: 'Version to deploy'),
                        choice(name: 'STRATEGY', choices: ['blue-green', 'canary', 'rolling'], description: 'Deployment strategy')
                    ]
                )
            }
        }

        stage('Deploy to Production') {
            steps {
                script {
                    def strategy = params.STRATEGY ?: 'rolling'
                    sh "./deploy.sh production ${DOCKER_IMAGE} --strategy=${strategy}"
                }
            }
            post {
                success {
                    echo "Deployed to production: ${PRODUCTION_URL}"
                }
            }
        }

        stage('Post-Deployment Verification') {
            parallel {
                stage('Smoke Tests') {
                    steps {
                        sh "npm run test:smoke -- --url=${PRODUCTION_URL}"
                    }
                }
                stage('Health Check') {
                    steps {
                        sh "curl -f ${PRODUCTION_URL}/health"
                    }
                }
                stage('Performance Check') {
                    steps {
                        sh "npm run test:performance -- --url=${PRODUCTION_URL}"
                    }
                }
            }
        }
    }

    post {
        failure {
            emailext(
                to: 'team@example.com',
                subject: "Pipeline Failed: ${env.JOB_NAME} - ${env.BUILD_NUMBER}",
                body: "The pipeline failed. Check ${env.BUILD_URL} for details."
            )
            slackSend(
                color: '#FF0000',
                message: "Pipeline Failed: ${env.JOB_NAME} - ${env.BUILD_NUMBER} (<${env.BUILD_URL}|Open>)"
            )
        }
        success {
            slackSend(
                color: '#00FF00',
                message: "Pipeline Succeeded: ${env.JOB_NAME} - ${env.BUILD_NUMBER} deployed to production"
            )
        }
        always {
            cleanWs()
        }
    }
}

