const LaunchDarkly = require('launchdarkly-node-server-sdk');
const Redis = require('ioredis');

class FeatureFlagService {
  constructor() {
    this.client = null;
    this.redis = new Redis(process.env.REDIS_URL);
    this.localCache = new Map();
    this.initialized = false;
  }

  async initialize() {
    // Initialize LaunchDarkly client
    this.client = LaunchDarkly.init(process.env.LAUNCHDARKLY_SDK_KEY);

    await new Promise((resolve, reject) => {
      this.client.once('ready', resolve);
      this.client.once('failed', reject);
    });

    this.initialized = true;
    console.log('Feature flag service initialized');

    // Start background sync
    this.startBackgroundSync();
  }

  async getFlag(flagKey, user, defaultValue = false) {
    if (!this.initialized) {
      return this.getFromCache(flagKey, user.id) || defaultValue;
    }

    try {
      // Evaluate flag for user
      const value = await this.client.variation(flagKey, user, defaultValue);

      // Cache result
      this.cacheValue(flagKey, user.id, value);

      return value;
    } catch (error) {
      console.error(`Error evaluating flag ${flagKey}:`, error);
      return this.getFromCache(flagKey, user.id) || defaultValue;
    }
  }

  async getFlagForUserSegment(flagKey, userId, segment) {
    const user = {
      key: userId,
      custom: {
        segment: segment,
        tier: await this.getUserTier(userId)
      }
    };

    return this.getFlag(flagKey, user, false);
  }

  async getAllFlags(user) {
    if (!this.initialized) {
      return {};
    }

    return this.client.allFlagsState(user);
  }

  cacheValue(flagKey, userId, value) {
    const cacheKey = `flag:${flagKey}:${userId}`;
    this.localCache.set(cacheKey, value);

    // Also cache in Redis with TTL
    this.redis.setex(cacheKey, 300, JSON.stringify(value));
  }

  async getFromCache(flagKey, userId) {
    const cacheKey = `flag:${flagKey}:${userId}`;

    // Check local cache first
    if (this.localCache.has(cacheKey)) {
      return this.localCache.get(cacheKey);
    }

    // Check Redis
    const cached = await this.redis.get(cacheKey);
    if (cached) {
      const value = JSON.parse(cached);
      this.localCache.set(cacheKey, value);
      return value;
    }

    return null;
  }

  async getUserTier(userId) {
    // Get user tier from database
    const user = await db.users.findById(userId);
    return user?.tier || 'free';
  }

  startBackgroundSync() {
    // Refresh cache periodically
    setInterval(() => {
      this.localCache.clear();
    }, 60000); // Clear local cache every minute
  }

  // Flag management methods
  async createFlag(flagKey, description, variations) {
    // This would use LaunchDarkly API
    console.log(`Creating flag: ${flagKey}`);
  }

  async updateFlagTargeting(flagKey, targetingRules) {
    // Update flag targeting rules
    console.log(`Updating targeting for: ${flagKey}`);
  }

  async deleteFlag(flagKey) {
    // Clean up old flag
    console.log(`Deleting flag: ${flagKey}`);
  }
}

