    const useNewCheckout = await this.flags.getFlag(
      'new-checkout-flow',
      user,
      false
    );

    if (useNewCheckout) {
      return this.processNewCheckout(userId, cart);
    } else {
      return this.processLegacyCheckout(userId, cart);
    }
  }

