    const user = { key: userId };

    // Check for premium user discount
    const discountPercent = await this.flags.getFlagForUserSegment(
      'premium-discount',
      userId,
      'premium'
    );

    if (discountPercent) {
      return amount * (1 - discountPercent / 100);
    }

    return amount;
  }

  async processNewCheckout(userId, cart) {
    // New checkout implementation
    console.log('Processing with new checkout flow');

    // Feature flags for sub-features
    const flags = await this.flags.getAllFlags({ key: userId });

    if (flags.oneClickCheckout) {
      return this.oneClickCheckout(userId, cart);
