    if (flags.savePaymentMethod) {
      await this.savePaymentMethod(userId, cart.paymentMethod);
    }

    return this.standardCheckout(userId, cart);
  }

  processLegacyCheckout(userId, cart) {
    console.log('Processing with legacy checkout flow');
    return this.standardCheckout(userId, cart);
  }

