// jenkins-cd-pipeline.groovy
pipeline {
    agent any

    environment {
        // Docker registry
        DOCKER_REGISTRY = 'docker.io/myorg'
        DOCKER_IMAGE = "${DOCKER_REGISTRY}/myapp:${BUILD_NUMBER}"

        // Kubernetes contexts
        KUBE_CONFIG = credentials('kubernetes-config')

        // Deployment strategies
        BLUE_NS = 'production-blue'
        GREEN_NS = 'production-green'
    }

    stages {
        stage('Build and Test') {
            parallel {
                stage('Lint') {
                    steps {
                        sh 'npm run lint'
                    }
                }
                stage('Unit Tests') {
                    steps {
                        sh 'npm test'
                    }
                    post {
                        always {
                            junit 'junit.xml'
                        }
                    }
                }
            }
        }

        stage('Build Docker Image') {
            steps {
                script {
                    docker.build(DOCKER_IMAGE)
                }
            }
        }

        stage('Push to Registry') {
            steps {
                script {
                    docker.withRegistry('', 'docker-hub-credentials') {
                        docker.image(DOCKER_IMAGE).push()
                    }
                }
            }
        }

        stage('Deploy to Staging') {
            steps {
                sh """
                    kubectl set image deployment/myapp \
                        myapp=${DOCKER_IMAGE} \
                        -n staging
                    kubectl rollout status deployment/myapp -n staging
                """
            }
        }

        stage('Smoke Tests') {
            steps {
                sh 'npm run test:smoke -- --url=https://staging.example.com'
            }
        }

        stage('Integration Tests') {
            steps {
                sh 'npm run test:integration'
            }
        }

        stage('Performance Tests') {
            steps {
                sh 'npm run test:performance'
            }
        }

        stage('Manual Approval') {
            when {
                branch 'main'
            }
            steps {
                input(
                    message: 'Deploy to production?',
                    ok: 'Deploy',
                    parameters: [
                        choice(
                            name: 'STRATEGY',
                            choices: ['blue-green', 'rolling'],
                            description: 'Deployment strategy'
                        )
                    ]
                )
            }
        }

        stage('Blue-Green Deployment') {
            when {
                expression { params.STRATEGY == 'blue-green' }
            }
            steps {
                script {
                    // Determine active namespace
                    def activeNs = sh(
                        script: "kubectl get ns -l active=true -o jsonpath='{.items[0].metadata.name}'",
                        returnStdout: true
                    ).trim()

                    def targetNs = activeNs == BLUE_NS ? GREEN_NS : BLUE_NS

                    // Deploy to inactive namespace
                    sh """
                        kubectl set image deployment/myapp \
                            myapp=${DOCKER_IMAGE} \
                            -n ${targetNs}
                        kubectl rollout status deployment/myapp -n ${targetNs}
                    """

                    // Run smoke tests
                    sh "npm run test:smoke -- --url=http://${targetNs}.example.com"

                    // Switch traffic
                    sh """
                        kubectl label ns ${activeNs} active- || true
                        kubectl label ns ${targetNs} active=true --overwrite
                        kubectl label ns ${activeNs} active- || true
                        kubectl rollout restart ingress -n production
                    """
                }
            }
        }

        stage('Rolling Update') {
            when {
                expression { params.STRATEGY == 'rolling' }
            }
            steps {
                sh """
                    kubectl set image deployment/myapp \
                        myapp=${DOCKER_IMAGE} \
                        -n production
                    kubectl rollout status deployment/myapp -n production
                """
            }
        }

        stage('Post-Deployment Verification') {
            parallel {
                stage('Health Check') {
                    steps {
                        sh 'curl -f https://example.com/health'
                    }
                }
                stage('Smoke Tests') {
                    steps {
                        sh 'npm run test:smoke -- --url=https://example.com'
                    }
                }
                stage('Database Migration Check') {
                    steps {
                        sh 'npm run db:verify'
                    }
                }
            }
        }
    }

    post {
        success {
            emailext(
                to: 'team@example.com',
                subject: "Deployment Successful: ${env.JOB_NAME} - ${env.BUILD_NUMBER}",
                body: "Application deployed to production successfully."
            )
            slackSend(
                color: 'good',
                message: "Deployment Successful: ${env.JOB_NAME} - ${env.BUILD_NUMBER}"
            )
        }
        failure {
            emailext(
                to: 'team@example.com',
                subject: "Deployment Failed: ${env.JOB_NAME} - ${env.BUILD_NUMBER}",
                body: "Deployment failed. Check ${env.BUILD_URL} for details."
            )
            slackSend(
                color: 'danger',
                message: "Deployment Failed: ${env.JOB_NAME} - ${env.BUILD_NUMBER}"
            )
        }
    }
}

