export const options = {
  // Load profile: ramp up, stay, ramp down
  stages: [
    { duration: '2m', target: 100 },  // Ramp up to 100 users
    { duration: '5m', target: 100 },  // Stay at 100 users
    { duration: '2m', target: 200 },  // Ramp up to 200 users
    { duration: '5m', target: 200 },  // Stay at 200 users
    { duration: '2m', target: 300 },  // Ramp up to 300 users
    { duration: '5m', target: 300 },  // Stay at 300 users
    { duration: '2m', target: 0 },    // Ramp down to 0
  ],

  // Thresholds (SLOs)
  thresholds: {
    http_req_duration: ['p(95)<500', 'p(99)<1000'], // 95% under 500ms, 99% under 1s
    http_req_failed: ['rate<0.01'], // Less than 1% errors
    'db_query_duration': ['p(95)<200'], // Custom metric threshold
  },
};

// Custom metrics
const dbQueryTrend = new Trend('db_query_duration');
const errorRate = new Rate('errors');
const apiCalls = new Counter('api_calls');

// Base URL from environment variable
const BASE_URL = __ENV.API_BASE_URL || 'https://api.example.com';

// Test setup - runs once per VU
function setup() {
  // Authenticate and get token
  const loginRes = http.post(`${BASE_URL}/auth/login`, JSON.stringify({
    username: 'testuser',
    password: 'testpass123'
  }), {
    headers: { 'Content-Type': 'application/json' }
  });

  check(loginRes, { 'login successful': (r) => r.status === 200 });

  return { token: loginRes.json('token') };
}

export default function(data) {
  const headers = {
    'Authorization': `Bearer ${data.token}`,
    'Content-Type': 'application/json'
  };

  // Scenario 1: Get users list
  {
    const start = Date.now();
    const res = http.get(`${BASE_URL}/api/users?page=1&limit=20`, { headers });

    // Record custom duration
    dbQueryTrend.add(Date.now() - start);

    // Check response
    const success = check(res, {
      'users list status 200': (r) => r.status === 200,
      'users list has data': (r) => r.json('data') && r.json('data').length > 0,
    });

    errorRate.add(!success);
    apiCalls.add(1);

    sleep(Math.random() * 2); // Random think time 0-2s
  }

  // Scenario 2: Get specific user
  {
    const userId = Math.floor(Math.random() * 1000) + 1;
    const res = http.get(`${BASE_URL}/api/users/${userId}`, { headers });

    check(res, {
      'user detail status 200': (r) => r.status === 200,
      'user has id': (r) => r.json('id') === userId,
    });

    sleep(1);
  }

  // Scenario 3: Create user (10% of requests)
  if (Math.random() < 0.1) {
    const newUser = {
      name: `Test User ${Date.now()}`,
      email: `user${Date.now()}@example.com`,
      role: 'user'
    };

    const res = http.post(`${BASE_URL}/api/users`, JSON.stringify(newUser), { headers });

    check(res, {
      'create user status 201': (r) => r.status === 201,
      'user created': (r) => r.json('id') !== undefined,
    });

    if (res.status === 201) {
      const userId = res.json('id');

      // Update user
      const updateRes = http.put(`${BASE_URL}/api/users/${userId}`, JSON.stringify({
        role: 'premium'
      }), { headers });

      check(updateRes, { 'update user status 200': (r) => r.status === 200 });
    }
  }

  sleep(2);
}

// Test teardown - runs once after test
export function teardown(data) {
  // Cleanup test data
  http.del(`${BASE_URL}/api/test/cleanup`, null, {
    headers: { 'Authorization': `Bearer ${data.token}` }
  });
}

