import com.zaxxer.hikari.HikariConfig;
import com.zaxxer.hikari.HikariDataSource;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

import javax.sql.DataSource;
import java.sql.Connection;
import java.sql.SQLException;
import java.util.concurrent.TimeUnit;

@Configuration
public class DatabaseConfig {

    @Bean
    public DataSource dataSource() {
        HikariConfig config = new HikariConfig();

        // Database connection settings
        config.setJdbcUrl("jdbc:postgresql://localhost:5432/ecommerce");
        config.setUsername("app_user");
        config.setPassword("secure_password");
        config.setDriverClassName("org.postgresql.Driver");

        // Connection pool settings - increased from 50 to 100
        config.setMaximumPoolSize(100);
        config.setMinimumIdle(20);
        config.setIdleTimeout(300000); // 5 minutes
        config.setConnectionTimeout(30000); // 30 seconds (was 0 - infinite)
        config.setMaxLifetime(600000); // 10 minutes

        // Validation settings
        config.setConnectionTestQuery("SELECT 1");
        config.setValidationTimeout(5000);
        config.setLeakDetectionThreshold(10000); // Log if connection held >10s

        // Performance settings
        config.addDataSourceProperty("cachePrepStmts", "true");
        config.addDataSourceProperty("prepStmtCacheSize", "250");
        config.addDataSourceProperty("prepStmtCacheSqlLimit", "2048");

        // Metrics (for monitoring)
        config.setMetricRegistry(myMetricRegistry);

        return new HikariDataSource(config);
    }

    // Fixed connection usage with try-with-resources
    public Order getOrderById(long orderId) throws SQLException {
        String sql = "SELECT * FROM orders WHERE id = ?";

        // try-with-resources ensures connection is closed automatically
        try (Connection conn = dataSource().getConnection();
             PreparedStatement stmt = conn.prepareStatement(sql)) {

            stmt.setLong(1, orderId);

            try (ResultSet rs = stmt.executeQuery()) {
                if (rs.next()) {
                    return mapOrder(rs);
                }
            }
        } // Connection automatically closed here, even with exceptions

        return null;
    }

    // Fixed transaction boundary - external API call outside transaction
    @Transactional
    public Order processOrder(OrderRequest request) {
        // Database operations within transaction
        Order order = createOrder(request);
        updateInventory(request.getItems());

        // Transaction commits here

        // External API call AFTER transaction commits
        notifyExternalSystem(order); // No longer holding connection

        return order;
    }

    // Monitoring bean to track pool usage
    @Bean
    public ConnectionPoolMonitor connectionPoolMonitor(DataSource dataSource) {
        return new ConnectionPoolMonitor((HikariDataSource) dataSource);
    }
}

class ConnectionPoolMonitor {
    private final HikariDataSource dataSource;

    public ConnectionPoolMonitor(HikariDataSource dataSource) {
        this.dataSource = dataSource;
        startMonitoring();
    }

    private void startMonitoring() {
        ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(1);
        scheduler.scheduleAtFixedRate(() -> {
            HikariPoolMXBean poolMXBean = dataSource.getHikariPoolMXBean();

            int activeConnections = poolMXBean.getActiveConnections();
            int idleConnections = poolMXBean.getIdleConnections();
            int totalConnections = poolMXBean.getTotalConnections();
            int threadsAwaiting = poolMXBean.getThreadsAwaitingConnection();

            // Log metrics
            log.info("Connection Pool - Active: {}, Idle: {}, Total: {}, Awaiting: {}",
                activeConnections, idleConnections, totalConnections, threadsAwaiting);

            // Alert if nearing capacity
            if (activeConnections > dataSource.getMaximumPoolSize() * 0.8) {
                alertService.sendAlert("Connection pool nearing capacity: " + 
                    activeConnections + "/" + dataSource.getMaximumPoolSize());
            }

            // Check for leaks
            if (activeConnections > dataSource.getMaximumPoolSize() * 0.9) {
                // Force a leak detection report
                System.gc(); // Hint for leak detection
            }
        }, 0, 10, TimeUnit.SECONDS);
    }
}

// CacheFix.java
import com.google.common.cache.CacheBuilder;
import com.google.common.cache.CacheLoader;
import com.google.common.cache.LoadingCache;
import com.google.common.cache.RemovalListener;
import com.google.common.cache.RemovalNotification;
import org.springframework.stereotype.Component;

import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicLong;

@Component
public class DocumentCache {

    // Before: Simple HashMap with no eviction (the problem)
    // private Map<String, Document> cache = new HashMap<>();

    // After: Guava cache with proper eviction
    private final LoadingCache<String, Document> cache;
    private final AtomicLong hitCount = new AtomicLong();
    private final AtomicLong missCount = new AtomicLong();
    private final AtomicLong evictionCount = new AtomicLong();

    public DocumentCache() {
        cache = CacheBuilder.newBuilder()
            .maximumSize(100)  // Maximum 100 entries
            .maximumWeight(500 * 1024 * 1024) // Or 500MB total
            .weigher((key, value) -> ((Document) value).getSizeInBytes())
            .expireAfterAccess(1, TimeUnit.HOURS) // Remove after 1 hour of no access
            .expireAfterWrite(2, TimeUnit.HOURS) // Remove after 2 hours regardless
            .softValues() // Allow GC to reclaim if memory pressure
            .recordStats() // Track hit/miss rates
            .removalListener(new RemovalListener<String, Document>() {
                @Override
                public void onRemoval(RemovalNotification<String, Document> notification) {
                    evictionCount.incrementAndGet();
                    log.info("Cache entry removed: {}, reason: {}", 
                        notification.getKey(), notification.getCause());

                    // Clean up any resources
                    Document doc = notification.getValue();
                    if (doc != null) {
                        doc.cleanup();
                    }
                }
            })
            .build(new CacheLoader<String, Document>() {
                @Override
                public Document load(String key) throws Exception {
                    // This is called on cache miss
                    missCount.incrementAndGet();
                    return loadDocumentFromDatabase(key);
                }
            });
    }

    public Document getDocument(String documentId) {
        try {
            Document doc = cache.get(documentId);
            hitCount.incrementAndGet();
            return doc;
        } catch (Exception e) {
            log.error("Error loading document: {}", documentId, e);
            return null;
        }
    }

    public void invalidateDocument(String documentId) {
        cache.invalidate(documentId);
    }

    public void invalidateAll() {
        cache.invalidateAll();
    }

    // Cache statistics for monitoring
    public CacheStats getStats() {
        com.google.common.cache.CacheStats stats = cache.stats();

        return new CacheStats(
            stats.hitCount(),
            stats.missCount(),
            stats.evictionCount(),
            stats.loadTime(TimeUnit.MILLISECONDS),
            cache.size()
        );
    }

    // Alternative: Caffeine cache (newer, better performance)
    /*
    @Bean
    public Cache<String, Document> caffeineCache() {
        return Caffeine.newBuilder()
            .maximumSize(100)
            .expireAfterAccess(1, TimeUnit.HOURS)
            .recordStats()
            .removalListener((key, value, cause) -> {
                log.info("Removed {} because {}", key, cause);
            })
            .build();
    }
    */

    // Scheduled cache cleanup (if needed)
    @Scheduled(fixedDelay = 300000) // Every 5 minutes
    public void cleanupCache() {
        cache.cleanUp(); // Performs any pending maintenance operations

        CacheStats stats = getStats();
        log.info("Cache stats - Size: {}, Hits: {}, Misses: {}, Evictions: {}",
            stats.size(), stats.hits(), stats.misses(), stats.evictions());

        // Alert if hit rate is low
        double hitRate = stats.hitRate();
        if (hitRate < 0.5) {
            alertService.sendAlert("Low cache hit rate: " + hitRate);
        }
    }
}

// Record class for cache stats
record CacheStats(long hits, long misses, long evictions, long loadTimeMs, long size) {
    public double hitRate() {
        long total = hits + misses;
        return total == 0 ? 0 : (double) hits / total;
    }
}

