public User GetUserById(int userId) {
    using (var cmd = new SqlCommand("SELECT * FROM users WHERE id = @id", connection)) {
        cmd.Parameters.AddWithValue("@id", userId);
        using (var reader = cmd.ExecuteReader()) {
            if (reader.Read()) {
                return MapUser(reader);
            }
        }
    }
    return null;
}


