class SafeDOMHandler {
    constructor() {
        this.sanitizeInput();
    }

    sanitizeInput() {
        // Get URL parameters safely
        const urlParams = new URLSearchParams(window.location.search);

        // For each parameter, sanitize before using
        urlParams.forEach((value, key) => {
            // Option 1: Use textContent (safest)
            const element = document.getElementById(key);
            if (element) {
                element.textContent = value;
            }

            // Option 2: Use DOMPurify if you MUST allow some HTML
            // element.innerHTML = DOMPurify.sanitize(value);
        });

        // Handle hash safely
        if (location.hash) {
            const hashValue = location.hash.substring(1);
            const hashElement = document.getElementById('hash-content');
            if (hashElement) {
                hashElement.textContent = hashValue;
            }
        }
    }
}

