// ===== HTML CONTEXT ENCODING =====
function encodeForHTML(input) {
    if (input === null || input === undefined) return '';
    return String(input)
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#x27;')
        .replace(/\//g, '&#x2F;');
}

// ===== HTML ATTRIBUTE CONTEXT ENCODING =====
function encodeForHTMLAttribute(input) {
    // Same as HTML encoding, but ensure attribute is quoted
    return encodeForHTML(input);
}

// ===== JAVASCRIPT STRING CONTEXT ENCODING =====
function encodeForJavaScriptString(input) {
    if (input === null || input === undefined) return '';
    return String(input)
        .replace(/\\/g, '\\\\')
        .replace(/'/g, "\\'")
        .replace(/"/g, '\\"')
        .replace(/\n/g, '\\n')
        .replace(/\r/g, '\\r')
        .replace(/\t/g, '\\t')
        .replace(/<\/script>/gi, '<\\/script>'); // Break out of script tag
}

// ===== URL CONTEXT ENCODING =====
function encodeForURL(input) {
    return encodeURIComponent(input);
}

// ===== CSS CONTEXT ENCODING =====
function encodeForCSS(input) {
    if (input === null || input === undefined) return '';
    // Basic CSS escaping - not comprehensive
    return String(input).replace(/[^a-zA-Z0-9]/g, function(match) {
        return '\\' + match.charCodeAt(0).toString(16) + ' ';
    });
}

// ===== COMPREHENSIVE SANITIZER =====
class XSSSafe {
    constructor() {
        this.allowedTags = ['b', 'i', 'em', 'strong', 'a', 'p', 'br'];
        this.allowedAttributes = ['href', 'title'];
    }

    sanitizeHTML(input) {
        // For when you MUST allow some HTML (use with extreme caution)
        // In production, use a well-tested library like DOMPurify
        // This is a simplified example

        if (!input) return '';

        // First, encode everything
        let encoded = encodeForHTML(input);

        // Then, selectively decode allowed tags (INSECURE - DEMO ONLY)
        this.allowedTags.forEach(tag => {
            const openTag = `&lt;${tag}&gt;`;
            const closeTag = `&lt;/${tag}&gt;`;
            encoded = encoded.replace(new RegExp(openTag, 'g'), `<${tag}>`);
            encoded = encoded.replace(new RegExp(closeTag, 'g'), `</${tag}>`);
        });

        return encoded;
    }

    // Safe rendering methods
    renderText(elementId, text) {
        const element = document.getElementById(elementId);
        if (element) {
            element.textContent = text; // Safest
        }
    }

    renderHTML(elementId, html) {
        const element = document.getElementById(elementId);
        if (element) {
            // ONLY use if you've sanitized with a library like DOMPurify
            // element.innerHTML = DOMPurify.sanitize(html);
            console.warn('Avoid innerHTML with untrusted data');
        }
    }
}

