# Content Security Policy Examples

# ===== BASIC CSP =====
# Allow scripts only from same origin, no inline scripts
Content-Security-Policy: default-src 'self'; script-src 'self'; object-src 'none'

# ===== STRICT CSP (Recommended) =====
# Strict CSP using nonces - most secure against XSS
Content-Security-Policy: default-src 'self'; script-src 'nonce-{random}' 'strict-dynamic' https:; object-src 'none'; base-uri 'self'

# ===== WITH REPORTING =====
# Report violations but don't block (useful during rollout)
Content-Security-Policy-Report-Only: default-src 'self'; script-src 'self'; report-uri /csp-report

# ===== COMPREHENSIVE CSP =====
Content-Security-Policy: 
    default-src 'none';
    script-src 'self' https://trusted-cdn.com 'nonce-abc123';
    style-src 'self' 'unsafe-inline';
    img-src 'self' data: https://*.imgur.com;
    font-src 'self' https://fonts.googleapis.com;
    connect-src 'self' https://api.example.com;
