# ===== DEFENSE 1: Custom Header Validation =====

@app.before_request
def check_custom_header():
    """Require custom header for state-changing requests"""
    if request.method in ['POST', 'PUT', 'DELETE', 'PATCH']:
        # Check for custom header
        requested_with = request.headers.get('X-Requested-With')
        if requested_with != 'XMLHttpRequest':
            # Allow form submissions with CSRF token instead
            token = request.form.get('csrf_token')
            if not validate_token(token):
                abort(403, description="Missing required CSRF protection")


# ===== DEFENSE 2: Origin/Referer Validation =====

ALLOWED_ORIGINS = ['https://example.com', 'https://www.example.com']

def validate_origin():
    """Validate Origin or Referer header"""
    origin = request.headers.get('Origin')
    referer = request.headers.get('Referer')

    # Check Origin first (more reliable)
    if origin:
        if origin not in ALLOWED_ORIGINS:
            abort(403, description="Invalid origin")
    # Fall back to Referer
    elif referer:
        # Extract scheme + hostname from referer
        from urllib.parse import urlparse
        parsed = urlparse(referer)
        referer_origin = f"{parsed.scheme}://{parsed.netloc}"
        if referer_origin not in ALLOWED_ORIGINS:
            abort(403, description="Invalid referer")
    else:
        # No origin/referer - reject for state-changing requests
        if request.method in ['POST', 'PUT', 'DELETE', 'PATCH']:
            abort(403, description="Missing origin/referer header")


# ===== DEFENSE 3: Re-authentication for Critical Actions =====

