# ===== DEFENSE 5: Stateless Encrypted Tokens =====

from cryptography.fernet import Fernet
import base64

class EncryptedCSRFToken:
    def __init__(self, key=None):
        if key is None:
            key = Fernet.generate_key()
        self.cipher = Fernet(key)

    def generate_token(self, user_id, session_id):
        """Generate encrypted token containing user context"""
        data = f"{user_id}:{session_id}:{time.time()}"
        return self.cipher.encrypt(data.encode()).decode()

    def validate_token(self, token, user_id, session_id, max_age=3600):
        """Decrypt and validate token"""
        try:
            decrypted = self.cipher.decrypt(token.encode()).decode()
            token_user_id, token_session_id, timestamp = decrypted.split(':')

            # Validate user and session
            if token_user_id != user_id or token_session_id != session_id:
                return False

            # Check age
            if float(timestamp) < time.time() - max_age:
                return False

            return True
        except Exception:
            return False

encrypted_csrf = EncryptedCSRFToken()


# ===== DEFENSE 6: HMAC-Based Stateless Token =====

def generate_hmac_token(user_id, session_id, action):
    """Generate HMAC token bound to specific action"""
    message = f"{user_id}:{session_id}:{action}:{int(time.time() / 300)}"  # 5-minute window
    signature = hmac.new(
        app.secret_key.encode(),
        message.encode(),
        hashlib.sha256
    ).hexdigest()
    return f"{message}:{signature}"

def validate_hmac_token(token, user_id, session_id, action):
    """Validate HMAC token"""
    try:
        parts = token.split(':')
        if len(parts) != 5:  # user_id:session_id:action:time_window:signature
            return False

        token_user, token_session, token_action, time_window, signature = parts

        # Verify components
        if token_user != user_id or token_session != session_id or token_action != action:
            return False

        # Recompute signature
        expected_message = f"{token_user}:{token_session}:{token_action}:{time_window}"
        expected_signature = hmac.new(
            app.secret_key.encode(),
            expected_message.encode(),
            hashlib.sha256
        ).hexdigest()

        return hmac.compare_digest(signature, expected_signature)
    except Exception:
        return False


# ===== COMPLETE CSRF PROTECTION MIDDLEWARE =====

def csrf_protection(f):
    """Comprehensive CSRF protection decorator"""
    @wraps(f)
    def decorated(*args, **kwargs):
        if request.method in ['POST', 'PUT', 'DELETE', 'PATCH']:
            # Defense 1: SameSite cookie check (browser-level)
            # (already handled by cookie settings)

            # Defense 2: Origin/Referer validation
            validate_origin()

            # Defense 3: CSRF token validation
            token = (
                request.form.get('csrf_token') or
                request.headers.get('X-CSRF-Token') or
                request.cookies.get('csrf_token')
            )

            if not token:
                abort(403, description="Missing CSRF token")

            # Validate token (choose your method)
            if not validate_hmac_token(token, session['user_id'], session['session_id'], request.endpoint):
                abort(403, description="Invalid CSRF token")

            # Defense 4: Re-authentication for critical actions
            if request.endpoint in ['change_password', 'transfer_large']:
                if not request.headers.get('X-Reauthenticated'):
                    abort(403, description="Re-authentication required")

        return f(*args, **kwargs)
    return decorated

