const jwt = require('jsonwebtoken');

// NEVER store sensitive data like roles in a client-side JWT without a server-side fallback.
// Always verify the signature.

function authenticateToken(req, res, next) {
    const authHeader = req.headers['authorization'];
    const token = authHeader && authHeader.split(' ')[1]; // Bearer TOKEN

    if (token == null) return res.sendStatus(401);

    jwt.verify(token, process.env.ACCESS_TOKEN_SECRET, (err, user) => {
        if (err) {
            // Differentiate between expired and invalid
            if (err.name === 'TokenExpiredError') {
                return res.status(401).json({ error: 'Token expired' });
            }
            return res.sendStatus(403); // Invalid token
        }

        // Attach user payload to request. This payload should be minimal (e.g., user ID).
        // DO NOT rely on `user.role` from the token for every authorization decision.
        // Fetch the user's current role/permissions from the DB/session here or in the authorize middleware.
        req.user = { id: user.userId }; 
        next();
    });
}

// Best Practices:
// 1. Use short-lived access tokens (e.g., 15 minutes).
// 2. Use refresh tokens stored in HttpOnly cookies for obtaining new access tokens.
// 3. Implement a token revocation list (e.g., in Redis) for critical scenarios like logout or password change.
// 4. Keep the JWT payload small. Store only a nonce or a session ID that can be cross-referenced server-side for permissions.

// Example: Stateless but Revocable Pattern
// 1. Generate JWT with `{ jti: 'unique-session-id', sub: userId }`
// 2. On logout/password change, add `jti` to a denylist in Redis until its natural expiry.
// 3. In `authenticateToken`, after verifying the JWT, check if its `jti` is in the denylist.
//    If yes, reject the token.

