// FLAKY PATTERN: Hard-coded waits
// ===========================================
// This is brittle. The element might load in 200ms or 2000ms.
// If it's slower than 1 second, the test fails.

cy.visit('/dashboard');
cy.wait(1000); // Bad: Arbitrary wait
cy.get('.user-profile').should('be.visible');


// ===========================================
// STABLE PATTERN: Explicit, intelligent waits
// ===========================================
// The test waits for the exact condition it needs.
// It will pass as soon as the element is available, regardless of timing.

cy.visit('/dashboard');

// Good: Explicitly wait for the network request to complete
cy.intercept('GET', '/api/user').as('getUser');
cy.wait('@getUser'); // Waits for the API call

// Better: Wait for the element itself with built-in retry
cy.get('.user-profile', { timeout: 10000 }) // Waits up to 10s
  .should('be.visible');


