# LOGIN PAGE OBJECT
# ===========================================
from selenium.webdriver.common.by import By

class LoginPage(BasePage):
    # Locators - stored as tuples, defined in one place
    USERNAME_INPUT = (By.ID, "username")
    PASSWORD_INPUT = (By.ID, "password")
    LOGIN_BUTTON = (By.CSS_SELECTOR, "button[type='submit']")
    ERROR_MESSAGE = (By.CLASS_NAME, "error")
    FORGOT_PASSWORD_LINK = (By.LINK_TEXT, "Forgot Password?")

    def __init__(self, driver):
        super().__init__(driver)
        # Optional: Verify we're on the correct page
        assert "Login" in self.driver.title, "Not on login page"

    # Page-specific actions
    def enter_username(self, username):
        element = self.wait_for_element(*self.USERNAME_INPUT)
        element.clear()
        element.send_keys(username)
        return self  # For method chaining

    def enter_password(self, password):
        self.find_element(*self.PASSWORD_INPUT).send_keys(password)
        return self

    def click_login(self):
        self.find_element(*self.LOGIN_BUTTON).click()
        # After clicking, we may navigate to a new page
        from pages.dashboard_page import DashboardPage  # Avoid circular import
        return DashboardPage(self.driver)

    def login_as(self, username, password):
        """High-level workflow method"""
        return (self.enter_username(username)
                .enter_password(password)
                .click_login())

    def get_error_message(self):
        return self.find_element(*self.ERROR_MESSAGE).text

    def is_error_displayed(self):
        return len(self.driver.find_elements(*self.ERROR_MESSAGE)) > 0


# ===========================================
# DASHBOARD PAGE OBJECT
# ===========================================
class DashboardPage(BasePage):
    WELCOME_MESSAGE = (By.ID, "welcome-message")
    USER_MENU = (By.ID, "user-menu")
    LOGOUT_LINK = (By.LINK_TEXT, "Logout")

    def get_welcome_text(self):
        return self.wait_for_element(*self.WELCOME_MESSAGE).text

    def logout(self):
        self.find_element(*self.USER_MENU).click()
        self.wait_for_element(*self.LOGOUT_LINK).click()
        return LoginPage(self.driver)


