import org.testng.ITestContext;
import org.testng.ITestListener;
import org.testng.ITestResult;

public class ScreenshotListener implements ITestListener {

    @Override
    public void onTestStart(ITestResult result) {
        System.out.println("Starting test: " + result.getName());
    }

    @Override
    public void onTestSuccess(ITestResult result) {
        System.out.println("Test passed: " + result.getName());
    }

    @Override
    public void onTestFailure(ITestResult result) {
        System.out.println("Test failed: " + result.getName());
        // Get the driver instance from the test class (assuming it's stored)
        Object testInstance = result.getInstance();
        try {
            // Assuming the test class has a getDriver() method
            WebDriver driver = (WebDriver) testInstance.getClass().getMethod("getDriver").invoke(testInstance);
            if (driver != null) {
                String fileName = "screenshot_" + result.getName() + "_" + System.currentTimeMillis() + ".png";
                File screenshot = ((TakesScreenshot) driver).getScreenshotAs(OutputType.FILE);
                FileUtils.copyFile(screenshot, new File("test-output/screenshots/" + fileName));
                System.out.println("Screenshot saved: " + fileName);
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    @Override
    public void onTestSkipped(ITestResult result) {
        System.out.println("Test skipped: " + result.getName());
    }

    @Override
    public void onFinish(ITestContext context) {
        System.out.println("Test suite finished: " + context.getName());
    }
}

