import static org.hamcrest.MatcherAssert.assertThat;
import static org.hamcrest.Matchers.*;
import org.junit.jupiter.api.Test;
import java.util.Arrays;
import java.util.List;
import java.util.Map;

public class HamcrestTest {

    @Test
    void testStringMatchers() {
        String actual = "Hello World";

        assertThat(actual, startsWith("Hello"));
        assertThat(actual, endsWith("World"));
        assertThat(actual, containsString("lo Wo"));
        assertThat(actual, equalToIgnoringCase("HELLO WORLD"));
        assertThat(actual, allOf(
            startsWith("Hello"),
            containsString("World"),
            length(is(11))
        ));
    }

    @Test
    void testCollectionMatchers() {
        List<String> fruits = Arrays.asList("apple", "banana", "cherry");

        assertThat(fruits, hasSize(3));
        assertThat(fruits, hasItem("banana"));
        assertThat(fruits, hasItems("apple", "cherry"));
        assertThat(fruits, contains("apple", "banana", "cherry")); // Exact order
        assertThat(fruits, containsInAnyOrder("cherry", "apple", "banana")); // Any order
        assertThat(fruits, everyItem(notNullValue()));
    }

    @Test
    void testNumberMatchers() {
        int actual = 42;

        assertThat(actual, greaterThan(40));
        assertThat(actual, lessThan(50));
        assertThat(actual, is(both(greaterThan(40)).and(lessThan(50))));
        assertThat((double)actual, closeTo(42.0, 0.01));
    }

    @Test
    void testMapMatchers() {
        Map<String, Integer> scores = Map.of(
            "Alice", 95,
            "Bob", 87,
            "Charlie", 92
        );

        assertThat(scores, hasKey("Alice"));
        assertThat(scores, hasValue(92));
        assertThat(scores, hasEntry("Bob", 87));
        assertThat(scores, aMapWithSize(3));
    }

    @Test
    void testCustomMatcher() {
        // Hamcrest also allows creating custom matchers
        // For example, a matcher that checks if a string is a valid email
        assertThat("user@example.com", isValidEmail()); // Custom matcher
    }

    // Custom matcher example
    private Matcher<String> isValidEmail() {
        return new TypeSafeMatcher<String>() {
            @Override
            protected boolean matchesSafely(String item) {
                return item.matches("^[A-Za-z0-9+_.-]+@(.+)$");
            }

            @Override
            public void describeTo(Description description) {
                description.appendText("a valid email address");
            }
        };
    }
}

