package com.example.utils;

import org.openqa.selenium.*;
import org.openqa.selenium.support.ui.ExpectedConditions;
import org.openqa.selenium.support.ui.WebDriverWait;
import java.time.Duration;
import java.util.function.Supplier;

public class SmartWait {

    private WebDriver driver;
    private int maxRetries;
    private int baseTimeout;

    public SmartWait(WebDriver driver) {
        this(driver, 3, 10);
    }

    public SmartWait(WebDriver driver, int maxRetries, int baseTimeout) {
        this.driver = driver;
        this.maxRetries = maxRetries;
        this.baseTimeout = baseTimeout;
    }

    /**
     * Execute an action with retry on StaleElementReferenceException
     */
    public <T> T executeWithRetry(Supplier<T> action) {
        int attempts = 0;
        while (attempts < maxRetries) {
            try {
                return action.get();
            } catch (StaleElementReferenceException e) {
                attempts++;
                if (attempts >= maxRetries) {
                    throw e;
                }
                // Wait a bit before retrying
                try {
                    Thread.sleep(500);
                } catch (InterruptedException ignored) {}
            }
        }
        throw new RuntimeException("Should not reach here");
    }

    /**
     * Click an element with automatic handling of interception and staleness
     */
    public void safeClick(By locator) {
        executeWithRetry(() -> {
            try {
                WebDriverWait wait = new WebDriverWait(driver, Duration.ofSeconds(baseTimeout));
                WebElement element = wait.until(ExpectedConditions.elementToBeClickable(locator));
                element.click();
                return null;
            } catch (ElementClickInterceptedException e) {
                // Maybe a loading spinner is in the way
                WebDriverWait wait = new WebDriverWait(driver, Duration.ofSeconds(5));
                wait.until(ExpectedConditions.invisibilityOfElementLocated(
                    By.cssSelector(".loading-spinner, .overlay")));
                throw new StaleElementReferenceException("Retry after spinner");
            }
        });
    }

    /**
     * Type text with automatic retry
     */
    public void safeSendKeys(By locator, String text) {
        executeWithRetry(() -> {
            WebDriverWait wait = new WebDriverWait(driver, Duration.ofSeconds(baseTimeout));
            WebElement element = wait.until(ExpectedConditions.visibilityOfElementLocated(locator));
            element.clear();
            element.sendKeys(text);
            return null;
        });
    }

    /**
     * Get text with retry
     */
    public String safeGetText(By locator) {
        return executeWithRetry(() -> {
            WebDriverWait wait = new WebDriverWait(driver, Duration.ofSeconds(baseTimeout));
            WebElement element = wait.until(ExpectedConditions.presenceOfElementLocated(locator));
            return element.getText();
        });
    }
}

package com.example.pages;

import org.openqa.selenium.WebDriver;
import org.openqa.selenium.WebElement;
import org.openqa.selenium.support.FindBy;
import org.openqa.selenium.support.PageFactory;
import org.openqa.selenium.support.ui.WebDriverWait;
import java.time.Duration;

public class BasePage {

    protected WebDriver driver;
    protected WebDriverWait wait;

    public BasePage(WebDriver driver) {
        this.driver = driver;
        this.wait = new WebDriverWait(driver, Duration.ofSeconds(10));
        PageFactory.initElements(driver, this);
    }

    // Common wait methods
    protected void waitForPageLoad() {
        wait.until(d -> ((JavascriptExecutor) d)
            .executeScript("return document.readyState")
            .equals("complete"));
    }
}

public class LoginPage extends BasePage {

    @FindBy(id = "username")
    private WebElement usernameInput;

    @FindBy(id = "password")
    private WebElement passwordInput;

    @FindBy(id = "loginBtn")
    private WebElement loginButton;

    public LoginPage(WebDriver driver) {
        super(driver);
    }

    public void enterUsername(String username) {
        wait.until(d -> usernameInput.isDisplayed());
        usernameInput.clear();
        usernameInput.sendKeys(username);
    }

    public void enterPassword(String password) {
        wait.until(d -> passwordInput.isEnabled());
        passwordInput.sendKeys(password);
    }

    public DashboardPage clickLogin() {
        wait.until(d -> loginButton.isEnabled());
        loginButton.click();
        waitForPageLoad();
        return new DashboardPage(driver);
    }

    public DashboardPage login(String username, String password) {
        enterUsername(username);
        enterPassword(password);
        return clickLogin();
    }
}

