public class BrowserFeatureChecker {

    private WebDriver driver;

    public boolean supportsDateInput() {
        return (Boolean) ((JavascriptExecutor) driver).executeScript(
            "var input = document.createElement('input');" +
            "input.setAttribute('type', 'date');" +
            "return input.type !== 'text';"
        );
    }

    public boolean supportsWebP() {
        return (Boolean) ((JavascriptExecutor) driver).executeScript(
            "var canvas = document.createElement('canvas');" +
            "return canvas.toDataURL('image/webp').indexOf('data:image/webp') === 0;"
        );
    }

    public String getBrowserInfo() {
        return (String) ((JavascriptExecutor) driver).executeScript(
            "return navigator.userAgent;"
        );
    }

    public boolean isMobileBrowser() {
        return (Boolean) ((JavascriptExecutor) driver).executeScript(
            "return /Mobi|Android|iPhone|iPad|iPod/i.test(navigator.userAgent);"
        );
    }

    public void testWithFeatureDetection() {
        if (supportsDateInput()) {
            // Use standard date picker interaction
            driver.findElement(By.cssSelector("input[type='date']")).sendKeys("2024-01-01");
        } else {
            // Use fallback method (e.g., JavaScript to set value)
            ((JavascriptExecutor) driver).executeScript(
                "document.querySelector('input[type=\"date\"]').value = '2024-01-01';"
            );
        }
    }
}

