    private String browserVersion;
    private String platform;

    @BeforeMethod
    public void setup() {
        // Get browser info from driver capabilities
        Capabilities caps = ((RemoteWebDriver) driver).getCapabilities();
        browserName = caps.getBrowserName().toLowerCase();
        browserVersion = caps.getBrowserVersion();
        platform = caps.getPlatformName().toString();

        System.out.println("Running on: " + browserName + " " + browserVersion + " on " + platform);
    }

