import org.testng.TestNG;
import org.testng.xml.XmlSuite;
import org.testng.xml.XmlTest;
import java.util.ArrayList;
import java.util.List;

public class TestNGParallelSetup {

    public static void main(String[] args) {
        // Create suite programmatically
        XmlSuite suite = new XmlSuite();
        suite.setName("Dynamic Parallel Suite");
        suite.setParallel(XmlSuite.ParallelMode.TESTS);
        suite.setThreadCount(8);
        suite.setVerbose(2);

        // Add tests for different browsers
        String[] browsers = {"chrome", "firefox", "edge", "safari"};

        for (String browser : browsers) {
            XmlTest test = new XmlTest(suite);
            test.setName(browser + " Tests");

            // Add parameters
            test.addParameter("browser", browser);
            test.addParameter("headless", "true");

            // Add classes
            List<XmlClass> classes = new ArrayList<>();
            classes.add(new XmlClass("com.example.tests.LoginTest"));
            classes.add(new XmlClass("com.example.tests.SearchTest"));
            test.setXmlClasses(classes);
        }

        // Run suite
        TestNG testng = new TestNG();
        List<XmlSuite> suites = new ArrayList<>();
        suites.add(suite);
        testng.setXmlSuites(suites);
        testng.run();
    }
}

