        String timestamp = String.valueOf(System.currentTimeMillis());
        String uniqueId = UUID.randomUUID().toString().substring(0, 8);

        return new TestUser(
            "user_" + threadId + "_" + uniqueId,
            "pass_" + timestamp.substring(timestamp.length() - 6),
            "user_" + threadId + "@example.com"
