pipeline {
    agent none

    parameters {
        choice(
            name: 'PARALLEL_LEVEL',
            choices: ['low', 'medium', 'high', 'custom'],
            description: 'Parallel execution level'
        )
        string(
            name: 'CUSTOM_THREADS',
            defaultValue: '10',
            description: 'Number of threads (for custom level)'
        )
    }

    environment {
        BROWSERSTACK_USERNAME = credentials('browserstack-username')
        BROWSERSTACK_ACCESS_KEY = credentials('browserstack-access-key')
    }

    stages {
        stage('Build') {
            agent any
            steps {
                sh 'mvn clean compile'
            }
        }

        stage('Parallel Tests') {
            agent none
            steps {
                script {
                    // Define parallel execution based on parameter
                    def parallelJobs = [:]

                    def browsers = ['chrome', 'firefox', 'edge', 'safari']
                    def testGroups = [1, 2, 3, 4]

                    // Create a matrix of browser x test group
                    for (browser in browsers) {
                        for (group in testGroups) {
                            def jobName = "${browser}-group-${group}"
                            parallelJobs[jobName] = {
                                node('linux') {
                                    stage("Test: ${jobName}") {
                                        sh """
                                            mvn test \
                                                -Dbrowser=${browser} \
                                                -DtestGroup=${group} \
                                                -Dthreads=${getThreadCount()}
                                        """
                                    }
                                }
                            }
                        }
                    }

                    // Run all in parallel
                    parallel parallelJobs
                }
            }
        }

        stage('Publish Reports') {
            agent any
            steps {
                junit 'target/surefire-reports/*.xml'
                publishHTML([
                    reportDir: 'target/site/allure-maven-plugin',
                    reportFiles: 'index.html',
                    reportName: 'Allure Report'
                ])
            }
        }
    }

    post {
        always {
            cleanWs()
        }
        failure {
            emailext(
                to: 'team@example.com',
                subject: "Parallel Tests Failed: ${env.JOB_NAME} - ${env.BUILD_NUMBER}",
                body: "Check console at ${env.BUILD_URL}"
            )
        }
    }
}

