import java.lang.management.ManagementFactory;
import java.lang.management.ThreadMXBean;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicLong;

public class PerformanceMonitor {

    private static final ThreadMXBean threadMXBean = ManagementFactory.getThreadMXBean();
    private static final ConcurrentHashMap<String, TestMetrics> metrics = new ConcurrentHashMap<>();

    static class TestMetrics {
        String testName;
        long startTime;
        long endTime;
        long threadId;
        String threadName;
        long cpuTime;

        TestMetrics(String testName) {
            this.testName = testName;
            this.startTime = System.currentTimeMillis();
            this.threadId = Thread.currentThread().getId();
            this.threadName = Thread.currentThread().getName();
            this.cpuTime = threadMXBean.getCurrentThreadCpuTime();
        }

        void finish() {
            this.endTime = System.currentTimeMillis();
            this.cpuTime = threadMXBean.getCurrentThreadCpuTime() - this.cpuTime;
        }
    }

    public static void startTest(String testName) {
        metrics.put(testName + Thread.currentThread().getId(), new TestMetrics(testName));
    }

    public static void endTest(String testName) {
        String key = testName + Thread.currentThread().getId();
        TestMetrics metric = metrics.get(key);
        if (metric != null) {
            metric.finish();
            System.out.println(metricToString(metric));
        }
    }

    private static String metricToString(TestMetrics m) {
        return String.format(
            "Test: %s | Thread: %d (%s) | Duration: %d ms | CPU Time: %.2f ms",
            m.testName, m.threadId, m.threadName, 
            (m.endTime - m.startTime),
            m.cpuTime / 1_000_000.0
        );
    }

    public static void printSummary() {
        System.out.println("\n=== PARALLEL EXECUTION SUMMARY ===");
        System.out.println("Total tests: " + metrics.size());

        double totalWallTime = metrics.values().stream()
            .mapToLong(m -> m.endTime - m.startTime)
            .sum();
        double totalCpuTime = metrics.values().stream()
            .mapToLong(m -> m.cpuTime)
            .sum() / 1_000_000.0;

        System.out.printf("Total wall time: %.2f seconds\n", totalWallTime / 1000);
        System.out.printf("Total CPU time: %.2f seconds\n", totalCpuTime / 1000);
        System.out.printf("Parallel efficiency: %.2f%%\n", 
            (totalCpuTime / (totalWallTime / 1000)) / 
            Runtime.getRuntime().availableProcessors() * 100);
    }
}

// Use in tests
@Test
public void testSomething() {
    PerformanceMonitor.startTest("testSomething");
    try {
        // test logic
    } finally {
        PerformanceMonitor.endTest("testSomething");
    }
}

