import com.opencsv.CSVReader;
import com.opencsv.exceptions.CsvException;
import org.testng.annotations.DataProvider;
import java.io.FileReader;
import java.io.IOException;
import java.util.Arrays;
import java.util.List;
import java.util.stream.Collectors;

/**
 * Generic CSV Data Provider that reads any CSV file and returns data as Object[][]
 * for TestNG DataProvider.
 */
public class CsvDataProvider {

    /**
     * Reads CSV file and returns data for DataProvider.
     * First row is treated as header and used for field mapping if needed.
     * 
     * @param csvPath Path to CSV file in classpath or absolute path
     * @param skipHeader Whether to skip the first row (header)
     * @return Object[][] for TestNG DataProvider
     */
    public static Object[][] readCsv(String csvPath, boolean skipHeader) {
        try (CSVReader reader = new CSVReader(new FileReader(csvPath))) {
            List<String[]> rows = reader.readAll();

            if (skipHeader && !rows.isEmpty()) {
                rows = rows.subList(1, rows.size()); // Remove header
            }

            // Convert List<String[]> to Object[][]
            Object[][] data = new Object[rows.size()][];
            for (int i = 0; i < rows.size(); i++) {
                data[i] = rows.get(i);
            }

            return data;

        } catch (IOException | CsvException e) {
            throw new RuntimeException("Failed to read CSV file: " + csvPath, e);
        }
    }

    /**
     * Reads CSV and maps to specific object types.
     * Assumes first row contains headers.
     */
    public static List<LoginData> readLoginData(String csvPath) {
        try (CSVReader reader = new CSVReader(new FileReader(csvPath))) {
            List<String[]> rows = reader.readAll();

            // Skip header row
            return rows.stream()
                .skip(1)
                .map(row -> new LoginData(
                    row[0], // username
                    row[1], // password
                    Boolean.parseBoolean(row[2]), // shouldSucceed
                    row[3]  // expectedMessage
                ))
                .collect(Collectors.toList());

        } catch (IOException | CsvException e) {
            throw new RuntimeException("Failed to read CSV file: " + csvPath, e);
        }
    }

    /**
     * Data Provider method that can be used directly in tests
     */
    @DataProvider(name = "csvData")
    public static Object[][] provideCsvData() {
        String filePath = System.getProperty("test.data.path", 
            "src/test/resources/testdata/login/valid_users.csv");
        return readCsv(filePath, true);
    }

    /**
     * Inner class representing login test data
     */
    public static class LoginData {
        private String username;
        private String password;
        private boolean shouldSucceed;
        private String expectedMessage;

        public LoginData(String username, String password, 
                        boolean shouldSucceed, String expectedMessage) {
            this.username = username;
            this.password = password;
            this.shouldSucceed = shouldSucceed;
            this.expectedMessage = expectedMessage;
        }

        // Getters
        public String getUsername() { return username; }
        public String getPassword() { return password; }
        public boolean shouldSucceed() { return shouldSucceed; }
        public String getExpectedMessage() { return expectedMessage; }

        @Override
        public String toString() {
            return String.format("LoginData{username='%s', shouldSucceed=%s}", 
                username, shouldSucceed);
        }
    }
}

