package com.company.core.dataproviders;

import org.apache.poi.ss.usermodel.*;
import org.apache.poi.xssf.usermodel.XSSFWorkbook;
import org.testng.annotations.DataProvider;
import java.io.File;
import java.io.FileInputStream;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;

/**
 * Advanced Excel Data Provider with support for:
 * - Multiple sheets
 * - Different data types (String, Number, Boolean, Date)
 * - Formula evaluation
 * - Row filtering
 */
public class ExcelDataProvider {

    private static final String EXCEL_PATH = "src/test/resources/testdata/";

    /**
     * Generic method to read Excel data
     * @param fileName Excel file name
     * @param sheetName Sheet to read
     * @param hasHeader Whether first row is header
     * @return List of Object arrays representing rows
     */
    public static List<Object[]> readExcel(String fileName, String sheetName, boolean hasHeader) {
        List<Object[]> testData = new ArrayList<>();

        try (FileInputStream fis = new FileInputStream(new File(EXCEL_PATH + fileName));
             Workbook workbook = new XSSFWorkbook(fis)) {

            Sheet sheet = workbook.getSheet(sheetName);
            if (sheet == null) {
                throw new IllegalArgumentException("Sheet " + sheetName + " not found");
            }

            Iterator<Row> rowIterator = sheet.iterator();

            // Skip header if needed
            if (hasHeader && rowIterator.hasNext()) {
                rowIterator.next();
            }

            // Formula evaluator for cells with formulas
            FormulaEvaluator evaluator = workbook.getCreationHelper().createFormulaEvaluator();

            while (rowIterator.hasNext()) {
                Row row = rowIterator.next();

                // Skip empty rows
                if (isRowEmpty(row)) {
                    continue;
                }

                Object[] rowData = new Object[row.getLastCellNum()];

                for (int i = 0; i < row.getLastCellNum(); i++) {
                    Cell cell = row.getCell(i, Row.MissingCellPolicy.CREATE_NULL_AS_BLANK);
                    rowData[i] = getCellValue(cell, evaluator);
                }

                testData.add(rowData);
            }

        } catch (IOException e) {
            throw new RuntimeException("Failed to read Excel file: " + fileName, e);
        }

        return testData;
    }

    /**
     * Convert cell to appropriate Java object based on cell type
     */
    private static Object getCellValue(Cell cell, FormulaEvaluator evaluator) {
        switch (cell.getCellType()) {
            case STRING:
                return cell.getStringCellValue();

            case NUMERIC:
                if (DateUtil.isCellDateFormatted(cell)) {
                    return cell.getDateCellValue();
                } else {
                    return cell.getNumericCellValue();
                }

            case BOOLEAN:
                return cell.getBooleanCellValue();

            case FORMULA:
                CellValue formulaValue = evaluator.evaluate(cell);
                switch (formulaValue.getCellType()) {
                    case STRING: return formulaValue.getStringValue();
                    case NUMERIC: return formulaValue.getNumberValue();
                    case BOOLEAN: return formulaValue.getBooleanValue();
                    default: return null;
                }

            case BLANK:
                return null;

            default:
                return null;
        }
    }

    /**
     * Check if a row is completely empty
     */
    private static boolean isRowEmpty(Row row) {
        if (row == null) return true;

        for (int i = 0; i < row.getLastCellNum(); i++) {
            Cell cell = row.getCell(i, Row.MissingCellPolicy.RETURN_BLANK_AS_NULL);
            if (cell != null && cell.getCellType() != CellType.BLANK) {
                return false;
            }
        }
        return true;
    }

    /**
     * DataProvider for login tests from Excel
     */
    @DataProvider(name = "excelLoginData")
    public static Object[][] provideLoginData() {
        List<Object[]> dataList = readExcel("login_test_data.xlsx", "LoginScenarios", true);
        return dataList.toArray(new Object[0][]);
    }

    /**
     * DataProvider with filtering by scenario type
     */
    @DataProvider(name = "positiveLoginData")
    public static Object[][] providePositiveLoginData() {
        List<Object[]> allData = readExcel("login_test_data.xlsx", "LoginScenarios", true);
        List<Object[]> filteredData = new ArrayList<>();

        for (Object[] row : allData) {
            // Assuming column 2 is scenario type
            if ("positive".equals(row[2])) {
                filteredData.add(row);
            }
        }

        return filteredData.toArray(new Object[0][]);
    }
}

