 * Supports nested objects, arrays, and all JSON data types.
 */
public class JsonDataProvider {

    private static final ObjectMapper mapper = new ObjectMapper();
    private static final String JSON_PATH = "src/test/resources/testdata/";

    /**
     * Read JSON array and convert to List of Maps
     */
    public static List<Map<String, Object>> readJsonArray(String fileName) {
        try {
            return mapper.readValue(
                new File(JSON_PATH + fileName),
                new TypeReference<List<Map<String, Object>>>() {}
            );
        } catch (IOException e) {
            throw new RuntimeException("Failed to read JSON file: " + fileName, e);
        }
    }

    /**
     * Read JSON and convert to specific object type
     */
    public static <T> List<T> readJsonArray(String fileName, Class<T> clazz) {
        try {
            return mapper.readValue(
                new File(JSON_PATH + fileName),
                mapper.getTypeFactory().constructCollectionType(List.class, clazz)
            );
        } catch (IOException e) {
            throw new RuntimeException("Failed to read JSON file: " + fileName, e);
        }
    }

    /**
     * Convert List of Maps to Object[][] for TestNG
     */
    public static Object[][] mapsToDataProvider(List<Map<String, Object>> data) {
        Object[][] result = new Object[data.size()][1];
        for (int i = 0; i < data.size(); i++) {
            result[i][0] = data.get(i);
        }
        return result;
    }

