    void testLoginFromFile(String username, String password, String expected) {
        LoginResult result = loginService.login(username, password);
        assertEquals(expected, result.getStatus());
    }

    // ===========================================
    // @MethodSource: Complex data generation
    // ===========================================
    @ParameterizedTest
    @MethodSource("provideUsers")
    void testUserValidation(User user, boolean expectedValid) {
        assertEquals(expectedValid, userValidator.isValid(user));
    }

