package com.company.core.utils;

import java.util.*;

/**
 * Pairwise (All-Pairs) Test Data Generator
 * Generates minimal set of test cases that cover all possible pairs of input values.
 */
public class PairwiseGenerator {

    /**
     * Generate pairwise combinations from parameter-value map
     */
    public static List<Map<String, String>> generatePairwise(Map<String, List<String>> parameters) {
        List<Map<String, String>> result = new ArrayList<>();

        // Convert parameters to list for indexed access
        List<String> paramNames = new ArrayList<>(parameters.keySet());
        List<List<String>> paramValues = new ArrayList<>();
        for (String name : paramNames) {
            paramValues.add(parameters.get(name));
        }

        // Generate all possible pairs
        Set<Pair> coveredPairs = new HashSet<>();

        // Start with first combination
        int[] indices = new int[paramNames.size()];

        while (true) {
            // Create current combination
            Map<String, String> combo = new LinkedHashMap<>();
            for (int i = 0; i < paramNames.size(); i++) {
                combo.put(paramNames.get(i), paramValues.get(i).get(indices[i]));
            }

            // Check if this combination adds new pairs
            boolean addsNewPair = false;
            List<Pair> newPairs = new ArrayList<>();

            for (int i = 0; i < paramNames.size(); i++) {
                for (int j = i + 1; j < paramNames.size(); j++) {
                    Pair pair = new Pair(
                        paramNames.get(i), paramValues.get(i).get(indices[i]),
                        paramNames.get(j), paramValues.get(j).get(indices[j])
                    );
                    if (!coveredPairs.contains(pair)) {
                        addsNewPair = true;
                        newPairs.add(pair);
                    }
                }
            }

            if (addsNewPair) {
                result.add(combo);
                coveredPairs.addAll(newPairs);
            }

            // Move to next combination
            int pos = indices.length - 1;
            while (pos >= 0) {
                indices[pos]++;
                if (indices[pos] < paramValues.get(pos).size()) {
                    break;
                }
                indices[pos] = 0;
                pos--;
            }
            if (pos < 0) break;
        }

        return result;
    }

    /**
     * Pair class to track covered pairs
     */
    static class Pair {
        String param1, value1, param2, value2;

        Pair(String p1, String v1, String p2, String v2) {
            this.param1 = p1;
            this.value1 = v1;
            this.param2 = p2;
            this.value2 = v2;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Pair)) return false;
            Pair pair = (Pair) o;
            return (param1.equals(pair.param1) && value1.equals(pair.value1) &&
                    param2.equals(pair.param2) && value2.equals(pair.value2)) ||
                   (param1.equals(pair.param2) && value1.equals(pair.value2) &&
                    param2.equals(pair.param1) && value2.equals(pair.value1));
        }

        @Override
        public int hashCode() {
            // Order-independent hash
            String first = param1.compareTo(param2) < 0 ? param1 : param2;
            String second = param1.compareTo(param2) < 0 ? param2 : param1;
            String vFirst = first.equals(param1) ? value1 : value2;
            String vSecond = second.equals(param2) ? value2 : value1;
            return Objects.hash(first, vFirst, second, vSecond);
        }
    }

    /**
     * Convert pairwise results to TestNG DataProvider format
     */
    public static Object[][] toDataProvider(List<Map<String, String>> pairwiseData) {
        Object[][] result = new Object[pairwiseData.size()][1];
        for (int i = 0; i < pairwiseData.size(); i++) {
            result[i][0] = pairwiseData.get(i);
        }
        return result;
    }
}

