import java.time.Duration;

/**
 * Page Object with methods designed for data-driven testing
 */
public class CheckoutPage {

    private WebDriver driver;
    private WebDriverWait wait;

    @FindBy(id = "firstName")
    private WebElement firstNameInput;

    @FindBy(id = "lastName")
    private WebElement lastNameInput;

    @FindBy(id = "email")
    private WebElement emailInput;

    @FindBy(id = "address")
    private WebElement addressInput;

    @FindBy(id = "city")
    private WebElement cityInput;

    @FindBy(id = "zipCode")
    private WebElement zipCodeInput;

    @FindBy(id = "paymentMethod")
    private WebElement paymentMethodSelect;

    @FindBy(id = "cardNumber")
    private WebElement cardNumberInput;

    @FindBy(id = "expiryDate")
    private WebElement expiryDateInput;

    @FindBy(id = "cvv")
    private WebElement cvvInput;

    @FindBy(id = "placeOrder")
    private WebElement placeOrderButton;

    @FindBy(className = "success-message")
    private WebElement successMessage;

    public CheckoutPage(WebDriver driver) {
        this.driver = driver;
        this.wait = new WebDriverWait(driver, Duration.ofSeconds(10));
        PageFactory.initElements(driver, this);
    }

    /**
     * Fill shipping information from data object
     */
    public CheckoutPage fillShippingInfo(ShippingInfo shipping) {
        wait.until(d -> firstNameInput.isDisplayed());

        firstNameInput.sendKeys(shipping.getFirstName());
        lastNameInput.sendKeys(shipping.getLastName());
        emailInput.sendKeys(shipping.getEmail());
        addressInput.sendKeys(shipping.getAddress());
        cityInput.sendKeys(shipping.getCity());
        zipCodeInput.sendKeys(shipping.getZipCode());

        return this;
    }

    /**
     * Fill payment information from data object
     */
    public CheckoutPage fillPaymentInfo(PaymentInfo payment) {
        paymentMethodSelect.sendKeys(payment.getPaymentMethod());
        cardNumberInput.sendKeys(payment.getCardNumber());
        expiryDateInput.sendKeys(payment.getExpiryDate());
        cvvInput.sendKeys(payment.getCvv());

        return this;
    }

    /**
     * Complete checkout with combined data objects
     */
    public CheckoutPage completeCheckout(ShippingInfo shipping, PaymentInfo payment) {
        return fillShippingInfo(shipping)
               .fillPaymentInfo(payment);
    }

    /**
     * Place order
     */
    public void placeOrder() {
        placeOrderButton.click();
        wait.until(d -> successMessage.isDisplayed());
    }

    /**
     * Get success message text
     */
    public String getSuccessMessage() {
        return successMessage.getText();
    }
}

