package com.company.core.utils;

import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.List;
import java.util.stream.Collectors;
import java.util.stream.Stream;

/**
 * Dynamically selects test data based on environment, branch, or test profile
 */
public class DynamicDataSelector {

    private static final String DATA_ROOT = "src/test/resources/testdata/";

    /**
     * Select data files based on environment
     */
    public static List<String> selectDataFiles(String environment) {
        List<String> selectedFiles = new ArrayList<>();

        // Base data - always included
        selectedFiles.addAll(loadFiles(DATA_ROOT + "base/"));

        // Environment-specific overrides
        String envDir = DATA_ROOT + environment + "/";
        if (Files.exists(Paths.get(envDir))) {
            selectedFiles.addAll(loadFiles(envDir));
        }

        // Branch-specific data for CI
        String branch = System.getenv("BRANCH_NAME");
        if (branch != null) {
            String branchDir = DATA_ROOT + "branches/" + branch + "/";
            if (Files.exists(Paths.get(branchDir))) {
                selectedFiles.addAll(loadFiles(branchDir));
            }
        }

        return selectedFiles;
    }

    /**
     * Load all CSV files from a directory
     */
    private static List<String> loadFiles(String directory) {
        try (Stream<Path> paths = Files.walk(Paths.get(directory))) {
            return paths
                .filter(Files::isRegularFile)
                .filter(p -> p.toString().endsWith(".csv"))
                .map(Path::toString)
                .collect(Collectors.toList());
        } catch (IOException e) {
            return new ArrayList<>();
        }
    }

    /**
     * Get test data subset based on chunk number for parallel execution
     */
    public static List<String> getDataChunk(List<String> allFiles, int chunkNum, int totalChunks) {
        int chunkSize = allFiles.size() / totalChunks;
        int start = (chunkNum - 1) * chunkSize;
        int end = (chunkNum == totalChunks) ? allFiles.size() : start + chunkSize;

        return allFiles.subList(start, end);
    }

    /**
     * Usage in test
     */
    public static void main(String[] args) {
        String env = System.getProperty("env", "dev");
        int chunk = Integer.parseInt(System.getProperty("data.chunk", "1"));
        int totalChunks = Integer.parseInt(System.getProperty("total.chunks", "1"));

        List<String> allData = selectDataFiles(env);
        List<String> myChunk = getDataChunk(allData, chunk, totalChunks);

        System.out.println("Running data chunk " + chunk + " of " + totalChunks);
        myChunk.forEach(file -> System.out.println("  - " + file));
    }
}

