import org.testng.ITestContext;
import org.testng.ITestListener;
import org.testng.ITestResult;
import java.io.FileWriter;
import java.io.PrintWriter;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.util.concurrent.ConcurrentHashMap;

/**
 * Custom TestNG listener to generate detailed DDT reports
 */
public class DDTTestListener implements ITestListener {

    private static final ConcurrentHashMap<String, TestResult> results = new ConcurrentHashMap<>();
    private static PrintWriter csvWriter;
    private static PrintWriter htmlWriter;

    static {
        try {
            String timestamp = LocalDateTime.now().format(DateTimeFormatter.ofPattern("yyyyMMdd_HHmmss"));
            csvWriter = new PrintWriter(new FileWriter("ddt-results-" + timestamp + ".csv"));
            htmlWriter = new PrintWriter(new FileWriter("ddt-report-" + timestamp + ".html"));

            // Write CSV header
            csvWriter.println("Test Name,Data Set,Status,Start Time,End Time,Duration(ms),Error Message");

            // Write HTML header
            htmlWriter.println("<html><head><title>DDT Test Report</title>");
            htmlWriter.println("<style>");
            htmlWriter.println("body { font-family: Arial; margin: 20px; }");
            htmlWriter.println(".pass { color: green; } .fail { color: red; } .skip { color: orange; }");
            htmlWriter.println("table { border-collapse: collapse; width: 100%; }");
            htmlWriter.println("th, td { border: 1px solid #ddd; padding: 8px; text-align: left; }");
            htmlWriter.println("th { background-color: #f2f2f2; }");
            htmlWriter.println("</style></head><body>");
            htmlWriter.println("<h1>Data-Driven Test Report</h1>");
            htmlWriter.println("<table><tr><th>Test</th><th>Data Set</th><th>Status</th><th>Time</th><th>Error</th></tr>");

        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    @Override
    public void onTestStart(ITestResult result) {
        String key = generateKey(result);
        TestResult tr = new TestResult();
        tr.startTime = System.currentTimeMillis();
        results.put(key, tr);
    }

    @Override
    public void onTestSuccess(ITestResult result) {
        completeTest(result, "PASS", null);
    }

    @Override
    public void onTestFailure(ITestResult result) {
        completeTest(result, "FAIL", result.getThrowable());
    }

    @Override
    public void onTestSkipped(ITestResult result) {
        completeTest(result, "SKIP", result.getThrowable());
    }

    private void completeTest(ITestResult result, String status, Throwable error) {
        String key = generateKey(result);
        TestResult tr = results.get(key);
        if (tr == null) return;

        tr.endTime = System.currentTimeMillis();
        tr.status = status;
        tr.duration = tr.endTime - tr.startTime;
        tr.error = error;

        // Write to CSV
        csvWriter.printf("%s,%s,%s,%d,%d,%d,%s%n",
            result.getMethod().getMethodName(),
            getDataSetInfo(result),
            status,
            tr.startTime,
            tr.endTime,
            tr.duration,
            error == null ? "" : error.getMessage().replace(",", ";")
        );
        csvWriter.flush();

        // Write to HTML
        String color = status.equals("PASS") ? "pass" : status.equals("FAIL") ? "fail" : "skip";
        htmlWriter.printf("<tr><td>%s</td><td>%s</td><td class='%s'>%s</td><td>%d ms</td><td>%s</td></tr>%n",
            result.getMethod().getMethodName(),
            getDataSetInfo(result),
            color,
            status,
            tr.duration,
            error == null ? "" : error.getMessage()
        );
        htmlWriter.flush();
    }

    private String generateKey(ITestResult result) {
        return result.getMethod().getMethodName() + "_" + 
               Thread.currentThread().getId() + "_" +
               result.getParameters().hashCode();
    }

    private String getDataSetInfo(ITestResult result) {
        Object[] params = result.getParameters();
        if (params == null || params.length == 0) return "default";

        StringBuilder sb = new StringBuilder();
        for (Object param : params) {
            sb.append(param.toString()).append("|");
        }
        return sb.toString();
    }

    @Override
    public void onFinish(ITestContext context) {
        // Close HTML table and file
        htmlWriter.println("</table>");

        // Add summary statistics
        long total = results.size();
        long passed = results.values().stream().filter(r -> "PASS".equals(r.status)).count();
        long failed = results.values().stream().filter(r -> "FAIL".equals(r.status)).count();
        long skipped = results.values().stream().filter(r -> "SKIP".equals(r.status)).count();

        htmlWriter.printf("<h2>Summary: Total: %d, Passed: %d, Failed: %d, Skipped: %d</h2>%n",
            total, passed, failed, skipped);
        htmlWriter.println("</body></html>");

        // Close writers
        csvWriter.close();
        htmlWriter.close();
    }

    static class TestResult {
        long startTime;
        long endTime;
        long duration;
        String status;
        Throwable error;
    }
}

