// ExcelReader.java
public class ExcelReader {
    private FileInputStream fis;
    private XSSFWorkbook workbook;
    private XSSFSheet sheet;

    public ExcelReader(String filePath) {
        try {
            fis = new FileInputStream(filePath);
            workbook = new XSSFWorkbook(fis);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    public List<Map<String, String>> getTestData(String sheetName) {
        sheet = workbook.getSheet(sheetName);
        List<Map<String, String>> testData = new ArrayList<>();

        // Get headers
        XSSFRow headerRow = sheet.getRow(0);
        List<String> headers = new ArrayList<>();
        for (Cell cell : headerRow) {
            headers.add(cell.getStringCellValue());
        }

        // Get data rows
        for (int i = 1; i <= sheet.getLastRowNum(); i++) {
            XSSFRow dataRow = sheet.getRow(i);
            Map<String, String> rowData = new HashMap<>();

            for (int j = 0; j < headers.size(); j++) {
                Cell cell = dataRow.getCell(j);
                String cellValue = "";

                if (cell != null) {
                    switch (cell.getCellType()) {
                        case STRING:
                            cellValue = cell.getStringCellValue();
                            break;
                        case NUMERIC:
                            cellValue = String.valueOf(cell.getNumericCellValue());
                            break;
                        case BOOLEAN:
                            cellValue = String.valueOf(cell.getBooleanCellValue());
                            break;
                        default:
                            cellValue = "";
                    }
                }
                rowData.put(headers.get(j), cellValue);
            }
            testData.add(rowData);
        }
        return testData;
    }

    public void close() {
        try {
            if (workbook != null) workbook.close();
            if (fis != null) fis.close();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}

// TestExecutor.java
public class TestExecutor {
    private WebDriver driver;
    private LoginKeywords loginKeywords;
    private NavigationKeywords navigationKeywords;
    private Map<String, Object> keywordMap;

    public TestExecutor(WebDriver driver) {
        this.driver = driver;
        initializeKeywords();
    }

    private void initializeKeywords() {
        loginKeywords = new LoginKeywords(driver);
        navigationKeywords = new NavigationKeywords(driver);

        keywordMap = new HashMap<>();
        // Map keyword names to method references
        keywordMap.put("navigateToUrl", loginKeywords::navigateToLoginPage);
        keywordMap.put("enterUsername", loginKeywords::enterUsername);
        keywordMap.put("enterPassword", loginKeywords::enterPassword);
        keywordMap.put("clickLogin", loginKeywords::clickLogin);
        keywordMap.put("verifyLoginSuccess", loginKeywords::verifyLoginSuccess);
        keywordMap.put("verifyLoginError", loginKeywords::verifyLoginError);
    }

    public TestResult executeTestCase(List<Map<String, String>> testSteps) {
        TestResult testResult = new TestResult();
        testResult.setTestId(testSteps.get(0).get("TC_ID"));
        testResult.setStartTime(LocalDateTime.now());

        List<StepResult> stepResults = new ArrayList<>();

        for (Map<String, String> step : testSteps) {
            StepResult stepResult = executeTestStep(step);
            stepResults.add(stepResult);

            // Stop execution if step fails
            if (stepResult.getStatus().equals("FAIL")) {
                testResult.setStatus("FAIL");
                break;
            }
        }

        testResult.setStepResults(stepResults);
        testResult.setEndTime(LocalDateTime.now());

        if (!testResult.getStatus().equals("FAIL")) {
            testResult.setStatus("PASS");
        }

        return testResult;
    }

    private StepResult executeTestStep(Map<String, String> step) {
        StepResult stepResult = new StepResult();
        stepResult.setStepDescription(step.get("Description"));
        stepResult.setKeyword(step.get("Keyword"));
        stepResult.setTestData(step.get("Data"));

        try {
            String keyword = step.get("Keyword");
            String data = step.get("Data");

            // Execute the keyword
            Function<String, String> keywordFunction = 
                (Function<String, String>) keywordMap.get(keyword);
            String result = keywordFunction.apply(data);

            stepResult.setStatus(result.startsWith("PASS") ? "PASS" : "FAIL");
            stepResult.setMessage(result);

        } catch (Exception e) {
            stepResult.setStatus("FAIL");
            stepResult.setMessage("Exception: " + e.getMessage());
        }

        return stepResult;
    }
}

