// Hooks.java
public class Hooks {

    private static WebDriver driver;
    private static Scenario scenario;

    @Before
    public void beforeScenario(Scenario scenario) {
        Hooks.scenario = scenario;
        String browser = ConfigReader.getProperty("browser");
        driver = WebDriverManager.createDriver(browser);
        driver.manage().window().maximize();
        driver.manage().timeouts().implicitlyWait(
            Duration.ofSeconds(10));

        // Log scenario start
        System.out.println("Starting scenario: " + scenario.getName());
    }

    @After
    public void afterScenario(Scenario scenario) {
        // Take screenshot if scenario failed
        if (scenario.isFailed()) {
            takeScreenshot(scenario.getName());
            scenario.attach(takeScreenshotAsBytes(), "image/png", "Screenshot on failure");
        }

        // Log scenario result
        System.out.println("Scenario: " + scenario.getName() + " - Status: " + 
            (scenario.isFailed() ? "FAILED" : "PASSED"));

        // Close browser
        if (driver != null) {
            driver.quit();
        }
    }

    @BeforeStep
    public void beforeStep() {
        // Wait for page to load before each step
        waitForPageToLoad();
    }

    @AfterStep
    public void afterStep() {
        // Add small delay between steps for better visibility
        try {
            Thread.sleep(500);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    public static WebDriver getDriver() {
        return driver;
    }

    public static Scenario getScenario() {
        return scenario;
    }

    private void takeScreenshot(String scenarioName) {
        try {
            File screenshot = ((TakesScreenshot) driver).getScreenshotAs(OutputType.FILE);
            String timestamp = LocalDateTime.now().format(DateTimeFormatter.ofPattern("yyyyMMdd_HHmmss"));
            String screenshotName = scenarioName.replace(" ", "_") + "_" + timestamp + ".png";
            FileUtils.copyFile(screenshot, new File("target/screenshots/" + screenshotName));
        } catch (IOException e) {
            System.err.println("Failed to take screenshot: " + e.getMessage());
        }
    }

    private byte[] takeScreenshotAsBytes() {
        return ((TakesScreenshot) driver).getScreenshotAs(OutputType.BYTES);
    }

    private void waitForPageToLoad() {
        try {
            WebDriverWait wait = new WebDriverWait(driver, Duration.ofSeconds(10));
            wait.until(webDriver -> ((JavascriptExecutor) webDriver)
                .executeScript("return document.readyState").equals("complete"));
        } catch (Exception e) {
            // Continue execution even if page load check fails
        }
    }
}

