// Custom Logger Implementation
public class TestLogger {

    private static final Logger logger = LoggerFactory.getLogger(TestLogger.class);
    private static final ThreadLocal<Logger> testLogger = new ThreadLocal<>();

    public static void initializeTestLogger(String testName) {
        LoggerContext context = (LoggerContext) LoggerFactory.getILoggerFactory();

        // Create test-specific logger
        Logger testSpecificLogger = context.getLogger(testName);
        testLogger.set(testSpecificLogger);

        // Create test-specific log file
        try {
            String logFileName = "target/logs/" + testName + "_" + 
                LocalDateTime.now().format(DateTimeFormatter.ofPattern("yyyyMMdd_HHmmss")) + ".log";

            FileAppender<ILoggingEvent> fileAppender = new FileAppender<>();
            fileAppender.setFile(logFileName);
            fileAppender.setContext(context);

            PatternLayoutEncoder encoder = new PatternLayoutEncoder();
            encoder.setPattern("%d{HH:mm:ss.SSS} [%thread] %-5level %logger{36} - %msg%n");
            encoder.setContext(context);
            encoder.start();

            fileAppender.setEncoder(encoder);
            fileAppender.start();

            testSpecificLogger.addAppender(fileAppender);
            testSpecificLogger.setAdditive(false);

        } catch (Exception e) {
            logger.error("Failed to create test-specific logger", e);
        }
    }

    public static void info(String message) {
        Logger currentLogger = testLogger.get();
        if (currentLogger != null) {
            currentLogger.info(message);
        }
        logger.info(message);
    }

    public static void debug(String message) {
        Logger currentLogger = testLogger.get();
        if (currentLogger != null) {
            currentLogger.debug(message);
        }
        logger.debug(message);
    }

    public static void error(String message, Throwable throwable) {
        Logger currentLogger = testLogger.get();
        if (currentLogger != null) {
            currentLogger.error(message, throwable);
        }
        logger.error(message, throwable);
    }

    public static void warn(String message) {
        Logger currentLogger = testLogger.get();
        if (currentLogger != null) {
            currentLogger.warn(message);
        }
        logger.warn(message);
    }

    public static void logStep(String stepDescription) {
        String formattedStep = "STEP: " + stepDescription;
        info(formattedStep);

        // Also attach to Allure report
        Allure.step(stepDescription);
    }

    public static void logVerification(String verificationDescription, boolean status) {
        String formattedVerification = "VERIFICATION: " + verificationDescription + 
            " - STATUS: " + (status ? "PASS" : "FAIL");

        if (status) {
            info(formattedVerification);
        } else {
            error(formattedVerification, null);
        }
    }

    public static void cleanupTestLogger() {
        Logger currentLogger = testLogger.get();
        if (currentLogger != null) {
            currentLogger.detachAndStopAllAppenders();
        }
        testLogger.remove();
    }
}

// Jenkinsfile - Declarative Pipeline
pipeline {
    agent any

    parameters {
        choice(
            name: 'BROWSER',
            choices: ['chrome', 'firefox', 'edge'],
            description: 'Select browser for test execution'
        )
        choice(
            name: 'ENVIRONMENT',
            choices: ['dev', 'qa', 'staging'],
            description: 'Select test environment'
        )
        string(
            name: 'TAGS',
            defaultValue: '@smoke',
            description: 'Cucumber tags to execute'
        )
        booleanParam(
            name: 'PARALLEL_EXECUTION',
            defaultValue: true,
            description: 'Execute tests in parallel'
        )
    }

    environment {
        JAVA_HOME = '/usr/lib/jvm/java-11-openjdk'
        MAVEN_HOME = '/usr/share/maven'
        PATH = "${MAVEN_HOME}/bin:${JAVA_HOME}/bin:${PATH}"
    }

    stages {
        stage('Checkout') {
            steps {
                checkout scm
                script {
                    currentBuild.displayName = "${env.BUILD_NUMBER} - ${params.ENVIRONMENT} - ${params.BROWSER}"
                    currentBuild.description = "Tags: ${params.TAGS}, Parallel: ${params.PARALLEL_EXECUTION}"
                }
            }
        }

        stage('Environment Setup') {
            steps {
                sh '''
                    echo "Setting up test environment: ${ENVIRONMENT}"
                    echo "Browser: ${BROWSER}"
                    echo "Tags: ${TAGS}"

                    # Create environment-specific configuration
                    cp src/test/resources/config-${ENVIRONMENT}.properties src/test/resources/config.properties

                    # Create directories for reports
                    mkdir -p target/allure-results
                    mkdir -p target/cucumber-reports
                    mkdir -p target/screenshots
                    mkdir -p target/logs
                '''
            }
        }

        stage('Dependency Check') {
            steps {
                sh 'mvn dependency:resolve'
                sh 'mvn dependency:tree'
            }
        }

        stage('Code Quality') {
            parallel {
                stage('Static Analysis') {
                    steps {
                        sh 'mvn checkstyle:checkstyle'
                        sh 'mvn pmd:pmd'
                    }
                    post {
                        always {
                            publishHTML([
                                allowMissing: false,
                                alwaysLinkToLastBuild: true,
                                keepAll: true,
                                reportDir: 'target/site',
                                reportFiles: 'checkstyle.html,pmd.html',
                                reportName: 'Static Analysis Report'
                            ])
                        }
                    }
                }

                stage('Unit Tests') {
                    steps {
                        sh 'mvn test -Dtest=**/*UnitTest'
                    }
                    post {
                        always {
                            junit 'target/surefire-reports/**/*.xml'
                        }
                    }
                }
            }
        }

        stage('Integration Tests') {
            when {
                expression { params.PARALLEL_EXECUTION == true }
            }
            parallel {
                stage('Chrome Tests') {
                    steps {
                        sh '''
                            mvn test -Dbrowser=chrome \
                                    -Dcucumber.filter.tags="${TAGS}" \
                                    -Dgroups="chrome"
                        '''
                    }
                }

                stage('Firefox Tests') {
                    steps {
                        sh '''
                            mvn test -Dbrowser=firefox \
                                    -Dcucumber.filter.tags="${TAGS}" \
                                    -Dgroups="firefox"
                        '''
                    }
                }
            }
            post {
                always {
                    junit 'target/surefire-reports/**/*.xml'
                    cucumber reportTitle: 'Cucumber Report', 
                           fileIncludePattern: '**/cucumber.json',
                           jsonReportDirectory: 'target/cucumber-reports'
                }
            }
        }

        stage('Sequential Tests') {
            when {
                expression { params.PARALLEL_EXECUTION == false }
            }
            steps {
                sh '''
                    mvn test -Dbrowser=${BROWSER} \
                            -Dcucumber.filter.tags="${TAGS}" \
                            -Dgroups="sequential"
                '''
            }
            post {
                always {
                    junit 'target/surefire-reports/**/*.xml'
                    cucumber reportTitle: 'Cucumber Report', 
                           fileIncludePattern: '**/cucumber.json',
                           jsonReportDirectory: 'target/cucumber-reports'
                }
            }
        }

        stage('Generate Reports') {
            steps {
                sh 'mvn allure:report'
                sh 'mvn site:site'
            }
            post {
                always {
                    publishHTML([
                        allowMissing: false,
                        alwaysLinkToLastBuild: true,
                        keepAll: true,
                        reportDir: 'target/site/allure-maven-plugin',
                        reportFiles: 'index.html',
                        reportName: 'Allure Test Report'
                    ])

                    publishHTML([
                        allowMissing: false,
                        alwaysLinkToLastBuild: true,
                        keepAll: true,
                        reportDir: 'target/site',
                        reportFiles: 'surefire-report.html',
                        reportName: 'Surefire Test Report'
                    ])
                }
            }
        }

        stage('Security Scan') {
            steps {
                sh 'mvn org.owasp:dependency-check-maven:check'
            }
            post {
                always {
                    dependencyCheckPublisher(pattern: '**/dependency-check-report.xml')
                }
            }
        }
    }

    post {
        always {
            // Archive test artifacts
            archiveArtifacts artifacts: 'target/**/*.png, target/**/*.log, target/**/*.html', 
                            allowEmptyArchive: true

            // Clean workspace
            cleanWs()
        }

        success {
            emailext (
                subject: "SUCCESS: Test Automation Build ${env.BUILD_NUMBER}",
                body: """
                <h2>Test Execution Completed Successfully</h2>
                <p><strong>Build:</strong> ${env.BUILD_NUMBER}</p>
                <p><strong>Environment:</strong> ${params.ENVIRONMENT}</p>
                <p><strong>Browser:</strong> ${params.BROWSER}</p>
                <p><strong>Tags:</strong> ${params.TAGS}</p>
                <p><a href="${env.BUILD_URL}allure/">View Allure Report</a></p>
                <p><a href="${env.BUILD_URL}cucumber-html-reports/overview-features.html">View Cucumber Report</a></p>
                """,
                to: 'qa-team@company.com',
                attachLog: false
            )
        }

        failure {
            emailext (
                subject: "FAILED: Test Automation Build ${env.BUILD_NUMBER}",
                body: """
                <h2>Test Execution Failed</h2>
                <p><strong>Build:</strong> ${env.BUILD_NUMBER}</p>
                <p><strong>Environment:</strong> ${params.ENVIRONMENT}</p>
                <p><strong>Browser:</strong> ${params.BROWSER}</p>
