// BasePage.cs
using OpenQA.Selenium;
using OpenQA.Selenium.Support.UI;
using OpenQA.Selenium.Interactions;
using System.Collections.ObjectModel;

namespace Tests.UI.Pages
{
    public abstract class BasePage
    {
        protected IWebDriver Driver;
        protected WebDriverWait Wait;
        protected IJavaScriptExecutor JsExecutor;

        public BasePage(IWebDriver driver)
        {
            Driver = driver;
            Wait = new WebDriverWait(driver, TimeSpan.FromSeconds(30));
            JsExecutor = (IJavaScriptExecutor)driver;
        }

        // Common page interactions
        protected void Click(IWebElement element)
        {
            Wait.Until(d => element.Displayed && element.Enabled);
            element.Click();
        }

        protected void Type(IWebElement element, string text)
        {
            Wait.Until(d => element.Displayed && element.Enabled);
            element.Clear();
            element.SendKeys(text);
        }

        protected void SelectDropdownByText(IWebElement dropdown, string text)
        {
            var selectElement = new SelectElement(dropdown);
            selectElement.SelectByText(text);
        }

        protected void SelectDropdownByValue(IWebElement dropdown, string value)
        {
            var selectElement = new SelectElement(dropdown);
            selectElement.SelectByValue(value);
        }

        protected string GetText(IWebElement element)
        {
            Wait.Until(d => element.Displayed);
            return element.Text;
        }

        protected bool IsElementDisplayed(IWebElement element)
        {
            try
            {
                return element.Displayed;
            }
            catch (NoSuchElementException)
            {
                return false;
            }
        }

        protected bool IsElementEnabled(IWebElement element)
        {
            try
            {
                return element.Enabled;
            }
            catch (NoSuchElementException)
            {
                return false;
            }
        }

        protected void WaitForPageToLoad()
        {
            Wait.Until(d => JsExecutor.ExecuteScript("return document.readyState").Equals("complete"));
        }

        protected void ScrollToElement(IWebElement element)
        {
            JsExecutor.ExecuteScript("arguments[0].scrollIntoView(true);", element);
        }

        protected void HoverOverElement(IWebElement element)
        {
            var actions = new Actions(Driver);
            actions.MoveToElement(element).Perform();
        }

        protected void SwitchToFrame(IWebElement frameElement)
        {
            Driver.SwitchTo().Frame(frameElement);
        }

        protected void SwitchToDefaultContent()
        {
            Driver.SwitchTo().DefaultContent();
        }

        protected ReadOnlyCollection<IWebElement> FindElements(By locator)
        {
            return Driver.FindElements(locator);
        }

        protected IWebElement FindElement(By locator)
        {
            return Wait.Until(d => d.FindElement(locator));
        }

        // Virtual method for page-specific initialization
        public virtual void WaitForPage()
        {
            WaitForPageToLoad();
        }
    }
}

