using OpenQA.Selenium;
using OpenQA.Selenium.Support.UI;
using Tests.UI.Models;

namespace Tests.UI.Pages
{
    public class LoginPage : BasePage
    {
        // Page Locators
        private By UsernameField => By.Id("username");
        private By PasswordField => By.Id("password");
        private By LoginButton => By.Id("login-btn");
        private By ErrorMessage => By.ClassName("error-message");
        private By SuccessMessage => By.ClassName("success-message");
        private By ForgotPasswordLink => By.LinkText("Forgot Password?");
        private By RememberMeCheckbox => By.Id("remember-me");

        public LoginPage(IWebDriver driver) : base(driver)
        {
        }

        // Page Actions
        public void EnterUsername(string username)
        {
            Type(FindElement(UsernameField), username);
        }

        public void EnterPassword(string password)
        {
            Type(FindElement(PasswordField), password);
        }

        public void ClickLogin()
        {
            Click(FindElement(LoginButton));
        }

        public void ClickForgotPassword()
        {
            Click(FindElement(ForgotPasswordLink));
        }

        public void SetRememberMe(bool remember)
        {
            var checkbox = FindElement(RememberMeCheckbox);
            if (remember != checkbox.Selected)
            {
                checkbox.Click();
            }
        }

        // Business Logic Methods
        public DashboardPage Login(string username, string password)
        {
            EnterUsername(username);
            EnterPassword(password);
            ClickLogin();
            return new DashboardPage(Driver);
        }

        public DashboardPage Login(User user)
        {
            return Login(user.Username, user.Password);
        }

        public void LoginWithInvalidCredentials(string username, string password)
        {
            EnterUsername(username);
            EnterPassword(password);
            ClickLogin();
        }

        // Verification Methods
        public bool IsErrorMessageDisplayed()
        {
            return IsElementDisplayed(FindElement(ErrorMessage));
        }

        public string GetErrorMessage()
        {
            return GetText(FindElement(ErrorMessage));
        }

        public bool IsLoginSuccessful()
        {
            return IsElementDisplayed(FindElement(SuccessMessage));
        }

        public bool IsLoginPageDisplayed()
        {
            try
            {
                return FindElement(UsernameField).Displayed && 
                       FindElement(PasswordField).Displayed;
            }
            catch (NoSuchElementException)
            {
                return false;
            }
        }

        public override void WaitForPage()
        {
            base.WaitForPage();
            Wait.Until(d => FindElement(UsernameField).Displayed);
            Wait.Until(d => FindElement(PasswordField).Displayed);
        }
    }
}

