// WebDriverFactory.cs
using OpenQA.Selenium;
using OpenQA.Selenium.Chrome;
using OpenQA.Selenium.Firefox;
using OpenQA.Selenium.Edge;
using OpenQA.Selenium.Remote;
using Microsoft.Extensions.Configuration;

namespace Tests.UI.Utilities
{
    public interface IWebDriverFactory
    {
        IWebDriver CreateDriver(string browserType = null);
        void DisposeDriver(IWebDriver driver);
    }

    public class WebDriverFactory : IWebDriverFactory, IDisposable
    {
        private readonly IConfiguration _configuration;
        private readonly List<IWebDriver> _drivers;

        public WebDriverFactory(IConfiguration configuration)
        {
            _configuration = configuration;
            _drivers = new List<IWebDriver>();
        }

        public IWebDriver CreateDriver(string browserType = null)
        {
            browserType ??= _configuration["TestConfiguration:Browser"] ?? "Chrome";
            var headless = bool.Parse(_configuration["TestConfiguration:Headless"] ?? "false");

            IWebDriver driver;

            switch (browserType.ToLower())
            {
                case "firefox":
                    driver = CreateFirefoxDriver(headless);
                    break;
                case "edge":
                    driver = CreateEdgeDriver(headless);
                    break;
                case "remote":
                    driver = CreateRemoteDriver();
                    break;
                case "chrome":
                default:
                    driver = CreateChromeDriver(headless);
                    break;
            }

            // Configure timeouts
            var implicitWait = TimeSpan.FromSeconds(
                int.Parse(_configuration["TestConfiguration:ImplicitWait"] ?? "10"));
            var pageLoadTimeout = TimeSpan.FromSeconds(
                int.Parse(_configuration["TestConfiguration:PageLoadTimeout"] ?? "30"));

            driver.Manage().Timeouts().ImplicitWait = implicitWait;
            driver.Manage().Timeouts().PageLoad = pageLoadTimeout;
            driver.Manage().Window.Maximize();

            _drivers.Add(driver);
            return driver;
        }

        private IWebDriver CreateChromeDriver(bool headless)
        {
            var options = new ChromeOptions();

            if (headless)
            {
                options.AddArgument("--headless");
            }

            options.AddArgument("--no-sandbox");
            options.AddArgument("--disable-dev-shm-usage");
            options.AddArgument("--disable-gpu");
            options.AddArgument("--window-size=1920,1080");
            options.AddArgument("--ignore-certificate-errors");

            // Performance improvements
            options.AddArgument("--disable-extensions");
            options.AddArgument("--disable-plugins");
            options.AddArgument("--disable-images");

            // Additional options for stability
            options.AddAdditionalChromeOption("useAutomationExtension", false);
            options.AddExcludedArgument("enable-automation");

            var service = ChromeDriverService.CreateDefaultService();
            service.HideCommandPromptWindow = true;

            return new ChromeDriver(service, options);
        }

        private IWebDriver CreateFirefoxDriver(bool headless)
        {
            var options = new FirefoxOptions();

            if (headless)
            {
                options.AddArgument("--headless");
            }

            options.AddArgument("--width=1920");
            options.AddArgument("--height=1080");

            var service = FirefoxDriverService.CreateDefaultService();
            service.HideCommandPromptWindow = true;

            return new FirefoxDriver(service, options);
        }

        private IWebDriver CreateEdgeDriver(bool headless)
        {
            var options = new EdgeOptions();

            if (headless)
            {
                options.AddArgument("--headless");
            }

            options.AddArgument("--no-sandbox");
            options.AddArgument("--disable-dev-shm-usage");
            options.AddArgument("--window-size=1920,1080");

            var service = EdgeDriverService.CreateDefaultService();
            service.HideCommandPromptWindow = true;

            return new EdgeDriver(service, options);
        }

        private IWebDriver CreateRemoteDriver()
        {
            var gridUrl = _configuration["SeleniumGrid:Url"] ?? "http://localhost:4444/wd/hub";
            var browser = _configuration["SeleniumGrid:Browser"] ?? "chrome";
            var platform = _configuration["SeleniumGrid:Platform"] ?? "LINUX";

            var capabilities = new DesiredCapabilities();
            capabilities.SetCapability(CapabilityType.BrowserName, browser);
            capabilities.SetCapability(CapabilityType.Platform, platform);
            capabilities.SetCapability("version", "latest");

            // Additional capabilities for better video recording
            capabilities.SetCapability("enableVNC", true);
            capabilities.SetCapability("enableVideo", true);
            capabilities.SetCapability("videoName", $"{Guid.NewGuid()}.mp4");

            return new RemoteWebDriver(new Uri(gridUrl), capabilities);
        }

        public void DisposeDriver(IWebDriver driver)
        {
            try
            {
                if (driver != null)
                {
                    driver.Quit();
                    driver.Dispose();
                    _drivers.Remove(driver);
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error disposing driver: {ex.Message}");
            }
        }

        public void Dispose()
        {
            foreach (var driver in _drivers.ToList())
            {
                DisposeDriver(driver);
            }
        }
    }
}

// CustomWaitStrategies.cs
using OpenQA.Selenium;
using OpenQA.Selenium.Support.UI;
using System.Collections.ObjectModel;

namespace Tests.UI.Utilities
{
    public interface ICustomWait
    {
        IWebElement WaitForElement(By locator, int timeoutSeconds = 30);
        IWebElement WaitForElementToBeClickable(By locator, int timeoutSeconds = 30);
        IWebElement WaitForElementToBeVisible(By locator, int timeoutSeconds = 30);
        bool WaitForElementToDisappear(By locator, int timeoutSeconds = 30);
        bool WaitForTextToBePresent(By locator, string text, int timeoutSeconds = 30);
        void WaitForAjaxToComplete(int timeoutSeconds = 30);
        void WaitForPageToLoad(int timeoutSeconds = 30);
        void WaitForAngularToComplete(int timeoutSeconds = 30);
    }

    public class CustomWait : ICustomWait
    {
        private readonly IWebDriver _driver;
        private readonly ITestLogger _logger;

        public CustomWait(IWebDriver driver, ITestLogger logger)
        {
            _driver = driver;
            _logger = logger;
        }

        public IWebElement WaitForElement(By locator, int timeoutSeconds = 30)
        {
            try
            {
                var wait = new WebDriverWait(_driver, TimeSpan.FromSeconds(timeoutSeconds));
                return wait.Until(d => d.FindElement(locator));
            }
            catch (WebDriverTimeoutException)
            {
                _logger.Error($"Element not found within {timeoutSeconds} seconds: {locator}");
                throw;
            }
        }

        public IWebElement WaitForElementToBeClickable(By locator, int timeoutSeconds = 30)
        {
            try
            {
                var wait = new WebDriverWait(_driver, TimeSpan.FromSeconds(timeoutSeconds));
                return wait.Until(ExpectedConditions.ElementToBeClickable(locator));
            }
            catch (WebDriverTimeoutException)
            {
                _logger.Error($"Element not clickable within {timeoutSeconds} seconds: {locator}");
                throw;
            }
        }

        public IWebElement WaitForElementToBeVisible(By locator, int timeoutSeconds = 30)
        {
            try
            {
                var wait = new WebDriverWait(_driver, TimeSpan.FromSeconds(timeoutSeconds));
                return wait.Until(ExpectedConditions.ElementIsVisible(locator));
            }
            catch (WebDriverTimeoutException)
            {
                _logger.Error($"Element not visible within {timeoutSeconds} seconds: {locator}");
                throw;
            }
        }

        public bool WaitForElementToDisappear(By locator, int timeoutSeconds = 30)
        {
            try
            {
                var wait = new WebDriverWait(_driver, TimeSpan.FromSeconds(timeoutSeconds));
                return wait.Until(d =>
                {
                    try
                    {
                        var element = d.FindElement(locator);
                        return !element.Displayed;
                    }
                    catch (NoSuchElementException)
                    {
                        return true;
                    }
                    catch (StaleElementReferenceException)
                    {
                        return true;
                    }
                });
            }
            catch (WebDriverTimeoutException)
            {
                _logger.Error($"Element did not disappear within {timeoutSeconds} seconds: {locator}");
                return false;
            }
        }

        public bool WaitForTextToBePresent(By locator, string text, int timeoutSeconds = 30)
        {
            try
            {
                var wait = new WebDriverWait(_driver, TimeSpan.FromSeconds(timeoutSeconds));
                return wait.Until(d =>
                {
                    try
                    {
                        var element = d.FindElement(locator);
                        return element.Text.Contains(text);
                    }
                    catch (NoSuchElementException)
                    {
                        return false;
                    }
                });
            }
            catch (WebDriverTimeoutException)
            {
                _logger.Error($"Text '{text}' not found within {timeoutSeconds} seconds: {locator}");
                return false;
            }
        }

        public void WaitForAjaxToComplete(int timeoutSeconds = 30)
        {
            try
            {
                var wait = new WebDriverWait(_driver, TimeSpan.FromSeconds(timeoutSeconds));
                wait.Until(d =>
                {
                    var jsExecutor = (IJavaScriptExecutor)d;
                    return (bool)jsExecutor.ExecuteScript("return jQuery.active == 0");
                });
            }
            catch (Exception ex)
            {
                _logger.Warn($"AJAX wait completed with exception: {ex.Message}");
            }
        }

        public void WaitForPageToLoad(int timeoutSeconds = 30)
        {
            try
            {
                var wait = new WebDriverWait(_driver, TimeSpan.FromSeconds(timeoutSeconds));
                wait.Until(d =>
                {
                    var jsExecutor = (IJavaScriptExecutor)d;
                    return jsExecutor.ExecuteScript("return document.readyState").Equals("complete");
                });
            }
            catch (WebDriverTimeoutException)
            {
                _logger.Error($"Page did not load within {timeoutSeconds} seconds");
                throw;
            }
        }

        public void WaitForAngularToComplete(int timeoutSeconds = 30)
        {
            try
            {
                var wait = new WebDriverWait(_driver, TimeSpan.FromSeconds(timeoutSeconds));
                wait.Until(d =>
                {
                    var jsExecutor = (IJavaScriptExecutor)d;
                    return (bool)jsExecutor.ExecuteScript(
                        "return angular.element(document).injector().get('$http').pendingRequests.length === 0");
                });
            }
            catch (Exception ex)
            {
                _logger.Warn($"Angular wait completed with exception: {ex.Message}");
            }
        }

        // Retry mechanism for flaky operations
        public T Retry<T>(Func<T> operation, int maxRetries = 3, int delaySeconds = 2)
        {
            var attempts = 0;
            while (attempts < maxRetries)
            {
                try
                {
                    return operation();
                }
                catch (Exception ex) when (attempts < maxRetries - 1)
                {
                    attempts++;
                    _logger.Warn($"Attempt {attempts} failed, retrying in {delaySeconds} seconds: {ex.Message}");
                    Thread.Sleep(TimeSpan.FromSeconds(delaySeconds));
                }
            }

            throw new InvalidOperationException($"Operation failed after {maxRetries} attempts");
        }
    }
}

// TestHooks.cs
using TechTalk.SpecFlow;
using Allure.Net.Commons;

namespace Tests.UI.Hooks
{
    [Binding]
    public class TestHooks
    {
        private readonly IObjectContainer _objectContainer;
        private readonly ScenarioContext _scenarioContext;
        private IWebDriver _driver;
        private ITestLogger _logger;
        private IScreenshotHelper _screenshotHelper;

        public TestHooks(IObjectContainer objectContainer, ScenarioContext scenarioContext)
        {
            _objectContainer = objectContainer;
            _scenarioContext = scenarioContext;
        }

        [BeforeTestRun]
        public static void BeforeTestRun()
        {
            // Initialize test run
            TestLogger.InitializeTestRun();

            // Create report directories
            Directory.CreateDirectory("./allure-results");
            Directory.CreateDirectory("./screenshots");
            Directory.CreateDirectory("./test-logs");

            Console.WriteLine("Test Run Started");
        }

        [BeforeScenario]
        public void BeforeScenario()
        {
            // Initialize services
            var serviceProvider = _objectContainer.Resolve<IServiceProvider>();
            var driverFactory = serviceProvider.GetService<IWebDriverFactory>();
            _logger = serviceProvider.GetService<ITestLogger>();
            _screenshotHelper = serviceProvider.GetService<IScreenshotHelper>();

            // Create WebDriver
            _driver = driverFactory.CreateDriver();
            _objectContainer.RegisterInstanceAs(_driver);
            _scenarioContext.Set(_driver, "Driver");

            // Initialize test context
            var scenarioName = _scenarioContext.ScenarioInfo.Title;
            var tags = string.Join(", ", _scenarioContext.ScenarioInfo.Tags);

            _logger.InitializeTestLogger(scenarioName);
            _logger.Info($"Starting scenario: {scenarioName}");
            _logger.Info($"Tags: {tags}");

            // Allure setup
            AllureLifecycle.Instance.UpdateTestCase(testCase =>
            {
                testCase.labels.Add(new Label { name = "feature", value = _scenarioContext.ScenarioInfo.FeatureInfo.Title });
                testCase.labels.Add(new Label { name = "story", value = scenarioName });
                testCase.labels.AddRange(_scenarioContext.ScenarioInfo.Tags.Select(tag => new Label { name = "tag", value = tag }));
            });
        }

        [BeforeStep]
        public void BeforeStep()
        {
            var stepInfo = _scenarioContext.StepContext.StepInfo.Text;
            _logger.Info($"Executing step: {stepInfo}");

            // Wait for page stability before each step
            var customWait = new CustomWait(_driver, _logger);
            customWait.WaitForPageToLoad(10);
        }

        [AfterStep]
        public void AfterStep()
        {
            var stepInfo = _scenarioContext.StepContext.StepInfo.Text;

            if (_scenarioContext.TestError != null)
            {
                _logger.Error($"Step failed: {stepInfo}", _scenarioContext.TestError);

                // Capture screenshot on step failure
                try
                {
                    var screenshotPath = _screenshotHelper.CaptureScreenshot(_driver, $"step_failure_{DateTime.Now:yyyyMMdd_HHmmss}");
                    _logger.Info($"Screenshot captured: {screenshotPath}");

                    // Attach to Allure report
                    AllureLifecycle.Instance.AddAttachment(
                        $"Step Failure - {stepInfo}", 
                        "image/png", 
                        _screenshotHelper.CaptureScreenshotAsBytes(_driver)
                    );
                }
                catch (Exception ex)
                {
                    _logger.Error("Failed to capture screenshot", ex);
                }
            }
            else
            {
                _logger.Info($"Step completed: {stepInfo}");
            }
        }

        [AfterScenario]
        public void AfterScenario()
        {
            var scenarioName = _scenarioContext.ScenarioInfo.Title;

            try
            {
                if (_scenarioContext.TestError != null)
                {
                    _logger.Error($"Scenario FAILED: {scenarioName}", _scenarioContext.TestError);

                    // Capture final screenshot on scenario failure
                    var screenshotPath = _screenshotHelper.CaptureScreenshot(_driver, $"scenario_failure_{DateTime.Now:yyyyMMdd_HHmmss}");

                    // Attach page source to Allure
                    AllureLifecycle.Instance.AddAttachment(
                        $"Page Source - {scenarioName}", 
                        "text/html", 
                        _driver.PageSource
                    );

                    // Attach browser logs if available
                    AttachBrowserLogs();
                }
                else
                {
                    _logger.Info($"Scenario PASSED: {scenarioName}");
                }

                // Log scenario duration
                _logger.Info($"Scenario completed: {scenarioName}");
            }
            finally
            {
                // Cleanup WebDriver
                var driverFactory = _objectContainer.Resolve<IWebDriverFactory>();
                driverFactory.DisposeDriver(_driver);

                // Cleanup test logger
                _logger.CleanupTestLogger();
            }
        }

        [AfterTestRun]
        public static void AfterTestRun()
        {
            // Generate final reports
            TestLogger.FinalizeTestRun();

            Console.WriteLine("Test Run Completed");

            // Optional: Trigger report generation
            GenerateAllureReport();
        }

        private void AttachBrowserLogs()
        {
            try
            {
                var logs = _driver.Manage().Logs;
                var browserLogs = logs.GetLog(LogType.Browser);

                if (browserLogs.Any())
                {
                    var logContent = string.Join("\n", browserLogs.Select(log => $"{log.Timestamp}: {log.Message}"));
                    AllureLifecycle.Instance.AddAttachment("Browser Logs", "text/plain", logContent);
                }
            }
            catch (Exception ex)
            {
                _logger.Warn($"Failed to capture browser logs: {ex.Message}");
            }
        }

        private static void GenerateAllureReport()
        {
            try
            {
                // This would typically be done via command line
                // allure serve allure-results
                Console.WriteLine("Allure report generation completed");
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Failed to generate Allure report: {ex.Message}");
            }
        }
    }
}

