        {
            testResult.labels.Add(new Label { name = "environment", value = $"{name}={value}" });
        }
    }

    // Custom Allure steps for better reporting
    public class AllureSteps
    {
        public static void Step(string stepName, Action action)
        {
            AllureApi.Step(stepName, () =>
            {
                try
                {
                    action();
                }
                catch (Exception ex)
                {
                    // Capture screenshot on step failure
                    var screenshotBytes = CaptureScreenshot();
                    if (screenshotBytes != null)
                    {
                        AllureApi.AddAttachment("Step Failure Screenshot", "image/png", screenshotBytes);
                    }
                    throw;
                }
            });
        }

        public static T Step<T>(string stepName, Func<T> function)
        {
            return AllureApi.Step(stepName, () =>
            {
                try
                {
                    return function();
                }
                catch (Exception ex)
                {
                    var screenshotBytes = CaptureScreenshot();
                    if (screenshotBytes != null)
                    {
                        AllureApi.AddAttachment("Step Failure Screenshot", "image/png", screenshotBytes);
                    }
                    throw;
                }
            });
        }

        private static byte[] CaptureScreenshot()
        {
            try
            {
                var driver = ParallelTestContext.Driver;
                if (driver is ITakesScreenshot takesScreenshot)
                {
                    return takesScreenshot.GetScreenshot().AsByteArray;
                }
            }
            catch
            {
                // Ignore screenshot capture errors
            }
            return null;
        }
    }

    // Enhanced test context for Allure
    public class AllureTestContext
    {
        private readonly TestResult _testResult;

        public AllureTestContext(string testName)
        {
            _testResult = new TestResult
            {
                name = testName,
                start = DateTimeOffset.Now.ToUnixTimeMilliseconds()
            };
        }

        public void AddParameter(string name, string value)
        {
            _testResult.AddTestParameter(name, value);
        }

        public void AddEnvironmentInfo(string browser, string environment, string version)
        {
            _testResult.AddEnvironmentVariable("Browser", browser);
            _testResult.AddEnvironmentVariable("Environment", environment);
            _testResult.AddEnvironmentVariable("Version", version);
        }

        public void AddCustomLabel(string labelName, string labelValue)
        {
            _testResult.AddTestLabel(labelName, labelValue);
        }

        public void AddIssueLink(string issueUrl, string issueKey)
        {
            _testResult.AddTestLink(issueUrl, $"Issue: {issueKey}");
        }

        public void AddTestManagementLink(string tmUrl, string testCaseId)
        {
            _testResult.AddTestLink(tmUrl, $"Test Case: {testCaseId}");
        }

        public void CompleteTest(Status status, string errorMessage = null)
        {
            _testResult.status = status;
            _testResult.statusDetails = new StatusDetails
            {
                message = errorMessage,
                trace = errorMessage
            };
            _testResult.stop = DateTimeOffset.Now.ToUnixTimeMilliseconds();

            AllureLifecycle.Instance.UpdateTestCase(_testResult.uuid, tc =>
            {
                tc.status = _testResult.status;
                tc.statusDetails = _testResult.statusDetails;
            });
        }
    }
