// ApiTestBase.cs - Base class for API testing
using RestSharp;
using Newtonsoft.Json;
using FluentAssertions;

namespace Tests.API
{
    public abstract class ApiTestBase
    {
        protected RestClient Client;
        protected string BaseUrl;
        protected string AuthToken;

        protected ApiTestBase(string baseUrl)
        {
            BaseUrl = baseUrl;
            Client = new RestClient(baseUrl);
            Client.AddDefaultHeader("Content-Type", "application/json");
        }

        protected void SetAuthentication(string token)
        {
            AuthToken = token;
            Client.AddDefaultHeader("Authorization", $"Bearer {token}");
        }

        protected T ExecuteRequest<T>(RestRequest request) where T : new()
        {
            var response = Client.Execute<T>(request);

            if (!response.IsSuccessful)
            {
                throw new HttpRequestException($"API Request failed: {response.StatusCode} - {response.ErrorMessage}");
            }

            return response.Data;
        }

        protected async Task<T> ExecuteRequestAsync<T>(RestRequest request) where T : new()
        {
            var response = await Client.ExecuteAsync<T>(request);

            if (!response.IsSuccessful)
            {
                throw new HttpRequestException($"API Request failed: {response.StatusCode} - {response.ErrorMessage}");
            }

            return response.Data;
        }

        protected void VerifyResponse<T>(T response, Action<T> assertions)
        {
            assertions(response);
        }

        protected void VerifyResponseStatusCode(RestResponse response, System.Net.HttpStatusCode expectedStatusCode)
        {
            response.StatusCode.Should().Be(expectedStatusCode);
        }
    }

    // User API Tests
    public class UserApiTests : ApiTestBase
    {
        public UserApiTests() : base("https://api.example.com") { }

        public User CreateUser(User user)
        {
            var request = new RestRequest("/users", Method.Post);
            request.AddJsonBody(user);

            return ExecuteRequest<User>(request);
        }

        public User GetUser(int userId)
        {
            var request = new RestRequest($"/users/{userId}", Method.Get);
            return ExecuteRequest<User>(request);
        }

        public List<User> GetUsers()
        {
            var request = new RestRequest("/users", Method.Get);
            return ExecuteRequest<List<User>>(request);
        }

        public User UpdateUser(int userId, User user)
        {
            var request = new RestRequest($"/users/{userId}", Method.Put);
            request.AddJsonBody(user);
            return ExecuteRequest<User>(request);
        }

        public void DeleteUser(int userId)
        {
            var request = new RestRequest($"/users/{userId}", Method.Delete);
            var response = Client.Execute(request);
            VerifyResponseStatusCode(response, System.Net.HttpStatusCode.NoContent);
        }
    }

    // API Test Integration with UI Tests
    public class ApiUiIntegrationTests
    {
        private readonly UserApiTests _apiTests;
        private readonly LoginPage _loginPage;

        public ApiUiIntegrationTests(UserApiTests apiTests, LoginPage loginPage)
        {
            _apiTests = apiTests;
            _loginPage = loginPage;
        }

        public void CreateUserAndVerifyInUI(string username, string password)
        {
            // Create user via API
            var user = new User { Username = username, Password = password, Email = $"{username}@test.com" };
            var createdUser = _apiTests.CreateUser(user);

            // Verify user can login via UI
            var dashboard = _loginPage.Login(username, password);
            dashboard.IsDashboardLoaded().Should().BeTrue();
        }
    }
}

