using OpenQA.Selenium;
using OpenQA.Selenium.DevTools;
using OpenQA.Selenium.DevTools.V114.Performance;
using System.Diagnostics;

namespace Tests.Performance
{
    public interface IPerformanceMonitor
    {
        Task StartMonitoring();
        Task<PerformanceMetrics> StopMonitoring();
        Task<PageLoadMetrics> MeasurePageLoad(string pageUrl);
        Task<ApiResponseMetrics> MeasureApiCall(Func<Task> apiCall);
        void AssertPerformanceThresholds(PerformanceMetrics metrics);
    }

    public class PerformanceMonitor : IPerformanceMonitor
    {
        private readonly IWebDriver _driver;
        private IDevToolsSession _devToolsSession;
        private bool _isMonitoring = false;

        public PerformanceMonitor(IWebDriver driver)
        {
            _driver = driver;
        }

        public async Task StartMonitoring()
        {
            if (_driver is IDevTools)
            {
                var devTools = (IDevTools)_driver;
                _devToolsSession = devTools.GetDevToolsSession();

                await _devToolsSession.SendCommand<EnableCommandSettings>(new EnableCommandSettings());
                _isMonitoring = true;
            }
        }

        public async Task<PerformanceMetrics> StopMonitoring()
        {
            if (!_isMonitoring || _devToolsSession == null)
                return new PerformanceMetrics();

            var metricsResponse = await _devToolsSession.SendCommand<GetMetricsCommandSettings, GetMetricsCommandResponse>(
                new GetMetricsCommandSettings());

            _isMonitoring = false;

            return new PerformanceMetrics
            {
                Metrics = metricsResponse.Metrics.ToDictionary(m => m.Name, m => m.Value),
                Timestamp = DateTime.UtcNow
            };
        }

        public async Task<PageLoadMetrics> MeasurePageLoad(string pageUrl)
        {
            var stopwatch = Stopwatch.StartNew();

            await StartMonitoring();

            // Navigate to page
            _driver.Navigate().GoToUrl(pageUrl);

            // Wait for page to be completely loaded
            var wait = new WebDriverWait(_driver, TimeSpan.FromSeconds(30));
            wait.Until(d => ((IJavaScriptExecutor)d).ExecuteScript("return document.readyState").Equals("complete"));

            stopwatch.Stop();

            var performanceMetrics = await StopMonitoring();

            return new PageLoadMetrics
            {
                LoadTime = stopwatch.ElapsedMilliseconds,
                PerformanceMetrics = performanceMetrics,
                Url = pageUrl
            };
        }

        public async Task<ApiResponseMetrics> MeasureApiCall(Func<Task> apiCall)
        {
            var stopwatch = Stopwatch.StartNew();

            try
            {
                await apiCall();
            }
            finally
            {
                stopwatch.Stop();
            }

            return new ApiResponseMetrics
            {
                ResponseTime = stopwatch.ElapsedMilliseconds,
                Timestamp = DateTime.UtcNow
            };
        }

        public void AssertPerformanceThresholds(PerformanceMetrics metrics)
        {
            // Define performance thresholds
            const long maxPageLoadTime = 3000; // 3 seconds
            const long maxFirstContentfulPaint = 1500; // 1.5 seconds
            const long maxLargestContentfulPaint = 2500; // 2.5 seconds

            if (metrics.Metrics.TryGetValue("FirstContentfulPaint", out var fcp))
            {
                fcp.Should().BeLessThan(maxFirstContentfulPaint, 
                    $"First Contentful Paint should be less than {maxFirstContentfulPaint}ms");
            }

            if (metrics.Metrics.TryGetValue("LargestContentfulPaint", out var lcp))
            {
                lcp.Should().BeLessThan(maxLargestContentfulPaint, 
                    $"Largest Contentful Paint should be less than {maxLargestContentfulPaint}ms");
            }
        }
    }

    public class PerformanceMetrics
    {
        public Dictionary<string, double> Metrics { get; set; } = new Dictionary<string, double>();
        public DateTime Timestamp { get; set; }
    }

    public class PageLoadMetrics
    {
        public long LoadTime { get; set; }
        public PerformanceMetrics PerformanceMetrics { get; set; }
        public string Url { get; set; }
    }

    public class ApiResponseMetrics
    {
        public long ResponseTime { get; set; }
        public DateTime Timestamp { get; set; }
    }

    // Performance-aware UI Tests
    public class PerformanceAwareLoginTests
    {
        private readonly LoginPage _loginPage;
        private readonly IPerformanceMonitor _performanceMonitor;

        public PerformanceAwareLoginTests(LoginPage loginPage, IPerformanceMonitor performanceMonitor)
        {
            _loginPage = loginPage;
            _performanceMonitor = performanceMonitor;
        }

        public async Task<PageLoadMetrics> TestLoginWithPerformanceMeasurement(string username, string password)
        {
            // Measure page load performance
            var pageLoadMetrics = await _performanceMonitor.MeasurePageLoad(_loginPage.GetPageUrl());

            // Perform login
            var dashboard = _loginPage.Login(username, password);

            // Verify functionality
            dashboard.IsDashboardLoaded().Should().BeTrue();

            // Assert performance thresholds
            _performanceMonitor.AssertPerformanceThresholds(pageLoadMetrics.PerformanceMetrics);

            return pageLoadMetrics;
        }
    }
}

// SecurityTestBase.cs
using System.Security.Cryptography;
using System.Text;
using OpenQA.Selenium;

namespace Tests.Security
{
    public interface ISecurityTester
    {
        Task<bool> CheckForSqlInjectionVulnerability(string inputFieldId, string payload);
        Task<bool> CheckForXssVulnerability(string inputFieldId, string payload);
        Task<bool> VerifySslCertificate(string url);
        Task<bool> CheckForInformationDisclosure(string url);
        void VerifySecurityHeaders(HttpResponseMessage response);
        Task<bool> TestAuthenticationBypass(string protectedUrl);
    }

    public class SecurityTester : ISecurityTester
    {
        private readonly IWebDriver _driver;
        private readonly HttpClient _httpClient;

        public SecurityTester(IWebDriver driver)
        {
            _driver = driver;
            _httpClient = new HttpClient();
        }

        public async Task<bool> CheckForSqlInjectionVulnerability(string inputFieldId, string payload)
        {
            try
            {
                // SQL Injection test payloads
                var sqlPayloads = new[]
                {
                    "' OR '1'='1",
                    "; DROP TABLE users --",
                    "' UNION SELECT username, password FROM users --"
                };

                foreach (var sqlPayload in sqlPayloads)
                {
                    var inputElement = _driver.FindElement(By.Id(inputFieldId));
                    inputElement.Clear();
                    inputElement.SendKeys(sqlPayload);

                    // Submit form or trigger action
                    inputElement.SendKeys(Keys.Enter);

                    // Check for error messages or unexpected behavior
                    var pageSource = _driver.PageSource.ToLower();

                    if (pageSource.Contains("sql") || pageSource.Contains("database") || 
                        pageSource.Contains("error") || pageSource.Contains("exception"))
                    {
                        return true; // Potential vulnerability found
                    }
                }

                return false;
            }
            catch (Exception ex)
            {
                Console.WriteLine($"SQL Injection test failed: {ex.Message}");
                return false;
            }
        }

        public async Task<bool> CheckForXssVulnerability(string inputFieldId, string payload)
        {
            try
            {
                // XSS test payloads
                var xssPayloads = new[]
                {
                    "<script>alert('XSS')</script>",
                    "<img src=x onerror=alert('XSS')>",
                    "javascript:alert('XSS')"
                };

                foreach (var xssPayload in xssPayloads)
                {
                    var inputElement = _driver.FindElement(By.Id(inputFieldId));
                    inputElement.Clear();
                    inputElement.SendKeys(xssPayload);

                    // Submit form
                    inputElement.SendKeys(Keys.Enter);

                    // Check if script executed
                    var pageSource = _driver.PageSource;

                    if (pageSource.Contains(xssPayload) && !pageSource.Contains("&lt;script&gt;"))
                    {
                        return true; // Potential XSS vulnerability
                    }
                }

                return false;
            }
            catch (Exception ex)
            {
                Console.WriteLine($"XSS test failed: {ex.Message}");
                return false;
            }
        }

        public async Task<bool> VerifySslCertificate(string url)
        {
            try
            {
                var handler = new HttpClientHandler
                {
                    ServerCertificateCustomValidationCallback = (message, cert, chain, errors) =>
                    {
                        // Check certificate validity
                        return errors == System.Net.Security.SslPolicyErrors.None &&
                               cert.Verify() &&
                               DateTime.Now >= cert.NotBefore &&
                               DateTime.Now <= cert.NotAfter;
                    }
                };

                using var client = new HttpClient(handler);
                var response = await client.GetAsync(url);

                return response.IsSuccessStatusCode;
            }
            catch
            {
                return false;
            }
        }

        public async Task<bool> CheckForInformationDisclosure(string url)
        {
            try
            {
                var response = await _httpClient.GetAsync(url);
                var content = await response.Content.ReadAsStringAsync();

                // Check for sensitive information in response
                var sensitivePatterns = new[]
                {
                    "stack trace",
                    "internal server error",
                    "database connection",
                    "connection string",
                    "api key",
                    "password"
                };

                return sensitivePatterns.Any(pattern => 
                    content.ToLower().Contains(pattern.ToLower()));
            }
            catch
            {
                return false;
            }
        }

        public void VerifySecurityHeaders(HttpResponseMessage response)
        {
            var requiredHeaders = new Dictionary<string, string>
            {
                ["X-Content-Type-Options"] = "nosniff",
                ["X-Frame-Options"] = "DENY",
                ["X-XSS-Protection"] = "1; mode=block",
                ["Strict-Transport-Security"] = "max-age=31536000; includeSubDomains"
            };

            foreach (var header in requiredHeaders)
            {
                if (response.Headers.TryGetValues(header.Key, out var values))
                {
                    values.First().Should().Be(header.Value, $"Security header {header.Key} should be set correctly");
                }
                else
                {
                    throw new Exception($"Missing security header: {header.Key}");
                }
            }
        }

        public async Task<bool> TestAuthenticationBypass(string protectedUrl)
        {
            try
            {
                // Try to access protected resource without authentication
                var response = await _httpClient.GetAsync(protectedUrl);

                // Should redirect to login or return 401/403
                return response.StatusCode == System.Net.HttpStatusCode.Redirect ||
                       response.StatusCode == System.Net.HttpStatusCode.Unauthorized ||
                       response.StatusCode == System.Net.HttpStatusCode.Forbidden;
            }
            catch
            {
                return false;
            }
        }
    }

    // Security-aware test scenarios
    public class SecurityAwareLoginTests
    {
        private readonly LoginPage _loginPage;
        private readonly ISecurityTester _securityTester;

        public SecurityAwareLoginTests(LoginPage loginPage, ISecurityTester securityTester)
        {
            _loginPage = loginPage;
            _securityTester = securityTester;
        }

        public async Task TestLoginSecurity()
        {
            // Test for SQL injection in username field
            var hasSqlInjection = await _securityTester.CheckForSqlInjectionVulnerability("username", "test");
            hasSqlInjection.Should().BeFalse("Login should be protected against SQL injection");

            // Test for XSS in username field
            var hasXss = await _securityTester.CheckForXssVulnerability("username", "test");
            hasXss.Should().BeFalse("Login should be protected against XSS");

            // Verify SSL certificate
            var hasValidSsl = await _securityTester.VerifySslCertificate(_loginPage.GetPageUrl());
            hasValidSsl.Should().BeTrue("Login page should use valid SSL certificate");

            // Test authentication bypass
            var isProtected = await _securityTester.TestAuthenticationBypass(_loginPage.GetDashboardUrl());
            isProtected.Should().BeTrue("Dashboard should require authentication");
        }
    }
}

// Custom Exception Classes
namespace Tests.Framework.Exceptions
{
    public class AutomationException : Exception
    {
        public string ScreenshotPath { get; set; }
        public string PageSource { get; set; }
        public DateTime ErrorTime { get; set; }

        public AutomationException(string message) : base(message)
        {
            ErrorTime = DateTime.Now;
        }

        public AutomationException(string message, Exception innerException) 
            : base(message, innerException)
        {
            ErrorTime = DateTime.Now;
        }
    }

    public class ElementNotFoundException : AutomationException
    {
        public By Locator { get; set; }
        public string PageName { get; set; }

        public ElementNotFoundException(string pageName, By locator) 
            : base($"Element not found on page '{pageName}': {locator}")
        {
            PageName = pageName;
            Locator = locator;
        }
    }

    public class TimeoutException : AutomationException
    {
        public int TimeoutSeconds { get; set; }
        public string Operation { get; set; }

        public TimeoutException(string operation, int timeoutSeconds)
            : base($"Operation '{operation}' timed out after {timeoutSeconds} seconds")
        {
            Operation = operation;
            TimeoutSeconds = timeoutSeconds;
        }
    }
}

// Error Handling Service
public interface IErrorHandler
{
    TResult ExecuteWithHandling<TResult>(Func<TResult> operation, string operationName);
    void ExecuteWithHandling(Action operation, string operationName);
    bool IsTransientError(Exception exception);
    void HandleError(Exception exception, IWebDriver driver = null);
}

public class ErrorHandler : IErrorHandler
{
    private readonly IScreenshotHelper _screenshotHelper;
    private readonly ITestLogger _logger;

    public ErrorHandler(IScreenshotHelper screenshotHelper, ITestLogger logger)
    {
        _screenshotHelper = screenshotHelper;
        _logger = logger;
    }

    public TResult ExecuteWithHandling<TResult>(Func<TResult> operation, string operationName)
    {
        try
        {
            return operation();
        }
        catch (Exception ex) when (IsTransientError(ex))
        {
            _logger.Warn($"Transient error in {operationName}, retrying: {ex.Message}");
            System.Threading.Thread.Sleep(1000);
            return operation(); // Single retry for transient errors
        }
        catch (Exception ex)
        {
            HandleError(ex);
            throw;
        }
    }

    public void ExecuteWithHandling(Action operation, string operationName)
    {
        ExecuteWithHandling<object>(() => 
        {
            operation();
            return null;
        }, operationName);
    }

    public bool IsTransientError(Exception exception)
    {
        return exception is WebDriverException ||
               exception is NoSuchElementException ||
               exception is StaleElementReferenceException ||
               exception is ElementClickInterceptedException ||
               (exception.InnerException != null && IsTransientError(exception.InnerException));
    }

    public void HandleError(Exception exception, IWebDriver driver = null)
    {
        _logger.Error($"Error handled: {exception.Message}", exception);

        if (driver != null)
        {
            try
            {
                var screenshotPath = _screenshotHelper.CaptureScreenshot(driver, $"error_{DateTime.Now:yyyyMMdd_HHmmss}");
                var pageSource = driver.PageSource;

                // Enhance exception with context
                if (exception is AutomationException automationEx)
                {
                    automationEx.ScreenshotPath = screenshotPath;
                    automationEx.PageSource = pageSource;
                }

                _logger.Info($"Screenshot captured: {screenshotPath}");
            }
            catch (Exception screenshotEx)
            {
                _logger.Warn($"Failed to capture screenshot: {screenshotEx.Message}");
            }
        }
    }
}

// Error Handling in Page Objects
public class SafeBasePage : BasePage
{
    protected readonly IErrorHandler ErrorHandler;

    public SafeBasePage(IWebDriver driver, IErrorHandler errorHandler) : base(driver)
    {
        ErrorHandler = errorHandler;
    }

    protected override void Click(IWebElement element)
    {
        ErrorHandler.ExecuteWithHandling(() => base.Click(element), $"Click element");
    }

    protected override void Type(IWebElement element, string text)
    {
        ErrorHandler.ExecuteWithHandling(() => base.Type(element, text), $"Type text: {text}");
    }

    public new IWebElement FindElement(By locator)
    {
        return ErrorHandler.ExecuteWithHandling(() => 
        {
            try
            {
                return base.FindElement(locator);
            }
            catch (NoSuchElementException)
            {
                throw new ElementNotFoundException(this.GetType().Name, locator);
            }
        }, $"Find element: {locator}");
    }
}

// Retry Policy Configuration
public class RetryPolicy
{
    public int MaxRetryCount { get; set; } = 3;
    public TimeSpan RetryInterval { get; set; } = TimeSpan.FromSeconds(2);
    public TimeSpan Timeout { get; set; } = TimeSpan.FromSeconds(30);
    public Func<Exception, bool> ShouldRetry { get; set; }

    public static RetryPolicy Default => new RetryPolicy
    {
        ShouldRetry = ex => ex is WebDriverException || 
                           ex is NoSuchElementException ||
                           ex is StaleElementReferenceException
    };

    public static RetryPolicy ForElementInteraction => new RetryPolicy
    {
        MaxRetryCount = 5,
        RetryInterval = TimeSpan.FromSeconds(1),
        ShouldRetry = ex => ex is ElementNotInteractableException ||
                           ex is ElementClickInterceptedException ||
                           ex is StaleElementReferenceException
    };
}

// Retry Service Implementation
public interface IRetryService
{
    TResult ExecuteWithRetry<TResult>(Func<TResult> operation, RetryPolicy policy = null);
    Task<TResult> ExecuteWithRetryAsync<TResult>(Func<Task<TResult>> operation, RetryPolicy policy = null);
    void ExecuteWithRetry(Action operation, RetryPolicy policy = null);
}

public class RetryService : IRetryService
{
    private readonly ITestLogger _logger;

    public RetryService(ITestLogger logger)
    {
        _logger = logger;
    }

    public TResult ExecuteWithRetry<TResult>(Func<TResult> operation, RetryPolicy policy = null)
    {
        policy ??= RetryPolicy.Default;
        var exceptions = new List<Exception>();

        for (int attempt = 1; attempt <= policy.MaxRetryCount; attempt++)
        {
            try
            {
                return operation();
            }
            catch (Exception ex) when (policy.ShouldRetry?.Invoke(ex) == true && attempt < policy.MaxRetryCount)
            {
                exceptions.Add(ex);
                _logger.Warn($"Attempt {attempt} failed, retrying in {policy.RetryInterval.TotalSeconds}s: {ex.Message}");

                if (attempt < policy.MaxRetryCount)
                {
                    Thread.Sleep(policy.RetryInterval);
                }
            }
        }

        throw new AggregateException($"Operation failed after {policy.MaxRetryCount} attempts", exceptions);
    }

    public async Task<TResult> ExecuteWithRetryAsync<TResult>(Func<Task<TResult>> operation, RetryPolicy policy = null)
    {
        policy ??= RetryPolicy.Default;
        var exceptions = new List<Exception>();

        for (int attempt = 1; attempt <= policy.MaxRetryCount; attempt++)
        {
            try
            {
                return await operation().ConfigureAwait(false);
            }
            catch (Exception ex) when (policy.ShouldRetry?.Invoke(ex) == true && attempt < policy.MaxRetryCount)
            {
                exceptions.Add(ex);
                _logger.Warn($"Attempt {attempt} failed, retrying in {policy.RetryInterval.TotalSeconds}s: {ex.Message}");

                if (attempt < policy.MaxRetryCount)
                {
                    await Task.Delay(policy.RetryInterval).ConfigureAwait(false);
                }
            }
        }

        throw new AggregateException($"Operation failed after {policy.MaxRetryCount} attempts", exceptions);
    }

    public void ExecuteWithRetry(Action operation, RetryPolicy policy = null)
    {
        ExecuteWithRetry<object>(() =>
        {
            operation();
            return null;
        }, policy);
    }
}

// Flaky Test Management
public class FlakyTestDetector
{
    private readonly Dictionary<string, TestFailureHistory> _testHistory;

    public FlakyTestDetector()
    {
        _testHistory = new Dictionary<string, TestFailureHistory>();
    }

    public bool IsFlakyTest(string testName, int maxFailures = 3, double failureRateThreshold = 0.3)
    {
        if (!_testHistory.ContainsKey(testName))
            return false;

        var history = _testHistory[testName];
        var failureRate = (double)history.FailureCount / history.TotalExecutions;

        return history.FailureCount >= maxFailures && failureRate >= failureRateThreshold;
    }

    public void RecordTestExecution(string testName, bool passed)
    {
        if (!_testHistory.ContainsKey(testName))
        {
            _testHistory[testName] = new TestFailureHistory();
        }

        var history = _testHistory[testName];
        history.TotalExecutions++;

        if (!passed)
        {
            history.FailureCount++;
            history.LastFailure = DateTime.Now;
        }
    }

    public List<string> GetFlakyTests()
    {
        return _testHistory
            .Where(kvp => IsFlakyTest(kvp.Key))
            .Select(kvp => kvp.Key)
            .ToList();
    }
}

public class TestFailureHistory
{
    public int TotalExecutions { get; set; }
    public int FailureCount { get; set; }
    public DateTime LastFailure { get; set; }
}

// Test Data Factory Pattern
public interface ITestDataFactory
{
    User CreateUser(UserType userType = UserType.Standard);
    Product CreateProduct(ProductCategory category = ProductCategory.General);
    Order CreateOrder(int itemCount = 1);
    string GetUniqueEmail();
    string GetUniqueUsername();
    T GetTestData<T>(string dataKey) where T : class;
}

public class TestDataFactory : ITestDataFactory
{
    private readonly Faker _faker;
    private readonly IConfiguration _configuration;

    public TestDataFactory(IConfiguration configuration)
    {
        _faker = new Faker();
        _configuration = configuration;
    }

    public User CreateUser(UserType userType = UserType.Standard)
    {
        var user = new User
        {
            Username = GetUniqueUsername(),
            Email = GetUniqueEmail(),
            FirstName = _faker.Name.FirstName(),
            LastName = _faker.Name.LastName(),
            Password = GenerateSecurePassword(),
            UserType = userType
        };

        // Apply user type specific properties
        switch (userType)
        {
            case UserType.Admin:
                user.Roles = new List<string> { "Admin", "User" };
                user.IsActive = true;
                break;
            case UserType.Premium:
                user.SubscriptionType = "Premium";
                user.SubscriptionExpiry = DateTime.Now.AddYears(1);
                break;
            default:
                user.Roles = new List<string> { "User" };
                break;
        }

        return user;
    }

    public Product CreateProduct(ProductCategory category = ProductCategory.General)
    {
        return new Product
        {
            Name = _faker.Commerce.ProductName(),
            Description = _faker.Commerce.ProductDescription(),
            Price = decimal.Parse(_faker.Commerce.Price(10, 1000)),
            Category = category,
            SKU = GenerateSku(),
            InStock = _faker.Random.Bool(0.8) // 80% chance of being in stock
        };
    }

    public Order CreateOrder(int itemCount = 1)
    {
        var order = new Order
        {
            OrderNumber = GenerateOrderNumber(),
            OrderDate = DateTime.Now,
            Items = new List<OrderItem>()
        };

        for (int i = 0; i < itemCount; i++)
        {
            order.Items.Add(new OrderItem
            {
                Product = CreateProduct(),
                Quantity = _faker.Random.Int(1, 5),
                UnitPrice = decimal.Parse(_faker.Commerce.Price(10, 500))
            });
        }

        order.TotalAmount = order.Items.Sum(item => item.Quantity * item.UnitPrice);

        return order;
    }

    public string GetUniqueEmail()
    {
        return $"test_{Guid.NewGuid():N}@test.com";
    }

    public string GetUniqueUsername()
    {
        return $"user_{Guid.NewGuid():N}";
    }

    public T GetTestData<T>(string dataKey) where T : class
    {
        var section = _configuration.GetSection($"TestData:{dataKey}");
        return section.Get<T>();
    }

    private string GenerateSecurePassword()
    {
        const string validChars = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ1234567890!@#$%^&*";
        var chars = new char[12];
        var random = new Random();

        for (int i = 0; i < chars.Length; i++)
        {
            chars[i] = validChars[random.Next(validChars.Length)];
        }

        return new string(chars);
    }

    private string GenerateSku()
    {
        return $"SKU-{_faker.Random.AlphaNumeric(8).ToUpper()}";
    }

    private string GenerateOrderNumber()
    {
        return $"ORD-{DateTime.Now:yyyyMMdd}-{_faker.Random.Number(1000, 9999)}";
    }
}

// Test Data Management Service
public interface ITestDataManager
{
    void InitializeTestData();
    void CleanupTestData();
    T GetTestEntity<T>(string identifier) where T : class;
    void StoreTestEntity<T>(string identifier, T entity) where T : class;
    string GenerateTestDataFile(string templateName, Dictionary<string, object> parameters);
}

public class TestDataManager : ITestDataManager
{
    private readonly Dictionary<string, object> _testEntities;
    private readonly ITestDataFactory _dataFactory;
    private readonly IDatabaseTestBase _database;

    public TestDataManager(ITestDataFactory dataFactory, IDatabaseTestBase database)
    {
        _testEntities = new Dictionary<string, object>();
        _dataFactory = dataFactory;
        _database = database;
    }

    public void InitializeTestData()
    {
        // Create baseline test data
        var adminUser = _dataFactory.CreateUser(UserType.Admin);
        StoreTestEntity("admin_user", adminUser);

        var testProduct = _dataFactory.CreateProduct();
        StoreTestEntity("test_product", testProduct);

        // Insert into database if needed
        _database.CreateUser(adminUser);
        // Additional initialization logic...
    }

    public void CleanupTestData()
    {
        // Cleanup test data from database
        foreach (var entity in _testEntities.Values)
        {
            if (entity is User user)
            {
                _database.CleanupTestData("Users", $"UserId = {user.UserId}");
            }
        }

        _testEntities.Clear();
    }

    public T GetTestEntity<T>(string identifier) where T : class
    {
        if (_testEntities.ContainsKey(identifier) && _testEntities[identifier] is T entity)
        {
            return entity;
        }

        throw new KeyNotFoundException($"Test entity '{identifier}' of type {typeof(T).Name} not found");
    }

    public void StoreTestEntity<T>(string identifier, T entity) where T : class
    {
        _testEntities[identifier] = entity;
    }

    public string GenerateTestDataFile(string templateName, Dictionary<string, object> parameters)
    {
        var templatePath = Path.Combine("TestData", "Templates", $"{templateName}.json");
        if (!File.Exists(templatePath))
        {
            throw new FileNotFoundException($"Test data template not found: {templatePath}");
        }

        var templateContent = File.ReadAllText(templatePath);

        // Replace placeholders with actual values
        foreach (var param in parameters)
        {
            templateContent = templateContent.Replace($"{{{param.Key}}}", param.Value?.ToString() ?? "");
        }

        var outputPath = Path.Combine("TestData", "Generated", $"{templateName}_{Guid.NewGuid():N}.json");
        Directory.CreateDirectory(Path.GetDirectoryName(outputPath));
        File.WriteAllText(outputPath, templateContent);

        return outputPath;
    }
}

// Configuration Service Interface
public interface IConfigurationService
{
    string GetValue(string key);
    T GetSection<T>(string sectionName) where T : class, new();
    string GetEnvironment();
    bool IsEnvironment(string environment);
    void ReloadConfiguration();
    Dictionary<string, string> GetAllSettings();
}

// Configuration Service Implementation
public class ConfigurationService : IConfigurationService
{
    private readonly IConfiguration _configuration;
    private readonly string _environment;

    public ConfigurationService()
    {
        _environment = Environment.GetEnvironmentVariable("ASPNETCORE_ENVIRONMENT") ?? "Production";

        _configuration = new ConfigurationBuilder()
            .SetBasePath(Directory.GetCurrentDirectory())
            .AddJsonFile("appsettings.json", optional: false, reloadOnChange: true)
            .AddJsonFile($"appsettings.{_environment}.json", optional: true, reloadOnChange: true)
            .AddEnvironmentVariables()
            .AddUserSecrets<Program>()
            .Build();
    }

    public string GetValue(string key)
    {
        return _configuration[key];
    }

    public T GetSection<T>(string sectionName) where T : class, new()
    {
        return _configuration.GetSection(sectionName).Get<T>() ?? new T();
    }

    public string GetEnvironment()
    {
        return _environment;
    }

    public bool IsEnvironment(string environment)
    {
        return string.Equals(_environment, environment, StringComparison.OrdinalIgnoreCase);
    }

    public void ReloadConfiguration()
    {
        // Configuration reloads automatically due to reloadOnChange: true
    }

    public Dictionary<string, string> GetAllSettings()
    {
        return _configuration.AsEnumerable().ToDictionary(kvp => kvp.Key, kvp => kvp.Value);
    }
}

