// Unified Mobile-Web Base Page
public abstract class UnifiedBasePage : IBasePage
{
    protected readonly AppiumDriver MobileDriver;
    protected readonly IWebDriver WebDriver;
    protected readonly PlatformContext Platform;
    protected readonly ITestLogger Logger;

    public UnifiedBasePage(PlatformContext platform, AppiumDriver mobileDriver, IWebDriver webDriver, ITestLogger logger)
    {
        Platform = platform;
        MobileDriver = mobileDriver;
        WebDriver = webDriver;
        Logger = logger;
    }

    protected IWebDriver GetDriver()
    {
        return Platform.IsMobile ? MobileDriver : WebDriver;
    }

    protected void ClickElement(By webLocator, string mobileLocator = null)
    {
        if (Platform.IsMobile && !string.IsNullOrEmpty(mobileLocator))
        {
            var element = MobileDriver.FindElement(By.XPath(mobileLocator));
            element.Click();
        }
        else
        {
            var element = WebDriver.FindElement(webLocator);
            element.Click();
        }
    }

    protected void EnterText(By webLocator, string text, string mobileLocator = null)
    {
        if (Platform.IsMobile && !string.IsNullOrEmpty(mobileLocator))
        {
            var element = MobileDriver.FindElement(By.XPath(mobileLocator));
            element.SendKeys(text);
        }
        else
        {
            var element = WebDriver.FindElement(webLocator);
            element.SendKeys(text);
        }
    }

    protected string GetText(By webLocator, string mobileLocator = null)
    {
        if (Platform.IsMobile && !string.IsNullOrEmpty(mobileLocator))
        {
            var element = MobileDriver.FindElement(By.XPath(mobileLocator));
            return element.Text;
        }
        else
        {
            var element = WebDriver.FindElement(webLocator);
            return element.Text;
        }
    }

    public abstract void WaitForPage();
    public abstract bool IsPageLoaded();
    public abstract string GetPageTitle();
}

