    private By WebUsernameField => By.Id("username");
    private By WebPasswordField => By.Id("password");
    private By WebLoginButton => By.Id("login-btn");

    // Mobile Locators
    private string MobileUsernameField => "//android.widget.EditText[@resource-id='username']";
    private string MobilePasswordField => "//android.widget.EditText[@resource-id='password']";
    private string MobileLoginButton => "//android.widget.Button[@text='LOGIN']";

    public UnifiedLoginPage(PlatformContext platform, AppiumDriver mobileDriver, IWebDriver webDriver, ITestLogger logger) 
        : base(platform, mobileDriver, webDriver, logger)
    {
    }

    public void EnterUsername(string username)
    {
        Logger.Info($"Entering username: {username}");
        EnterText(WebUsernameField, username, MobileUsernameField);
    }

    public void EnterPassword(string password)
    {
        Logger.Info("Entering password");
        EnterText(WebPasswordField, password, MobilePasswordField);
    }

    public UnifiedDashboardPage ClickLogin()
    {
        Logger.Info("Clicking login button");
        ClickElement(WebLoginButton, MobileLoginButton);

        return new UnifiedDashboardPage(Platform, MobileDriver, WebDriver, Logger);
    }

    public UnifiedDashboardPage Login(string username, string password)
    {
        EnterUsername(username);
        EnterPassword(password);

        if (Platform.IsMobile)
        {
            // Hide keyboard on mobile
            MobileDriver.HideKeyboard();
        }

        return ClickLogin();
    }

    public override void WaitForPage()
    {
        Logger.Info("Waiting for login page to load");

        if (Platform.IsMobile)
        {
            var wait = new WebDriverWait(MobileDriver, TimeSpan.FromSeconds(30));
            wait.Until(d => d.FindElement(By.XPath(MobileUsernameField)).Displayed);
        }
        else
        {
            var wait = new WebDriverWait(WebDriver, TimeSpan.FromSeconds(30));
            wait.Until(d => d.FindElement(WebUsernameField).Displayed);
        }
    }

    public override bool IsPageLoaded()
    {
        try
        {
            if (Platform.IsMobile)
            {
                return MobileDriver.FindElement(By.XPath(MobileUsernameField)).Displayed &&
                       MobileDriver.FindElement(By.XPath(MobilePasswordField)).Displayed;
            }
            else
            {
                return WebDriver.FindElement(WebUsernameField).Displayed &&
                       WebDriver.FindElement(WebPasswordField).Displayed;
            }
        }
        catch
        {
            return false;
        }
    }

    public override string GetPageTitle()
    {
        return Platform.IsMobile ? MobileDriver.Title : WebDriver.Title;
    }
}

// Cross-Platform Test Runner
public class CrossPlatformTestRunner
{
    private readonly ITestLogger _logger;
    private readonly IWebDriverFactory _webDriverFactory;
    private readonly IMobileDriverFactory _mobileDriverFactory;

    public CrossPlatformTestRunner(ITestLogger logger, IWebDriverFactory webDriverFactory, IMobileDriverFactory mobileDriverFactory)
    {
        _logger = logger;
        _webDriverFactory = webDriverFactory;
        _mobileDriverFactory = mobileDriverFactory;
    }

    public void RunCrossPlatformTest(Action<PlatformContext, IWebDriver, AppiumDriver> testAction, params PlatformContext[] platforms)
    {
        if (platforms.Length == 0)
        {
            platforms = new[]
            {
                new PlatformContext { IsMobile = false, PlatformType = PlatformType.Web },
                new PlatformContext { IsMobile = true, PlatformType = PlatformType.Android },
                new PlatformContext { IsMobile = true, PlatformType = PlatformType.iOS }
            };
        }

        var results = new Dictionary<PlatformContext, TestResult>();

        foreach (var platform in platforms)
        {
            IWebDriver webDriver = null;
            AppiumDriver mobileDriver = null;

            try
            {
                _logger.Info($"Starting test on platform: {platform.PlatformType}");

                if (platform.IsMobile)
                {
                    mobileDriver = _mobileDriverFactory.CreateDriver(platform.PlatformType);
                }
                else
                {
                    webDriver = _webDriverFactory.CreateDriver();
                }

                testAction(platform, webDriver, mobileDriver);

                results[platform] = new TestResult { Success = true };
                _logger.Info($"Test passed on platform: {platform.PlatformType}");
            }
            catch (Exception ex)
            {
                results[platform] = new TestResult { Success = false, Error = ex.Message };
                _logger.Error($"Test failed on platform: {platform.PlatformType}", ex);
            }
            finally
            {
                webDriver?.Quit();
                mobileDriver?.Quit();
            }
        }

        GenerateCrossPlatformReport(results);
    }

    private void GenerateCrossPlatformReport(Dictionary<PlatformContext, TestResult> results)
    {
        var passedPlatforms = results.Where(r => r.Value.Success).Select(r => r.Key.PlatformType).ToList();
        var failedPlatforms = results.Where(r => !r.Value.Success).Select(r => r.Key.PlatformType).ToList();

        _logger.Info($"Cross-platform test results: {passedPlatforms.Count} passed, {failedPlatforms.Count} failed");

        if (failedPlatforms.Any())
        {
            _logger.Warn($"Tests failed on platforms: {string.Join(", ", failedPlatforms)}");
        }
    }
}

// Performance Monitoring Service
public interface IPerformanceMonitor
{
    Task<PerformanceMetrics> MeasurePageLoad(string pageUrl);
    Task<PerformanceMetrics> MeasureAction(string actionName, Func<Task> action);
    Task<PerformanceMetrics> MeasureAction(string actionName, Action action);
    void AssertPerformanceThresholds(PerformanceMetrics metrics, PerformanceThresholds thresholds);
    Task StartContinuousMonitoring();
    Task<PerformanceReport> StopContinuousMonitoring();
}

public class PerformanceMonitor : IPerformanceMonitor
{
    private readonly IWebDriver _driver;
    private readonly ITestLogger _logger;
    private readonly List<PerformanceMetrics> _continuousMetrics;
    private bool _isMonitoring;

    public PerformanceMonitor(IWebDriver driver, ITestLogger logger)
    {
        _driver = driver;
        _logger = logger;
        _continuousMetrics = new List<PerformanceMetrics>();
    }

    public async Task<PerformanceMetrics> MeasurePageLoad(string pageUrl)
    {
        var stopwatch = Stopwatch.StartNew();

        try
        {
            _logger.Info($"Measuring page load performance for: {pageUrl}");

            // Navigate to page
            _driver.Navigate().GoToUrl(pageUrl);

            // Wait for page to load completely
            var wait = new WebDriverWait(_driver, TimeSpan.FromSeconds(30));
            wait.Until(d => ((IJavaScriptExecutor)d).ExecuteScript("return document.readyState").Equals("complete"));

            stopwatch.Stop();

            var metrics = new PerformanceMetrics
            {
                OperationName = $"Page Load: {pageUrl}",
                Duration = stopwatch.ElapsedMilliseconds,
                Timestamp = DateTime.Now,
                Metrics = await GetPerformanceMetrics()
            };

            _logger.Info($"Page load completed in {metrics.Duration}ms");

            return metrics;
        }
        catch (Exception ex)
        {
            stopwatch.Stop();
            _logger.Error($"Failed to measure page load performance for {pageUrl}", ex);
            throw;
        }
    }

    public async Task<PerformanceMetrics> MeasureAction(string actionName, Func<Task> action)
    {
        var stopwatch = Stopwatch.StartNew();

        try
        {
            _logger.Info($"Measuring performance for action: {actionName}");

            await action();

            stopwatch.Stop();

            var metrics = new PerformanceMetrics
            {
                OperationName = actionName,
                Duration = stopwatch.ElapsedMilliseconds,
                Timestamp = DateTime.Now
            };

            _logger.Info($"Action '{actionName}' completed in {metrics.Duration}ms");

            if (_isMonitoring)
            {
                _continuousMetrics.Add(metrics);
            }

            return metrics;
        }
        catch (Exception ex)
        {
            stopwatch.Stop();
            _logger.Error($"Failed to measure performance for action {actionName}", ex);
            throw;
        }
    }

    public async Task<PerformanceMetrics> MeasureAction(string actionName, Action action)
    {
        return await MeasureAction(actionName, () =>
        {
            action();
            return Task.CompletedTask;
        });
    }

    public void AssertPerformanceThresholds(PerformanceMetrics metrics, PerformanceThresholds thresholds)
    {
        _logger.Info($"Asserting performance thresholds for: {metrics.OperationName}");

        if (metrics.Duration > thresholds.MaxDuration)
        {
            throw new PerformanceThresholdException(
                $"Performance threshold exceeded for {metrics.OperationName}. " +
                $"Actual: {metrics.Duration}ms, Expected: <{thresholds.MaxDuration}ms");
        }

        // Additional threshold checks
        if (metrics.Metrics != null)
        {
            if (metrics.Metrics.ContainsKey("FirstContentfulPaint") && 
                metrics.Metrics["FirstContentfulPaint"] > thresholds.FirstContentfulPaint)
            {
                throw new PerformanceThresholdException(
                    $"First Contentful Paint threshold exceeded. " +
                    $"Actual: {metrics.Metrics["FirstContentfulPaint"]}ms, " +
                    $"Expected: <{thresholds.FirstContentfulPaint}ms");
            }

            if (metrics.Metrics.ContainsKey("LargestContentfulPaint") && 
                metrics.Metrics["LargestContentfulPaint"] > thresholds.LargestContentfulPaint)
            {
                throw new PerformanceThresholdException(
                    $"Largest Contentful Paint threshold exceeded. " +
                    $"Actual: {metrics.Metrics["LargestContentfulPaint"]}ms, " +
                    $"Expected: <{thresholds.LargestContentfulPaint}ms");
            }
        }

        _logger.Info("All performance thresholds met");
    }

    public async Task StartContinuousMonitoring()
    {
        _isMonitoring = true;
        _continuousMetrics.Clear();
        _logger.Info("Continuous performance monitoring started");

        await Task.CompletedTask;
    }

    public async Task<PerformanceReport> StopContinuousMonitoring()
    {
        _isMonitoring = false;

        var report = new PerformanceReport
        {
            Metrics = _continuousMetrics,
            StartTime = _continuousMetrics.FirstOrDefault()?.Timestamp ?? DateTime.Now,
            EndTime = DateTime.Now,
            TotalOperations = _continuousMetrics.Count
        };

        _logger.Info($"Continuous performance monitoring stopped. Collected {report.TotalOperations} metrics");

        return report;
    }

    private async Task<Dictionary<string, double>> GetPerformanceMetrics()
    {
        try
        {
            if (_driver is IDevTools)
            {
                var devTools = (IDevTools)_driver;
                var session = devTools.GetDevToolsSession();

                // Get performance metrics via DevTools
                // Implementation depends on specific DevTools version
                return new Dictionary<string, double>();
            }
        }
        catch (Exception ex)
        {
            _logger.Warn($"Failed to get detailed performance metrics: {ex.Message}");
        }

        return null;
    }
}

// Performance-Aware Test Example
public class PerformanceAwareLoginTest
{
    private readonly LoginPage _loginPage;
    private readonly IPerformanceMonitor _performanceMonitor;
    private readonly ITestLogger _logger;

    public PerformanceAwareLoginTest(LoginPage loginPage, IPerformanceMonitor performanceMonitor, ITestLogger logger)
    {
        _loginPage = loginPage;
        _performanceMonitor = performanceMonitor;
        _logger = logger;
    }

    public async Task TestLoginPerformance()
    {
        var performanceThresholds = new PerformanceThresholds
        {
            MaxDuration = 5000, // 5 seconds
            FirstContentfulPaint = 1500, // 1.5 seconds
            LargestContentfulPaint = 2500 // 2.5 seconds
        };

        try
        {
            // Measure page load performance
            var pageLoadMetrics = await _performanceMonitor.MeasurePageLoad(_loginPage.GetPageUrl());
            _performanceMonitor.AssertPerformanceThresholds(pageLoadMetrics, performanceThresholds);

            // Measure login action performance
            var loginMetrics = await _performanceMonitor.MeasureAction("User Login", async () =>
            {
                var dashboard = _loginPage.Login("testuser", "password");
                await Task.Delay(100); // Small delay for async operations
                dashboard.IsDashboardLoaded().Should().BeTrue();
            });

            _performanceMonitor.AssertPerformanceThresholds(loginMetrics, performanceThresholds);

            _logger.Info("Login performance test completed successfully");

        }
        catch (PerformanceThresholdException ex)
        {
            _logger.Error("Performance threshold violation detected", ex);
            throw;
        }
    }
}

public class PerformanceThresholdException : Exception
{
    public PerformanceThresholdException(string message) : base(message) { }
}

