// FlakyTestDetector.java
package com.example.utilities;

import java.util.HashMap;
import java.util.Map;

public class FlakyTestDetector {

    private static Map<String, TestExecutionHistory> testHistory = new HashMap<>();

    public static void recordTestExecution(String testName, boolean passed) {
        TestExecutionHistory history = testHistory.getOrDefault(testName, new TestExecutionHistory());
        history.totalExecutions++;

        if (!passed) {
            history.failureCount++;
            history.lastFailure = System.currentTimeMillis();
        }

        testHistory.put(testName, history);
    }

    public static boolean isFlakyTest(String testName, int maxFailures, double failureRateThreshold) {
        if (!testHistory.containsKey(testName)) {
            return false;
        }

        TestExecutionHistory history = testHistory.get(testName);
        double failureRate = (double) history.failureCount / history.totalExecutions;

        return history.failureCount >= maxFailures && failureRate >= failureRateThreshold;
    }

    public static void printFlakyTests() {
        System.out.println("\n=== Flaky Test Report ===");
        for (Map.Entry<String, TestExecutionHistory> entry : testHistory.entrySet()) {
            String testName = entry.getKey();
            TestExecutionHistory history = entry.getValue();
            double failureRate = (double) history.failureCount / history.totalExecutions;

            if (isFlakyTest(testName, 3, 0.3)) {
                System.out.println(String.format("Test: %s, Failures: %d/%d, Failure Rate: %.2f%%", 
                    testName, history.failureCount, history.totalExecutions, failureRate * 100));
            }
        }
    }

    static class TestExecutionHistory {
        int totalExecutions = 0;
        int failureCount = 0;
        long lastFailure = 0;
    }
}

