        // Discard old builds to save space
        buildDiscarder(logRotator(
            numToKeepStr: '20',
            artifactNumToKeepStr: '5',
            daysToKeepStr: '30'
        ))
    }

    stages {
        stage('Checkout and Setup') {
            steps {
                checkout([
                    $class: 'GitSCM',
                    branches: [[name: '*/main']],
                    extensions: [
                        // Clean after checkout
                        [$class: 'CleanBeforeCheckout'],
                        // Prune stale remote-tracking branches
                        [$class: 'PruneStaleBranch'],
                        // Sparse checkout for large repositories
                        [$class: 'SparseCheckoutPaths', 
                         sparseCheckoutPaths: [[
                            path: 'src/test/java'
                         ], [
                            path: 'src/test/resources'
                         ], [
                            path: 'pom.xml'
                         ]]]
                    ],
                    userRemoteConfigs: [[url: 'https://github.com/company/test-automation.git']]
                ])

                // Create necessary directories
                sh '''
                    mkdir -p target/screenshots
                    mkdir -p target/logs
                    mkdir -p target/allure-results
                    mkdir -p test-output/reports
                '''
            }
        }

        stage('Execute Tests') {
            steps {
                sh 'mvn clean test'
            }
        }

        stage('Archive Results') {
            steps {
                // Archive important test artifacts
                archiveArtifacts artifacts: 'target/screenshots/*.png, target/logs/*.log', 
                                allowEmptyArchive: true

                // Store test reports
                archiveArtifacts artifacts: 'target/surefire-reports/**/*.html, target/site/**/*', 
                                allowEmptyArchive: true
            }
        }
