        agent: 'any',
        timeout: '30m',
        parallelExecution: true,
        notifyOnFailure: true
    ]

    def finalConfig = defaults + config

    pipeline {
        agent { label finalConfig.agent }

        options {
            timeout(time: finalConfig.timeout.toInteger(), unit: 'MINUTES')
            buildDiscarder(logRotator(numToKeepStr: '20'))
        }

        stages {
            stage('Checkout') {
                steps {
                    checkout scm
                }
            }

            stage('Java Setup') {
                steps {
                    sh 'java -version'
                    sh 'mvn -version'
                }
            }

            stage('Unit Tests') {
                steps {
                    script {
                        if (finalConfig.parallelExecution) {
                            parallel {
                                'Core Unit Tests': {
                                    sh 'mvn test -Dtest=**/*Test -Dgroups=core'
                                }
                                'Service Unit Tests': {
                                    sh 'mvn test -Dtest=**/*Test -Dgroups=service'
                                }
                                'Util Unit Tests': {
                                    sh 'mvn test -Dtest=**/*Test -Dgroups=util'
                                }
                            }
                        } else {
                            sh 'mvn test -Dtest=**/*Test'
                        }
                    }
                }
            }

            stage('Code Coverage') {
