 */
def pythonIntegrationTestPipeline(Map config = [:]) {
    def defaults = [
        agent: 'python-agent',
        environment: 'qa',
        testMarkers: 'integration',
        generateAllure: true
    ]

    def finalConfig = defaults + config

    pipeline {
        agent { label finalConfig.agent }

        environment {
            TEST_ENV = finalConfig.environment
            PYTHONPATH = "${env.WORKSPACE}/src:${env.WORKSPACE}/tests"
        }

        stages {
            stage('Python Setup') {
                steps {
                    sh 'python --version'
                    sh 'pip --version'
                    sh 'pip install -r requirements.txt'
                    sh 'pip install -r test-requirements.txt'
                }
