            break
        case 'extended':
            config = ['chrome': 3, 'firefox': 2, 'edge': 1]
            break
        case 'mobile':
            config = ['chrome': 2, 'firefox': 1, 'android': 2, 'ios': 1]
            break
        case 'all':
            config = ['chrome': 4, 'firefox': 3, 'edge': 2, 'safari': 1, 'android': 2, 'ios': 1]
            break
    }

    return config
}

