// RESOURCE ALLOCATION AND OPTIMIZATION
pipeline {
    agent none

    parameters {
        choice(
            name: 'RESOURCE_STRATEGY',
            choices: ['balanced', 'performance', 'conservative', 'custom'],
            description: 'Resource allocation strategy'
        )
        string(
            name: 'MAX_MEMORY',
            defaultValue: '4g',
            description: 'Maximum memory per test process'
        )
        string(
            name: 'MAX_CPU',
            defaultValue: '2',
            description: 'Maximum CPU cores per test'
        )
    }

    stages {
        stage('Resource Assessment') {
            steps {
                script {
                    // Assess available resources
                    def resourceInfo = assessResources()
                    env.AVAILABLE_AGENTS = resourceInfo.agents
                    env.AVAILABLE_MEMORY = resourceInfo.memory
                    env.AVAILABLE_CPU = resourceInfo.cpu

                    echo "Available Resources: ${env.AVAILABLE_AGENTS} agents, ${env.AVAILABLE_MEMORY}MB memory, ${env.AVAILABLE_CPU} CPU cores"

                    // Calculate optimal resource allocation
                    def allocation = calculateResourceAllocation()
                    env.TEST_ALLOCATION = allocation
                }
            }
        }

        stage('Optimized Test Execution') {
            parallel {
                // Memory-intensive tests
                stage('Memory Intensive Tests') {
                    agent {
                        label "memory-high && ${env.TEST_ALLOCATION.memoryAgents.join(' || ')}"
                    }
                    steps {
                        script {
                            withEnv([
                                "JAVA_OPTS=-Xmx${params.MAX_MEMORY} -Xms1g",
                                "MAVEN_OPTS=-Xmx2g -Xms512m"
                            ]) {
                                // Java performance tests
                                sh 'mvn test -Dgroups=performance -Dtest.memory.limit=${params.MAX_MEMORY}'

                                // Python memory tests
                                sh 'pytest tests/performance/ -v --memory-limit=${params.MAX_MEMORY}'
                            }
                        }
                    }
                }

                // CPU-intensive tests
                stage('CPU Intensive Tests') {
                    agent {
                        label "cpu-high && ${env.TEST_ALLOCATION.cpuAgents.join(' || ')}"
                    }
                    steps {
                        script {
                            // Limit CPU usage
                            sh '''
                                # Java tests with CPU limits
                                taskset -c 0-${MAX_CPU} mvn test -Dgroups=cpu_intensive

                                # Python tests with CPU affinity
                                taskset -c 0-${MAX_CPU} pytest tests/benchmark/ -v
                            '''
                        }
                    }
                }

                // I/O intensive tests
                stage('I/O Intensive Tests') {
                    agent {
                        label "io-fast && ${env.TEST_ALLOCATION.ioAgents.join(' || ')}"
                    }
                    steps {
                        script {
                            // Tests requiring fast I/O
                            sh 'mvn test -Dgroups=database,file_io'
                            sh 'pytest tests/integration/ -v -m "database or filesystem"'
                        }
                    }
                }

                // Network-intensive tests
                stage('Network Intensive Tests') {
                    agent {
                        label "network-fast && ${env.TEST_ALLOCATION.networkAgents.join(' || ')}"
                    }
                    steps {
                        script {
                            // API and network tests
                            sh 'mvn test -Dgroups=api,network'
                            sh 'pytest tests/api/ tests/network/ -v'
                        }
                    }
                }
            }
        }

        stage('Dynamic Resource Scaling') {
            steps {
                script {
                    // Monitor resource usage and scale if needed
                    def resourceMetrics = monitorResourceUsage()

                    if (resourceMetrics.requiresScaling) {
                        echo "Scaling resources due to: ${resourceMetrics.scalingReason}"

                        // Scale up/down based on metrics
                        scaleResources(resourceMetrics)

                        // Re-execute any failed tests with additional resources
                        retryWithMoreResources()
                    }
                }
            }
        }
    }

    post {
        always {
            // Generate resource utilization report
            sh 'python scripts/generate_resource_report.py'

            // Clean up allocated resources
            cleanupResources()
        }
    }
}

// Resource assessment and allocation functions
def assessResources() {
    def agents = []
    def totalMemory = 0
    def totalCPU = 0

    // Query Jenkins for available agents
    def jenkins = Jenkins.instance
    jenkins.computers.each { computer ->
        if (computer.online && !computer.offline) {
            def node = computer.node
            if (node) {
                def agentInfo = [
                    name: node.displayName,
                    labels: node.labelString?.split(' ') ?: [],
                    available: true
                ]

                // Get system information
                def envVars = computer.environment
                agentInfo.memory = envVars['SYSTEM_TOTAL_MEMORY'] ?: '8192'
                agentInfo.cpu = envVars['SYSTEM_CPU_CORES'] ?: '4'

                agents << agentInfo
                totalMemory += agentInfo.memory.toInteger()
                totalCPU += agentInfo.cpu.toInteger()
            }
        }
    }

    return [
        agents: agents,
        memory: totalMemory,
        cpu: totalCPU,
        availableCount: agents.size()
    ]
}

def calculateResourceAllocation() {
    def allocation = [:]

    switch(params.RESOURCE_STRATEGY) {
        case 'balanced':
            allocation = balancedAllocation()
            break
        case 'performance':
            allocation = performanceAllocation()
            break
        case 'conservative':
            allocation = conservativeAllocation()
            break
        case 'custom':
            allocation = customAllocation()
            break
    }

    return allocation
}

def balancedAllocation() {
    def agents = env.AVAILABLE_AGENTS

    // Distribute agents evenly across test types
    def memoryAgents = agents.findAll { it.labels.contains('memory-high') }.take(2)
    def cpuAgents = agents.findAll { it.labels.contains('cpu-high') }.take(2)
    def ioAgents = agents.findAll { it.labels.contains('io-fast') }.take(2)
    def networkAgents = agents.findAll { it.labels.contains('network-fast') }.take(2)

    return [
        memoryAgents: memoryAgents*.name,
        cpuAgents: cpuAgents*.name,
        ioAgents: ioAgents*.name,
        networkAgents: networkAgents*.name,
        strategy: 'balanced'
    ]
}

def performanceAllocation() {
    def agents = env.AVAILABLE_AGENTS

    // Allocate more resources to critical paths
    def memoryAgents = agents.findAll { it.labels.contains('memory-high') }
    def cpuAgents = agents.findAll { it.labels.contains('cpu-high') }

    return [
        memoryAgents: memoryAgents*.name,
        cpuAgents: cpuAgents*.name,
        ioAgents: agents.findAll { it.labels.contains('io-fast') }*.name,
        networkAgents: agents.findAll { it.labels.contains('network-fast') }*.name,
        strategy: 'performance'
    ]
}

// Resource monitoring and scaling
def monitorResourceUsage() {
    def metrics = [
        cpuUsage: [],
        memoryUsage: [],
        diskIO: [],
        networkIO: []
    ]

    // Collect metrics from all agents
    env.AVAILABLE_AGENTS.each { agent ->
        def agentMetrics = getAgentMetrics(agent.name)
        metrics.cpuUsage << agentMetrics.cpu
        metrics.memoryUsage << agentMetrics.memory
        metrics.diskIO << agentMetrics.disk
        metrics.networkIO << agentMetrics.network
    }

    // Analyze for scaling needs
    def analysis = analyzeResourceMetrics(metrics)

    return analysis
}

def scaleResources(metrics) {
    if (metrics.scaleUp) {
        echo "Scaling up resources: ${metrics.scaleUp}"

        // Add more agents or resources
        switch(metrics.scalingReason) {
            case 'high_cpu':
                addCPUAgents(metrics.additionalCPUNeeded)
                break
            case 'high_memory':
                addMemoryAgents(metrics.additionalMemoryNeeded)
                break
            case 'bottleneck':
                addBalancedAgents(metrics.bottleneckType)
                break
        }
    } else if (metrics.scaleDown) {
        echo "Scaling down resources: ${metrics.scaleDown}"

        // Release unused resources
        releaseExcessResources()
    }
}

// Resource optimization utilities
def optimizeJavaMemory() {
    // Calculate optimal Java memory settings
    def availableMem = env.AVAILABLE_MEMORY.toInteger()
    def agentCount = env.AVAILABLE_AGENTS.size()

    def memoryPerAgent = availableMem / agentCount
    def heapSize = Math.min(memoryPerAgent * 0.7, params.MAX_MEMORY.toInteger())

    return [
        xmx: "${heapSize.toInteger()}m",
        xms: "${(heapSize * 0.25).toInteger()}m",
        metaspace: "${(heapSize * 0.25).toInteger()}m"
    ]
}

def optimizePythonResources() {
    // Python-specific resource optimization
    return [
        maxWorkers: Math.min(env.AVAILABLE_CPU.toInteger(), 8),
        memoryLimit: params.MAX_MEMORY,
        timeout: '300'
    ]
}

// Cleanup and resource management
def cleanupResources() {
    echo "Cleaning up allocated resources"

    // Stop any temporary agents
    sh '''
        # Clean up Docker containers
        docker ps -aq | xargs docker stop | xargs docker rm

        # Clean up temporary files
        find /tmp -name "jenkins-*" -mtime +1 -exec rm -rf {} +

        # Clear test caches
        mvn dependency:purge-local-repository -DactTransitively=false
        pip cache purge
    '''

    // Release cloud resources if using dynamic provisioning
    releaseCloudResources()
}

