                        testMetrics.duration_seconds = testResult.result.duration
                    }

                    // Write metrics to file for Prometheus
                    writeJSON file: 'test-metrics.json', json: testMetrics

                    // Push metrics to Prometheus
                    sh '''
                    curl -X POST ${PROMETHEUS_URL}/metrics/job/jenkins_tests/instance/${JOB_NAME} \
