    // Create cloud resources
    sh """
    terraform init -backend-config=env://TF_BACKEND_CONFIG
    terraform apply -auto-approve \
        -var "resource_prefix=${RESOURCE_PREFIX}" \
        -var "build_number=${env.BUILD_NUMBER}"
    """

    // Store environment details
    def outputs = sh(
        script: 'terraform output -json',
        returnStdout: true
    )

    writeJSON file: 'environment-info.json', json: readJSON(text: outputs)
}

def waitForEnvironmentReady() {
    def maxAttempts = 30
    def attempt = 0

    while (attempt < maxAttempts) {
        attempt++

        try {
            def health = sh(
                script: 'curl -s -o /dev/null -w "%{http_code}" ${APP_URL}/health',
                returnStdout: true
            ).trim()

            if (health == '200') {
                echo "Environment is ready after ${attempt} attempts"
                return true
            }
        } catch (Exception e) {
            echo "Health check attempt ${attempt} failed: ${e.message}"
        }

        sleep(30) // Wait 30 seconds between checks
    }

    error "Environment failed to become ready after ${maxAttempts} attempts"
}

def performHealthChecks() {
    def healthStatus = [
        overall: true,
        details: [:]
    ]

    // Application health
    def appHealth = sh(
        script: 'curl -s ${APP_URL}/health | jq -r .status',
        returnStdout: true
    ).trim()
    healthStatus.details.application = (appHealth == 'UP') ? 'healthy' : 'unhealthy'

    // Database health
    def dbHealth = sh(
        script: 'pg_isready -h ${DB_HOST} -p ${DB_PORT}',
        returnStatus: true
    ) == 0
    healthStatus.details.database = dbHealth ? 'healthy' : 'unhealthy'

    // External services
    def externalServices = ['redis', 'elasticsearch', 's3']
    externalServices.each { service ->
        def serviceHealth = checkServiceHealth(service)
        healthStatus.details[service] = serviceHealth
    }

    // Update overall status
    healthStatus.overall = !healthStatus.details.values().contains('unhealthy')

    return healthStatus
}

def cleanupEnvironment() {
    echo "Cleaning up environment for build ${env.BUILD_NUMBER}"

    // Stop application services
    sh 'docker-compose down -v --remove-orphans'

    // Clean up Kubernetes resources
    sh "kubectl delete namespace ${K8S_NAMESPACE} --wait=false"

    // Clean up cloud resources
    if (fileExists('terraform.tfstate')) {
        sh '''
        terraform destroy -auto-approve \
            -var "resource_prefix=${RESOURCE_PREFIX}" \
            -var "build_number=${env.BUILD_NUMBER}"
        '''
    }

    // Clean up test data
    sh 'python scripts/cleanup_test_data.py --db-url ${DB_URL}'

    // Remove temporary files
    sh 'rm -rf tmp/* logs/* test-results/tmp/*'

    echo "Environment cleanup completed"
}

