// Legacy system modernization pipeline with dual-track approach

/**
 * Legacy modernization pipeline supporting both monolith maintenance
 * and gradual migration to microservices
 */
def call(Map config) {
    pipeline {
        agent any

        parameters {
            choice(
                name: 'MODERNIZATION_PHASE',
                choices: ['monolith', 'strangler', 'microservice'],
                description: 'Current modernization phase'
            )
            booleanParam(
                name: 'RUN_LEGACY_TESTS',
                defaultValue: true,
                description: 'Execute legacy test suite'
            )
            booleanParam(
                name: 'RUN_MODERN_TESTS',
                defaultValue: true,
                description: 'Execute modern test suite'
            )
        }

        environment {
            MODERNIZATION_PHASE = params.MODERNIZATION_PHASE
            LEGACY_APP_VERSION = '2.1.0'
            MODERN_APP_VERSION = '1.0.0'

            // Feature flags for gradual migration
            FEATURE_FLAGS = '{"new_payment_service": false, "modern_ui": true, "microservice_auth": false}'
        }

        stages {
            stage('Legacy System Build') {
                when {
                    expression { params.MODERNIZATION_PHASE in ['monolith', 'strangler'] }
                }
                steps {
                    script {
                        legacyBuild.buildMonolith(
                            version: env.LEGACY_APP_VERSION,
                            environment: 'production'
                        )
                    }
                }
            }

            stage('Modern System Build') {
                when {
                    expression { params.MODERNIZATION_PHASE in ['strangler', 'microservice'] }
                }
                steps {
                    script {
                        modernBuild.buildMicroservices(
                            version: env.MODERN_APP_VERSION,
                            services: getActiveMicroservices()
                        )
                    }
                }
            }

            stage('Dual Testing Strategy') {
                parallel {
                    stage('Legacy Test Suite') {
                        when {
                            expression { params.RUN_LEGACY_TESTS && params.MODERNIZATION_PHASE in ['monolith', 'strangler'] }
                        }
                        steps {
                            script {
                                legacyTesting.runComprehensiveSuite(
                                    environment: 'legacy-test',
                                    testGroups: ['smoke', 'regression', 'integration']
                                )
                            }
                        }
                    }

                    stage('Modern Test Suite') {
                        when {
                            expression { params.RUN_MODERN_TESTS && params.MODERNIZATION_PHASE in ['strangler', 'microservice'] }
                        }
                        steps {
                            script {
                                modernTesting.runMicroserviceTests(
                                    services: getActiveMicroservices(),
                                    testTypes: ['unit', 'contract', 'integration']
                                )
                            }
                        }
                    }

                    stage('Migration Validation') {
                        when {
                            expression { params.MODERNIZATION_PHASE == 'strangler' }
                        }
                        steps {
                            script {
                                migrationTesting.validateFeatureFlags(
                                    flags: readJSON(text: env.FEATURE_FLAGS)
                                )
                                migrationTesting.compareBehavior(
                                    legacyVersion: env.LEGACY_APP_VERSION,
                                    modernVersion: env.MODERN_APP_VERSION
                                )
                            }
                        }
                    }
                }
            }

            stage('Dual Deployment') {
                steps {
                    script {
                        switch(params.MODERNIZATION_PHASE) {
                            case 'monolith':
                                legacyDeployment.deployMonolith(
                                    version: env.LEGACY_APP_VERSION,
                                    featureFlags: env.FEATURE_FLAGS
                                )
                                break
                            case 'strangler':
                                legacyDeployment.deployMonolith(
                                    version: env.LEGACY_APP_VERSION,
                                    featureFlags: env.FEATURE_FLAGS
                                )
                                modernDeployment.deployMicroservices(
                                    version: env.MODERN_APP_VERSION,
                                    services: getActiveMicroservices(),
                                    featureFlags: env.FEATURE_FLAGS
                                )
                                break
                            case 'microservice':
                                modernDeployment.deployMicroservices(
                                    version: env.MODERN_APP_VERSION,
                                    services: getActiveMicroservices(),
                                    featureFlags: env.FEATURE_FLAGS
                                )
                                break
                        }
                    }
                }
            }

            stage('Business Continuity Validation') {
                steps {
                    script {
                        businessValidation.verifyCriticalFlows(
                            modernizationPhase: params.MODERNIZATION_PHASE,
                            featureFlags: env.FEATURE_FLAGS
                        )

                        // Compare key business metrics between old and new
                        if (params.MODERNIZATION_PHASE == 'strangler') {
                            businessValidation.compareMetrics(
                                legacySystem: true,
                                modernSystem: true
                            )
                        }
                    }
                }
            }

            stage('Rollback Preparation') {
                steps {
                    script {
                        // Always maintain rollback capability during modernization
                        rollbackManagement.prepareRollbackPlan(
                            modernizationPhase: params.MODERNIZATION_PHASE,
                            currentVersions: [
                                legacy: env.LEGACY_APP_VERSION,
                                modern: env.MODERN_APP_VERSION
                            ]
                        )
                    }
                }
            }
        }

        post {
            always {
                script {
                    // Modernization progress tracking
                    modernizationTracking.recordDeployment(
                        phase: params.MODERNIZATION_PHASE,
                        legacyVersion: env.LEGACY_APP_VERSION,
                        modernVersion: env.MODERN_APP_VERSION,
                        featureFlags: env.FEATURE_FLAGS
                    )
                }
            }
            success {
                script {
                    // Update modernization dashboard
                    modernizationDashboard.updateProgress(
                        phase: params.MODERNIZATION_PHASE,
                        status: 'success'
                    )

                    // Notify stakeholders
                    modernizationNotifications.sendSuccess(
                        phase: params.MODERNIZATION_PHASE,
                        buildUrl: env.BUILD_URL
                    )
                }
            }
            failure {
                script {
                    // Automated rollback based on modernization phase
                    switch(params.MODERNIZATION_PHASE) {
                        case 'strangler':
                            rollbackManagement.rollbackToLegacy()
                            break
                        case 'microservice':
                            rollbackManagement.rollbackToPreviousVersion()
                            break
                    }

                    // Failure analysis for modernization learning
                    modernizationAnalysis.recordFailure(
                        phase: params.MODERNIZATION_PHASE,
                        failureReason: currentBuild.result
                    )
                }
            }
        }
    }
}

// Helper functions for legacy modernization
def getActiveMicroservices() {
    def featureFlags = readJSON(text: env.FEATURE_FLAGS)
    def activeServices = []

    if (featureFlags.new_payment_service) {
        activeServices << 'payment-service'
    }
    if (featureFlags.microservice_auth) {
        activeServices << 'auth-service'
    }

    // Always include base services
    activeServices << 'user-service'
    activeServices << 'product-service'

    return activeServices
}

