        Map<String, Object> fields = new HashMap<>();
        fields.put("project", Map.of("key", projectKey));
        fields.put("summary", summary);
        fields.put("issuetype", Map.of("name", zephyrTestIssueType));

        // Zephyr-specific fields
        fields.put("customfield_10100", description); // Test Description
        fields.put("customfield_10101", String.join("\n", steps)); // Test Steps
        fields.put("customfield_10102", String.join("\n", expectedResults)); // Expected Results

        // Create issue
        Promise<Issue> issuePromise = jiraClient.getIssueClient()
            .createIssue(fields);

        Issue issue = issuePromise.claim();
