public class LoginSteps {

    private WebDriver driver;
    private LoginPage loginPage;
    private DashboardPage dashboardPage;

    @Before
    public void setUp() {
        WebDriverManager.chromedriver().setup();
        driver = new ChromeDriver();
        driver.manage().window().maximize();
        loginPage = new LoginPage(driver);
        dashboardPage = new DashboardPage(driver);
    }

    @Given("the application is running")
    public void the_application_is_running() {
        // Application URL can be configured in properties file
        driver.get("https://example.com");
    }

    @Given("I am on the login page")
    public void i_am_on_the_login_page() {
        Assert.assertTrue("Not on login page", 
            loginPage.isLoginPageDisplayed());
    }

    @When("I enter username {string} and password {string}")
    public void i_enter_username_and_password(String username, String password) {
        loginPage.enterUsername(username);
        loginPage.enterPassword(password);
    }

    @When("I click the login button")
    public void i_click_the_login_button() {
        loginPage.clickLoginButton();
    }

    @Then("I should be redirected to the dashboard page")
    public void i_should_be_redirected_to_the_dashboard_page() {
        Assert.assertTrue("Not on dashboard page",
            dashboardPage.isDashboardDisplayed());
    }

    @Then("I should see welcome message {string}")
    public void i_should_see_welcome_message(String expectedMessage) {
        String actualMessage = dashboardPage.getWelcomeMessage();
        Assert.assertEquals("Welcome message mismatch", 
