public class ExcelTemplateManager {

    public static void createTestDataTemplate(String filePath) {
        try (Workbook workbook = new XSSFWorkbook()) {

            // Create TestCases sheet
            Sheet testCaseSheet = workbook.createSheet("TestCases");
            createHeaderRow(testCaseSheet, 
                "TestCaseID", "Description", "RunMode", "Priority", "Category");

            // Create TestData sheet
            Sheet testDataSheet = workbook.createSheet("TestData");
            createHeaderRow(testDataSheet,
                "TestCaseID", "DataID", "Username", "Password", "ExpectedResult");

            // Create Configuration sheet
            Sheet configSheet = workbook.createSheet("Configuration");
            createHeaderRow(configSheet, "Key", "Value", "Description");

            // Write to file
            try (FileOutputStream fos = new FileOutputStream(filePath)) {
                workbook.write(fos);
            }

        } catch (IOException e) {
            throw new RuntimeException("Failed to create template: " + e.getMessage());
        }
    }

    private static void createHeaderRow(Sheet sheet, String... headers) {
        Row headerRow = sheet.createRow(0);
        for (int i = 0; i < headers.length; i++) {
            headerRow.createCell(i).setCellValue(headers[i]);
        }
    }
}

