public static void validateTestData(String sheetName) {
    List<Map<String, String>> testData = ExcelUtils.getTestDataAsMap(sheetName);
    List<String> errors = new ArrayList<>();

    for (int i = 0; i < testData.size(); i++) {
        Map<String, String> row = testData.get(i);
        int rowNum = i + 2; // +2 for header and 1-based indexing

        // Check required fields
        if (isEmpty(row.get("TestCaseID"))) {
            errors.add("Row " + rowNum + ": TestCaseID is required");
        }

        if (isEmpty(row.get("Username")) && isEmpty(row.get("Password"))) {
            errors.add("Row " + rowNum + ": Either Username or Password is required");
        }

        // Add more validation rules as needed
    }

    if (!errors.isEmpty()) {
        throw new RuntimeException("Test data validation failed:\\n" + 
            String.join("\\n", errors));
    }
}

public static Map<String, String> sanitizeData(Map<String, String> data) {
    Map<String, String> sanitized = new HashMap<>();

    for (Map.Entry<String, String> entry : data.entrySet()) {
        String key = entry.getKey();
        String value = entry.getValue() != null ? 
            entry.getValue().trim() : "";

        // Handle empty strings
        if (value.isEmpty()) {
            value = getDefaultValue(key);
        }

        sanitized.put(key, value);
    }

    return sanitized;
}

