public class BaseIntegratedTest {

    protected WebDriver driver;
    protected RequestSpecification apiRequest;
    protected Connection dbConnection;
    protected TestDataFactory testData;
    protected static ExtentReports extent;
    protected ExtentTest test;

    @BeforeSuite
    public void beforeSuite() {
        // Initialize reporting
        extent = ReportUtils.initExtentReport();

        // Initialize database connection
        dbConnection = DbUtils.getConnection();

        // Initialize test data factory
        testData = new TestDataFactory();
    }

    @BeforeMethod
    public void setUp(Method method) {
        // Create test in report
        test = extent.createTest(method.getName());

        // Initialize API client
        apiRequest = ApiUtils.getDefaultRequest()
            .filter(new RequestLoggingFilter())
            .filter(new ResponseLoggingFilter());

        // Initialize WebDriver
        driver = WebDriverUtils.createDriver();
        driver.manage().window().maximize();

        // Setup test context
        TestContext.setDriver(driver);
        TestContext.setApiRequest(apiRequest);
        TestContext.setDbConnection(dbConnection);
        TestContext.setExtentTest(test);
    }

    @AfterMethod
    public void tearDown(ITestResult result) {
        // Log test result
        if (result.getStatus() == ITestResult.FAILURE) {
            test.fail("Test failed: " + result.getThrowable());
            // Capture screenshot for UI tests
            if (driver != null) {
                String screenshotPath = WebDriverUtils.captureScreenshot(driver, result.getName());
                test.addScreenCaptureFromPath(screenshotPath);
            }
        } else if (result.getStatus() == ITestResult.SUCCESS) {
            test.pass("Test passed");
        }

        // Cleanup test data
        cleanupTestData();

        // Close WebDriver
        if (driver != null) {
            driver.quit();
        }
    }

    @AfterSuite
    public void afterSuite() throws SQLException {
        // Close database connection
        if (dbConnection != null && !dbConnection.isClosed()) {
            dbConnection.close();
        }

        // Flush extent reports
        if (extent != null) {
            extent.flush();
        }
    }

    protected void cleanupTestData() {
        // Implementation for cleaning up test data created during test
        try {
            DbUtils.cleanupTestData(dbConnection, testData.getTestRunId());
        } catch (SQLException e) {
            test.warning("Failed to cleanup test data: " + e.getMessage());
        }
    }
}

public class UserApiClient {

    private static final String BASE_URL = "https://api.example.com";
    private static final String USERS_ENDPOINT = "/api/users";

    public static User createUser(User user) {
        return given()
            .baseUri(BASE_URL)
            .contentType(ContentType.JSON)
            .body(user)
            .when()
            .post(USERS_ENDPOINT)
            .then()
            .statusCode(201)
            .extract()
            .as(User.class);
    }

    public static User getUserById(int userId) {
        return given()
            .baseUri(BASE_URL)
            .pathParam("id", userId)
            .when()
            .get(USERS_ENDPOINT + "/{id}")
            .then()
            .statusCode(200)
            .extract()
            .as(User.class);
    }

    public static Response updateUser(int userId, User user) {
        return given()
            .baseUri(BASE_URL)
            .pathParam("id", userId)
            .contentType(ContentType.JSON)
            .body(user)
            .when()
            .put(USERS_ENDPOINT + "/{id}")
            .then()
            .extract()
            .response();
    }

    public static boolean deleteUser(int userId) {
        return given()
            .baseUri(BASE_URL)
            .pathParam("id", userId)
            .when()
            .delete(USERS_ENDPOINT + "/{id}")
            .then()
            .statusCode(204)
            .extract()
            .path("");
    }

    public static List<User> getAllUsers() {
        return given()
            .baseUri(BASE_URL)
            .when()
            .get(USERS_ENDPOINT)
            .then()
            .statusCode(200)
            .extract()
            .jsonPath()
            .getList("", User.class);
    }
}

public class UserRepository {

    private Connection connection;

    public UserRepository(Connection connection) {
        this.connection = connection;
    }

    public UserEntity createUser(UserEntity user) throws SQLException {
        String sql = "INSERT INTO users (username, email, first_name, last_name, created_date) " +
                    "VALUES (?, ?, ?, ?, ?)";

        try (PreparedStatement stmt = connection.prepareStatement(sql, Statement.RETURN_GENERATED_KEYS)) {
            stmt.setString(1, user.getUsername());
            stmt.setString(2, user.getEmail());
            stmt.setString(3, user.getFirstName());
            stmt.setString(4, user.getLastName());
            stmt.setTimestamp(5, new Timestamp(System.currentTimeMillis()));

            int affectedRows = stmt.executeUpdate();
            if (affectedRows == 0) {
                throw new SQLException("Creating user failed, no rows affected.");
            }

            try (ResultSet generatedKeys = stmt.getGeneratedKeys()) {
                if (generatedKeys.next()) {
                    user.setId(generatedKeys.getInt(1));
                } else {
                    throw new SQLException("Creating user failed, no ID obtained.");
                }
            }
        }
        return user;
    }

    public UserEntity getUserById(int userId) throws SQLException {
        String sql = "SELECT * FROM users WHERE id = ?";

        try (PreparedStatement stmt = connection.prepareStatement(sql)) {
            stmt.setInt(1, userId);

            try (ResultSet rs = stmt.executeQuery()) {
                if (rs.next()) {
                    return mapResultSetToUser(rs);
                }
            }
        }
        return null;
    }

    public boolean deleteUser(int userId) throws SQLException {
        String sql = "DELETE FROM users WHERE id = ?";

        try (PreparedStatement stmt = connection.prepareStatement(sql)) {
            stmt.setInt(1, userId);
            return stmt.executeUpdate() > 0;
        }
    }

    public List<UserEntity> getUsersByEmail(String email) throws SQLException {
        String sql = "SELECT * FROM users WHERE email = ?";
        List<UserEntity> users = new ArrayList<>();

        try (PreparedStatement stmt = connection.prepareStatement(sql)) {
            stmt.setString(1, email);

            try (ResultSet rs = stmt.executeQuery()) {
                while (rs.next()) {
                    users.add(mapResultSetToUser(rs));
                }
            }
        }
        return users;
    }

    public int getUserCount() throws SQLException {
        String sql = "SELECT COUNT(*) FROM users";

        try (PreparedStatement stmt = connection.prepareStatement(sql);
             ResultSet rs = stmt.executeQuery()) {
            if (rs.next()) {
                return rs.getInt(1);
            }
        }
        return 0;
    }

    private UserEntity mapResultSetToUser(ResultSet rs) throws SQLException {
        UserEntity user = new UserEntity();
        user.setId(rs.getInt("id"));
        user.setUsername(rs.getString("username"));
        user.setEmail(rs.getString("email"));
        user.setFirstName(rs.getString("first_name"));
        user.setLastName(rs.getString("last_name"));
        user.setCreatedDate(rs.getTimestamp("created_date"));
        return user;
    }
}

