public void validateUserConsistency(int userId) {
    // Get user data from all layers simultaneously
    CompletableFuture<User> apiUserFuture = CompletableFuture.supplyAsync(
        () -> UserApiClient.getUserById(userId));
    CompletableFuture<UserEntity> dbUserFuture = CompletableFuture.supplyAsync(
        () -> userRepository.getUserById(userId));
    CompletableFuture<String> uiUserNameFuture = CompletableFuture.supplyAsync(
        () -> profilePage.getDisplayedUserName());

    // Combine and validate
    CompletableFuture.allOf(apiUserFuture, dbUserFuture, uiUserNameFuture).join();

    User apiUser = apiUserFuture.join();
    UserEntity dbUser = dbUserFuture.join();
    String uiUserName = uiUserNameFuture.join();

    // Cross-layer validation
    Assert.assertEquals(apiUser.getUsername(), dbUser.getUsername(), 
        "API and DB usernames should match");
    Assert.assertEquals(apiUser.getUsername(), uiUserName, 
        "API and UI usernames should match");
}

public void conditionalUserValidation(int userId) {
    // Check API response time
    long startTime = System.currentTimeMillis();
    User apiUser = UserApiClient.getUserById(userId);
    long apiResponseTime = System.currentTimeMillis() - startTime;

    if (apiResponseTime < 1000) {
        // API is fast, use API for validation
        validateUserViaAPI(apiUser);
    } else {
        // API is slow, use database for validation
        validateUserViaDatabase(userId);
    }

    // Always do basic UI validation
    validateUserViaUI(userId);
}

public void testUserRegistrationRollback() {
    // Start transaction
    dbConnection.setAutoCommit(false);

    try {
        // Create user via API
        User user = UserApiClient.createUser(testData.createTestUser());

        // Verify user creation
        Assert.assertNotNull(UserApiClient.getUserById(user.getId()));

        // Simulate failure scenario
        throw new RuntimeException("Simulated business rule violation");

    } catch (Exception e) {
        // Rollback transaction
        dbConnection.rollback();

        // Verify rollback across all layers
        Assert.assertNull(UserApiClient.getUserById(user.getId()), 
            "User should not exist in API after rollback");
        Assert.assertNull(userRepository.getUserById(user.getId()), 
            "User should not exist in DB after rollback");
    } finally {
        dbConnection.setAutoCommit(true);
    }
}

